/**
 * Подключаем заголовочные файлы модуля
 */
#include <codec/yaml/reader.hpp>

/**
 * Используем стандартное пространство имён
 */
using namespace std;

/**
 * Используем пространство имён контейнера YAML
 */
using namespace awh::codec::yaml;

/**
 * @brief Внутренние помощники потокового чтения
 *
 */
namespace {
	/**
	 * Начало меток типов, описанием заданных
	 *
	 * @note Сокращение `!!` раскрывается именно им, и описанием оно закреплено: правится
	 *       начало это лишь директивой `%TAG !! ...`, объявленной самим текстом
	 */
	static constexpr string_view STANDARD_TAG = "tag:yaml.org,2002:";
	/**
	 * @brief Функция проверки знака на принадлежность к пробельным
	 *
	 * @param letter проверяемый знак
	 * @return       признак принадлежности знака к пробельным
	 *
	 */
	static bool spacing(const char letter) noexcept {
		// Выводим признак принадлежности знака к пробельным
		return ((letter == ' ') || (letter == '\t'));
	}
	/**
	 * @brief Функция снятия пробельной обвязки с конца записи
	 *
	 * @param text обрезаемая запись
	 * @return     запись без пробельной обвязки в конце
	 *
	 */
	static string_view trimmed(const string_view text) noexcept {
		// Длина записи без пробельной обвязки
		size_t length = text.size();
		/**
		 * Выполняем снятие пробельных знаков с конца записи
		 */
		while((length > 0) && spacing(text[length - 1]))
			// Выполняем укорочение записи на один знак
			length--;
		// Выводим запись без пробельной обвязки в конце
		return text.substr(0, length);
	}
	/**
	 * @brief Функция снятия пробельной обвязки с обеих сторон записи
	 *
	 * @param text обрезаемая запись
	 * @return     запись без пробельной обвязки
	 *
	 */
	static string_view stripped(const string_view text) noexcept {
		// Смещение начала записи без пробельной обвязки
		size_t offset = 0;
		/**
		 * Выполняем снятие пробельных знаков с начала записи
		 */
		while((offset < text.size()) && spacing(text[offset]))
			// Выполняем переход к следующему знаку записи
			offset++;
		// Выводим запись без пробельной обвязки
		return trimmed(text.substr(offset));
	}
	/**
	 * @brief Функция розыска конца очередной строки накопителя
	 *
	 * @param buffer   накопитель разбираемого текста
	 * @param from     смещение, с какого розыск ведётся
	 * @param sealed   признак того, что накопителю прирасти уже нечем
	 * @param deferred переменная, куда помещается признак отложенного решения
	 * @return         смещение знака конца строки либо `npos`, если его нет
	 *
	 * @details Описание YAML 1.2 числит концом строки правилом `b-char` три написания:
	 * перевод строки, возврат каретки с переводом за ним и возврат каретки одинокий.
	 * Розыск оттого ведётся по обоим знакам, а ближайший из найденных и есть конец
	 * строки. Прежде искался один лишь перевод, и возврат одинокий концом строки не
	 * считался вовсе: написание `- \r\r\n` отдавало запись со значением `\r`, а метка
	 * `&ab\ru` вбирала возврат в имя своё
	 *
	 * @warning Возврат каретки, стоящий ПОСЛЕДНИМ знаком накопителя, решения не
	 *          принимает, покуда текст не окончен: следующий кусок вправе принести
	 *          перевод строки, и тогда возврат одиноким не является вовсе. Решив
	 *          сейчас, розыск поставил бы исход разбора в зависимость от нарезки
	 *          текста на куски. Отсрочка эта одного рода с отсрочкою строки, перевода
	 *          не имеющей, - той, что стоит ниже по ходу подачи
	 *
	 * @note Судится здесь окончание текста, а не признак `complete`: последний несёт
	 *       ещё и удачу приведения кодировки, и при провале приведения отсрочка
	 *       держалась бы вечно - накопитель прирасти уже не может. Правило это одно с
	 *       правилом склейки строк, стоящим ниже
	 */
	static size_t terminator(const string & buffer, const size_t from, const bool sealed, bool & deferred) noexcept {
		// Выполняем сброс признака отложенного решения
		deferred = false;
		// Разыскиваем знак перевода строки
		const size_t position = buffer.find('\n', from);
		// Разыскиваем знак возврата каретки
		size_t carriage = buffer.find('\r', from);
		/**
		 * Выполняем розыск возврата каретки одинокого
		 */
		while(carriage != string::npos){
			/**
			 * Если за возвратом каретки стоит ещё хотя бы один знак
			 */
			if((carriage + 1) < buffer.size()){
				/**
				 * Если за возвратом каретки стоит перевод строки
				 *
				 * @note Пара эта концом строки является переводом своим, а не возвратом:
				 *       возврат снимается с конца строки ниже по ходу разбора
				 */
				if(buffer.at(carriage + 1) == '\n'){
					// Выполняем переход к следующему возврату каретки
					carriage = buffer.find('\r', (carriage + 2));
					// Выполняем переход к следующему обороту розыска
					continue;
				}
				// Выходим из розыска: возврат каретки одинок
				break;
			}
			/**
			 * Если накопителю прирасти ещё есть чем
			 *
			 * @warning Отсрочка объявляется лишь тогда, когда перевода строки прежде
			 *          возврата в накопителе нет: строка, переводом уже закрытая,
			 *          разбору подлежит немедля, и держать её ради возврата, стоящего
			 *          за нею, нельзя. Написание `[]A\n\r` с отсрочкою безусловной
			 *          теряло строку `[]A` целиком, а отказ её подменялся отказом
			 *          приведения кодировки
			 */
			if(!sealed){
				/**
				 * Если перевод строки стоит прежде возврата каретки
				 */
				if((position != string::npos) && (position < carriage))
					// Выводим смещение знака перевода строки
					return position;
				// Запоминаем признак отложенного решения
				deferred = true;
				// Выводим отсутствие конца строки
				return string::npos;
			}
			// Выходим из розыска: возврат каретки одинок и последний
			break;
		}
		/**
		 * Если возврат каретки одинокий стоит прежде перевода строки
		 */
		if((carriage != string::npos) && ((position == string::npos) || (carriage < position)))
			// Выводим смещение возврата каретки одинокого
			return carriage;
		// Выводим смещение знака перевода строки
		return position;
	}
	/**
	 * @brief Функция проверки строки на незакрытую ограду значения
	 *
	 * @param line проверяемая строка
	 * @return     признак того, что строка открывает ограду и не закрывает её
	 *
	 * @details Значение огранённое вправе стоять в несколько строк, и строки эти надлежит
	 *          свести в одну логическую прежде разбора: разбор строку числит целой записью
	 *          и продолжения ей не ждёт. Опознание идёт местом кавычки: ограду открывает
	 *          лишь кавычка, стоящая на месте значения, - за пробельным знаком, за чертою
	 *          записи, за двоеточием, за запятой либо за открывающей скобкой. Кавычка
	 *          внутри записи оградою не является вовсе, оттого запись `don't` строки не
	 *          продлевает
	 *
	 * @note Проверка эта решает лишь о склейке строк, а не о смысле записи: строку, ею
	 *       склеенную, разбирает затем обычный порядок, и запись негодная отвергается им
	 *       же. Ошибка её в сторону склейки даёт отказ, а в сторону отказа от склейки -
	 *       прежнее поведение
	 */
	static bool unclosed(const string_view line) noexcept {
		// Смещение разбираемого знака строки
		size_t offset = 0;
		/**
		 * Выполняем пропуск отступа разбираемой строки
		 */
		while((offset < line.size()) && spacing(line[offset]))
			// Выполняем переход к следующему знаку строки
			offset++;
		/**
		 * Если строка пуста, примечанием открыта либо указанием
		 */
		if((offset >= line.size()) || (line[offset] == '#') || (line[offset] == '%'))
			// Выводим признак закрытой ограды значения
			return false;
		// Знак, разбираемому предшествующий, началу строки пробел отвечает
		char previous = ' ';
		/**
		 * Признак того, что простое значение строкою уже начато
		 *
		 * @details Ограда значения открывается лишь НА МЕСТЕ значения, а внутри простого
		 *          значения кавычка есть знак содержимого. Сличения с предшествующим знаком
		 *          для того мало: пробел ему отвечает и посреди простого значения, и оттого
		 *          написание `P "` числилось оградою незакрытой, а склейка глотала строку
		 *          следующую, обращая её переводом в содержимом
		 *
		 * @note Обнаружилось это зависимостью исхода от хвостового перевода строки: строка
		 *       последняя, перевода не имеющая, склейке не подлежит вовсе, и порок на ней
		 *       не проявлялся
		 */
		bool plained = false;
		/**
		 * Глубина поточных построений, строкою открытых
		 *
		 * @note Нужна она двоеточию: описание требует за ним пробельного знака ЛИШЬ вне
		 *       поточного построения, а внутри него написание `{"а":"б"}` пишется вплотную
		 */
		size_t flowing = 0;
		/**
		 * Если строка чертою начала либо конца документа открывается
		 *
		 * @note Черта эта простым значением не является вовсе: за нею место значения
		 *       остаётся открытым, и написание `--- "строка` кавычку оградою несёт.
		 *       Считая черту началом простого значения, склейка бросала её на полпути -
		 *       корпус соответствия ответил на то расхождением случаев 9MQT и KSS4
		 */
		if((line.compare(offset, 3, "---") == 0) || (line.compare(offset, 3, "...") == 0)){
			/**
			 * Если за чертою стоит пробельный знак либо конец строки
			 */
			if(((offset + 3) >= line.size()) || spacing(line[offset + 3]))
				// Выполняем переход за черту документа
				offset += 3;
		}
		/**
		 * Выполняем перебор всех знаков строки
		 */
		while(offset < line.size()){
			// Получаем очередной знак строки
			const char letter = line[offset];
			/**
			 * Если знак открывает примечание, стоя за пробельным знаком
			 */
			if((letter == '#') && spacing(previous))
				// Выводим признак закрытой ограды значения
				return false;
			/**
			 * Если знак оградою значения является, стоя на месте значения
			 */
			/**
			 * Если знак оградою значения является, стоя на месте значения
			 *
			 * @note Знаки `-` и `?` из перечня изъяты намеренно: описание требует за ними
			 *       пробельного знака - `- x` есть член перечня, а `-x` есть простое
			 *       значение целиком. Числя `-"` местом значения, склейка глотала строку
			 *       следующую. Знак `:` изъятию не подлежит: поточное построение
			 *       `{"а":"б"}` пробела за ним не требует
			 */
			if(((letter == '\'') || (letter == '"')) && !plained &&
			   (spacing(previous) || (previous == ':') || (previous == ',') ||
			   (previous == '[') || (previous == '{'))){
				// Смещение разбираемого знака записи значения
				size_t position = (offset + 1);
				// Признак закрытия ограды значения
				bool closed = false;
				/**
				 * Выполняем перебор всех знаков записи значения
				 */
				while(position < line.size()){
					/**
					 * Если ограда двойная, а знак открывает отменяющую последовательность
					 */
					if((letter == '"') && (line[position] == '\\')){
						// Выполняем переход за отменяющую последовательность
						position += 2;
						// Выполняем переход к следующему знаку записи
						continue;
					}
					/**
					 * Если знак закрывает ограду значения
					 */
					if(line[position] == letter){
						/**
						 * Если ограда одинарная, а кавычка удвоена
						 */
						if((letter == '\'') && ((position + 1) < line.size()) && (line[position + 1] == '\'')){
							// Выполняем переход за удвоенную кавычку
							position += 2;
							// Выполняем переход к следующему знаку записи
							continue;
						}
						// Запоминаем признак закрытия ограды значения
						closed = true;
						// Выходим из перебора знаков записи значения
						break;
					}
					// Выполняем переход к следующему знаку записи
					position++;
				}
				/**
				 * Если ограда значения не закрыта
				 */
				if(!closed)
					// Выводим признак незакрытой ограды значения
					return true;
				// Выполняем переход за закрытую ограду значения
				offset = (position + 1);
				// Запоминаем знак, разбираемому предшествующий
				previous = letter;
				// Выполняем переход к разбору следующего знака
				continue;
			}
			/**
			 * Если знак свойство значения открывает, а простое значение ещё не начато
			 *
			 * @note Метка, якорь и ссылка суть СВОЙСТВА значения, а не значение само: за
			 *       ними место значения остаётся открытым, и кавычка за ними оградою
			 *       является. Считая их началом простого значения, склейка бросала
			 *       написание `ключ: !!binary "` на полпути - корпус соответствия ответил
			 *       на то расхождением случая 565N, чем правку и поправил
			 */
			if(!plained && ((letter == '!') || (letter == '&') || (letter == '*'))){
				/**
				 * Выполняем пропуск записи свойства значения до пробельного знака
				 */
				while((offset < line.size()) && !spacing(line[offset]))
					// Выполняем переход к следующему знаку строки
					offset++;
				// Запоминаем знак, разбираемому предшествующий, свойству пробел отвечает
				previous = ' ';
				// Выполняем переход к разбору следующего знака
				continue;
			}
			/**
			 * Если знак место значения открывает
			 *
			 * @note Пробел места значения не открывает и признака не трогает: он вправе
			 *       стоять и посреди простого значения
			 */
			/**
			 * Признак того, что за знаком стоит пробельный знак либо конец строки
			 */
			const bool parted = (((offset + 1) >= line.size()) || spacing(line[offset + 1]));
			/**
			 * Если знак место значения открывает
			 *
			 * @note Знаки `-`, `?` и `:` открывают место значения лишь тогда, когда за ними
			 *       стоит пробельный знак: внутри простого значения они суть знаки
			 *       содержимого
			 *
			 * @note Черта и вопрос вдобавок требуют, чтобы простое значение начато не было:
			 *       член перечня открывается чертою В НАЧАЛЕ места значения, а `P- ` есть
			 *       значение `P-` целиком, где черта содержимому принадлежит. Двоеточие же
			 *       оговорки той не знает: `имя: значение` открывает место значения ровно
			 *       за простым именем пары
			 *
			 * @note Считая знаки эти местом значения всегда, склейка бросала
			 *       написание `P- "` на полпути - в нём черта принадлежит значению `P-`
			 *
			 * @note Знаки `,`, `[` и `{` пробела за собою не требуют: поточное построение
			 *       `{"а":"б"}` пишется и вплотную
			 */
			/**
			 * Если знак поточное построение открывает
			 */
			if((letter == '[') || (letter == '{'))
				// Увеличиваем глубину поточных построений
				flowing++;
			/**
			 * Если знак поточное построение закрывает, а построение открыто
			 */
			else if(((letter == ']') || (letter == '}')) && (flowing > 0))
				// Уменьшаем глубину поточных построений
				flowing--;
			/**
			 * Если знак место значения открывает
			 *
			 * @warning Скобки поточных построений место значения открывают лишь тогда, когда
			 *          простое значение строкою ещё не начато: скобка внутри простого
			 *          значения есть знак содержимого, и написание `o[` построения не
			 *          открывает вовсе. Сбрасывая признак безусловно, проверка числила
			 *          кавычку в записи `: o["` стоящей на месте значения, склейка глотала
			 *          строку следующую, и текст `: o["\n-` с переводом хвостовым принимался,
			 *          а без перевода отвергался - строка последняя склейке не подлежит
			 */
			if((letter == ',') || (!plained && ((letter == '[') || (letter == '{'))) ||
			   ((parted || (flowing > 0)) && (letter == ':')) ||
			   (parted && !plained && ((letter == '-') || (letter == '?'))))
				// Выполняем сброс признака начатого простого значения
				plained = false;
			// Если знак пробельным не является
			else if(!spacing(letter))
				// Запоминаем признак начатого простого значения
				plained = true;
			// Запоминаем знак, разбираемому предшествующий
			previous = letter;
			// Выполняем переход к следующему знаку строки
			offset++;
		}
		// Выводим признак закрытой ограды значения
		return false;
	}
	/**
	 * @brief Функция свёртки переводов строк внутри огранённого значения
	 *
	 * @param text  содержимое огранённого значения без ограды
	 * @param style вид ограды значения
	 * @return      содержимое значения со свёрнутыми переводами строк
	 *
	 * @details Свёртка задана описанием правилом `s-flow-folded`: пробельная обвязка по
	 *          обе стороны перевода строки снимается, один перевод обращается пробелом, а
	 *          каждый следующий за ним остаётся переводом. Строка пустая перевода своего
	 *          не теряет - оттого два перевода дают один, три дают два и так далее
	 *
	 * @note Ограда двойная знает отмену самого перевода: обратная косая черта, перед ним
	 *       стоящая, свёртку отменяет вовсе - ни пробела, ни перевода не остаётся. Черта
	 *       та обязана быть непарной: `\\` есть записанная черта, а не отмена перевода
	 */
	static string folding(const string_view text, const style_t style) noexcept {
		// Собираемое содержимое значения со свёрнутыми переводами
		string result;
		// Выполняем упреждающее выделение памяти под собираемое содержимое
		result.reserve(text.size());
		// Смещение разбираемого знака содержимого
		size_t offset = 0;
		/**
		 * Выполняем перебор всех знаков содержимого значения
		 */
		while(offset < text.size()){
			// Получаем очередной знак содержимого значения
			const char letter = text[offset];
			/**
			 * Если знак переводом строки не является
			 */
			if(letter != '\n'){
				// Выполняем перенос знака в собираемое содержимое
				result.push_back(letter);
				// Выполняем переход к следующему знаку содержимого
				offset++;
				// Выполняем переход к разбору следующего знака
				continue;
			}
			// Количество непарных обратных косых черт перед переводом строки
			size_t slashes = 0;
			/**
			 * Выполняем счёт обратных косых черт, переводу строки предшествующих
			 */
			while((slashes < result.size()) && (result[(result.size() - 1) - slashes] == '\\'))
				// Увеличиваем количество обратных косых черт
				slashes++;
			// Признак отмены перевода строки обратною косой чертой
			const bool escaped = ((style == style_t::DOUBLE) && ((slashes % 2) == 1));
			/**
			 * Если перевод строки отменён обратною косой чертой
			 *
			 * @note Черта отмены в содержимое не переносится: снятие ограды знало бы её
			 *       отменяющей последовательностью, а отменяет она сам перевод
			 */
			if(escaped)
				// Выполняем снятие черты отмены с собираемого содержимого
				result.pop_back();
			/**
			 * Если перевод строки отменою не отменён
			 *
			 * @note Обвязка снимается лишь у перевода, свёртке подлежащего: отменённый
			 *       перевод содержимого не разделяет вовсе, и пробельные знаки перед чертою
			 *       отмены суть содержимое, а не обвязка. Прежде снимались они и там, и
			 *       написание `или \t\` строкою ниже теряло подачу
			 */
			if(!escaped){
				/**
				 * Выполняем снятие пробельной обвязки с конца собранного содержимого
				 */
				while(!result.empty() && spacing(result.back())){
					/**
					 * Если пробельный знак сам обратною косой чертой отменён
					 *
					 * @details Описание дозволяет отменять пробел и подачу самими знаками
					 *          их: запись `\` с подачею за нею есть подача, а не отмена
					 *          перевода строки. Знак такой есть содержимое, и обвязкою он
					 *          не является - снятие его теряло бы записанное, а черта
					 *          отмены при том оставалась бы отменять перевод строки
					 *
					 * @note Случаи DE56 набора yaml-test-suite
					 */
					if(style == style_t::DOUBLE){
						// Количество обратных косых черт перед пробельным знаком
						size_t leading = 0;
						/**
						 * Выполняем счёт обратных косых черт, знаку предшествующих
						 */
						while((leading < (result.size() - 1)) &&
						      (result[(result.size() - 2) - leading] == '\\'))
							// Увеличиваем количество обратных косых черт
							leading++;
						/**
						 * Если пробельный знак отменён обратною косой чертой
						 */
						if((leading % 2) == 1)
							// Выходим из снятия пробельной обвязки
							break;
					}
					// Выполняем укорочение собранного содержимого на один знак
					result.pop_back();
				}
			}
			// Количество переводов строк подряд
			size_t breaks = 0;
			/**
			 * Выполняем счёт переводов строк подряд вместе с пробельною обвязкой между ними
			 */
			while(offset < text.size()){
				/**
				 * Если знак является переводом строки
				 */
				if(text[offset] == '\n'){
					// Увеличиваем количество переводов строк подряд
					breaks++;
					// Выполняем переход к следующему знаку содержимого
					offset++;
				/**
				 * Если знак является пробельным
				 */
				} else if(spacing(text[offset]))
					// Выполняем переход к следующему знаку содержимого
					offset++;
				// Если знак содержательным является
				else break;
			}
			/**
			 * Если перевод строки отменён обратною косой чертой
			 *
			 * @note Отменяется лишь первый перевод: пустая строка за ним перевод свой
			 *       сохраняет, ибо отмена стоит перед нею, а не перед ней самой
			 */
			if(escaped)
				// Выполняем уменьшение количества переводов строк подряд
				breaks--;
			/**
			 * Если переводы строк свёртке подлежат
			 */
			if(breaks > 0){
				/**
				 * Если перевод строки один
				 */
				if(breaks == 1)
					// Выполняем запись пробела вместо перевода строки
					result.push_back(' ');
				// Выполняем запись переводов строк, свёртке не поддавшихся
				else result.append((breaks - 1), '\n');
			}
		}
		// Выводим содержимое значения со свёрнутыми переводами строк
		return result;
	}
	/**
	 * @brief Функция проверки знака на пригодность имени метки
	 *
	 * @details Описание дозволяет имени метки всякий знак, кроме пробельных и кроме
	 *          знаков, поточные построения размечающих: имя обязано кончаться там, где
	 *          кончается оно и внутри скобок, иначе `[*метка,ещё]` прочлось бы одним именем
	 *
	 * @param letter проверяемый знак
	 * @return       признак пригодности знака имени метки
	 *
	 */
	static bool naming(const char letter) noexcept {
		/**
		 * Если знак пробельный
		 */
		if(spacing(letter))
			// Выводим признак непригодности знака имени метки
			return false;
		/**
		 * Определяем знак, имени метки не принадлежащий
		 */
		switch(letter){
			// Если знак размечает поточное построение
			case ',':
			case '[':
			case ']':
			case '{':
			case '}':
				// Выводим признак непригодности знака имени метки
				return false;
		}
		// Выводим признак пригодности знака имени метки
		return true;
	}
	/**
	 * @brief Функция проверки знака на пригодность записи метки типа
	 *
	 * @details Метка типа есть запись единообразного указателя, и знаки её описанием
	 *          заданы перечнем. Восклицательный знак в перечень тот не входит нарочно:
	 *          им отделяется сокращение метки от остатка её
	 *
	 * @param letter проверяемый знак
	 * @return       признак пригодности знака записи метки типа
	 *
	 */
	/**
	 * @brief Функция проверки знака на разделитель имени пары
	 *
	 * @param line     разбираемая строка
	 * @param position смещение проверяемого знака строки
	 * @return         признак того, что знак разделителем имени пары является
	 *
	 * @details Описание числит двоеточие знаком записи метки типа: правило `ns-tag-char`
	 * берёт его у `ns-uri-char`. Двоеточие же, за каким стоит пробельный знак либо конец
	 * строки, есть разделитель имени пары - правило `ns-s-implicit-yaml-key` требует
	 * отделения имени от значения именно им. Розыск метки, двоеточие поглощавший,
	 * обращал написание `!t: v` в скаляр `v` с меткою `t:`, а пара при этом пропадала
	 * вовсе: имя её события своего не получало, и всякая пара ниже сдвигалась на одну -
	 * значение соседа становилось её именем
	 *
	 * @note Отделение сличается тем же правилом, каким сличает его разбор строки:
	 *       двоеточие внутри записи разделителем не является вовсе, и метка `!t:x`
	 *       остаётся меткою `t:x`
	 */
	static bool separated(const string_view line, const size_t position) noexcept {
		// Выводим признак разделителя имени пары
		return ((line[position] == ':') && (((position + 1) >= line.size()) ||
		 (line[position + 1] == ' ') || (line[position + 1] == '\t')));
	}
	static bool tagging(const char letter) noexcept {
		/**
		 * @note Знаки ограды поточных построений записи сокращения не принадлежат вовсе:
		 *       запятая в поточном построении метку типа завершает, а вне его делает
		 *       написание `- !!str, xxx` ошибочным. Дословная же запись `!<...>` знаки
		 *       эти несёт и читается не здесь
		 */
		/**
		 * Если знак есть буква либо цифра
		 */
		if(((letter >= 'a') && (letter <= 'z')) || ((letter >= 'A') && (letter <= 'Z')) ||
		   ((letter >= '0') && (letter <= '9')))
			// Выводим признак пригодности знака записи метки типа
			return true;
		/**
		 * Определяем знак, записи указателя принадлежащий
		 */
		switch(letter){
			// Если знак дозволен описанием записи указателя
			case '-': case ';': case '/': case '?': case ':': case '@': case '&':
			case '=': case '+': case '$': case '_': case '.': case '~':
			case '*': case '\'': case '(': case ')': case '%':
				// Выводим признак пригодности знака записи метки типа
				return true;
		}
		// Выводим признак непригодности знака записи метки типа
		return false;
	}
	/**
	 * @brief Функция разбора шестнадцатеричной записи знака Юникода
	 *
	 * @param text   разбираемая запись знака
	 * @param offset смещение начала записи
	 * @param count  количество разрядов записи
	 * @param code   получаемый знак Юникода
	 * @return       признак успешного разбора записи
	 *
	 */
	static bool hexadecimal(const string_view text, const size_t offset, const size_t count, uint32_t & code) noexcept {
		/**
		 * Если разрядов записи в строке не хватает
		 */
		if((offset + count) > text.size())
			// Выводим признак неудачного разбора записи
			return false;
		// Собираемый знак Юникода
		uint32_t result = 0;
		/**
		 * Выполняем перебор всех разрядов записи знака
		 */
		for(size_t i = 0; i < count; i++){
			// Получаем очередной разряд записи знака
			const char letter = text[offset + i];
			// Величина, отвечающая разряду записи
			uint32_t value = 0;
			/**
			 * Если разряд записан десятичной цифрой
			 */
			if((letter >= '0') && (letter <= '9'))
				// Получаем величину, отвечающую цифре
				value = static_cast <uint32_t> (letter - '0');
			/**
			 * Если разряд записан строчной буквой
			 */
			else if((letter >= 'a') && (letter <= 'f'))
				// Получаем величину, отвечающую букве
				value = static_cast <uint32_t> ((letter - 'a') + 10);
			/**
			 * Если разряд записан прописной буквой
			 */
			else if((letter >= 'A') && (letter <= 'F'))
				// Получаем величину, отвечающую букве
				value = static_cast <uint32_t> ((letter - 'A') + 10);
			/**
			 * Если знак разрядом записи не является вовсе
			 */
			else return false;
			// Выполняем добавление разряда к собираемому знаку
			result = ((result << 4) | value);
		}
		// Запоминаем разобранный знак Юникода
		code = result;
		// Выводим признак успешного разбора записи
		return true;
	}
	/**
	 * @brief Функция раскрытия долевых записей знаков в метке типа
	 *
	 * @details Метка типа есть единообразный указатель, и знаки, перечню его не
	 *          принадлежащие, записываются в ней долею с точкою кода: запись `%21` есть
	 *          восклицательный знак. Раскрытие это дело чтения, а не потребителя: метка
	 *          есть указатель сам по себе, а не запись его
	 *
	 * @note Раскрывается запись побайтно, а не позначно: доля задаёт октет записи UTF-8,
	 *       и знак вне ASCII записывается несколькими долями подряд
	 *
	 * @param tag раскрываемая метка типа
	 * @return    признак успешного раскрытия метки типа
	 *
	 */
	static bool unescaped(string & tag) noexcept {
		// Разыскиваем первую долевую запись знака в метке типа
		size_t offset = tag.find('%');
		/**
		 * Если долевых записей знаков метка типа не несёт
		 */
		if(offset == string::npos)
			// Выводим признак успешного раскрытия метки типа
			return true;
		// Собираемая метка типа с раскрытыми записями знаков
		string result(tag, 0, offset);
		/**
		 * Выполняем перебор остатка метки типа
		 */
		while(offset < tag.size()){
			/**
			 * Если знак метки типа долевую запись не открывает
			 */
			if(tag[offset] != '%'){
				// Выполняем присоединение знака к собираемой метке типа
				result.append(1, tag[offset]);
				// Выполняем переход к следующему знаку метки типа
				offset++;
				// Выполняем переход к следующему обороту разбора
				continue;
			}
			// Получаемый октет долевой записи знака
			uint32_t code = 0;
			/**
			 * Если разобрать долевую запись знака не удалось
			 *
			 * @note Доля без двух разрядов за нею записи указателя не принадлежит вовсе:
			 *       описание правилом `ns-uri-char` держит их обязательными
			 */
			if(!hexadecimal(tag, (offset + 1), 2, code))
				// Выводим признак неудачного раскрытия метки типа
				return false;
			// Выполняем присоединение раскрытого октета к собираемой метке типа
			result.append(1, static_cast <char> (code));
			// Выполняем переход за разобранную долевую запись знака
			offset += 3;
		}
		// Выполняем замену метки типа раскрытою записью её
		tag.swap(result);
		// Выводим признак успешного раскрытия метки типа
		return true;
	}
}

/**
 * @brief Конструктор
 *
 * @param log объект для работы с логами
 *
 */
awh::codec::yaml::Reader::Reader(const log_t * log) noexcept :
 _log(log),
 _decoder(log),
 _state(state_t::READY),
 _error(error_t::NONE),
 _offset(0),
 _reading(0),
 _line(0),
 _position(0),
 _started(false),
 _opened(false),
 _filled(false),
 _blocking(false),
 _block(style_t::LITERAL),
 _chomp(chomp_t::CLIP),
 _marked(NO_INDENT),
 _outer(0),
 _margin(0),
 _joined(0),
 _stretched(false),
 _shallow(0),
 _asked(false),
 _answering(false),
 _questioned(0),
 _asking(0),
 _dashed(false),
 _flowning(false),
 _inner(0),
 _opening(0),
 _breaks(0),
 _padding(0),
 _deepened(false),
 _expected(false),
 _awaited(false),
 _valued(false),
 _headed(false),
 _propped(false),
 _tabbed(false),
 _rooted(false),
 _detected(false),
 _entered(false),
 _pending(0),
 _schema(schema_t::CORE),
 _anchoredHere(false),
 _taggedHere(false),
 _plaining(false),
 _folds(0),
 _required(0),
 _phase(flow_t::ENTRY),
 _directed(false),
 _versioned(false),
 _declared(false),
 _dialect(schema_t::CORE) {}
/**
 * @brief Конструктор
 *
 * @param log      объект для работы с логами
 * @param settings настройки разбора текста
 *
 */
awh::codec::yaml::Reader::Reader(const log_t * log, const settings_t & settings) noexcept :
 _log(log),
 _settings(settings),
 _decoder(log),
 _state(state_t::READY),
 _error(error_t::NONE),
 _offset(0),
 _reading(0),
 _line(0),
 _position(0),
 _started(false),
 _opened(false),
 _filled(false),
 _blocking(false),
 _block(style_t::LITERAL),
 _chomp(chomp_t::CLIP),
 _marked(NO_INDENT),
 _outer(0),
 _margin(0),
 _joined(0),
 _stretched(false),
 _shallow(0),
 _asked(false),
 _answering(false),
 _questioned(0),
 _asking(0),
 _dashed(false),
 _flowning(false),
 _inner(0),
 _opening(0),
 _breaks(0),
 _padding(0),
 _deepened(false),
 _expected(false),
 _awaited(false),
 _valued(false),
 _headed(false),
 _propped(false),
 _tabbed(false),
 _rooted(false),
 _detected(false),
 _entered(false),
 _pending(0),
 _schema(settings.schema),
 _anchoredHere(false),
 _taggedHere(false),
 _plaining(false),
 _folds(0),
 _required(0),
 _phase(flow_t::ENTRY),
 _directed(false),
 _versioned(false),
 _declared(false),
 _dialect(settings.schema) {
	/**
	 * Если кодировка исходного текста навязана извне
	 */
	if(this->_settings.encoding != encoding_t::NONE)
		// Выполняем навязывание кодировки приведению
		this->_decoder.encoding(this->_settings.encoding);
}
/**
 * @brief Метод получения настроек разбора текста
 *
 * @return настройки разбора текста
 *
 */
const awh::codec::yaml::Reader::settings_t & awh::codec::yaml::Reader::settings() const noexcept {
	// Выводим настройки разбора текста
	return this->_settings;
}
/**
 * @brief Метод установки настроек разбора текста
 *
 * @param settings устанавливаемые настройки разбора
 * @return         признак принятия настроек разбора
 *
 */
bool awh::codec::yaml::Reader::settings(const settings_t & settings) noexcept {
	/**
	 * Если текст уже разбирается
	 *
	 * @note Смена правил разбора посреди текста развела бы начало его с концом: первая
	 *       половина оказалась бы прочитана одними правилами, вторая иными
	 */
	if(this->_state == state_t::PARSING)
		// Выводим признак непринятия настроек разбора
		return false;
	// Запоминаем настройки разбора текста
	this->_settings = settings;
	// Запоминаем схему разрешения видов, над документом действующую
	this->_schema = settings.schema;
	/**
	 * Запоминаем схему, директивой наречия назначенную
	 *
	 * @note Сброс состояния схему эту от настроек и берёт, а установка настроек её не
	 *       трогала вовсе: чтение, переиспользованное без сброса, отдавало бы наречие
	 *       текста прежнего
	 */
	this->_dialect = settings.schema;
	// Выполняем навязывание кодировки приведению
	this->_decoder.encoding(this->_settings.encoding);
	// Выводим признак принятия настроек разбора
	return true;
}
/**
 * @brief Метод сброса состояния потокового чтения
 *
 */
void awh::codec::yaml::Reader::clear() noexcept {
	// Выполняем сброс состояния потокового чтения
	this->_state = state_t::READY;
	// Выполняем сброс кода ошибки разбора текста
	this->_error = error_t::NONE;
	// Выполняем сброс положения отказа разбора
	this->_location = location_t();
	// Выполняем сброс накопителя поданного текста
	this->_buffer.clear();
	// Выполняем сброс смещения начала неразобранного текста
	this->_offset = 0;
	// Выполняем сброс хранилища содержимого собранных событий
	this->_storage.clear();
	// Выполняем сброс очереди собранных событий
	this->_events.clear();
	// Выполняем сброс номера очередного события очереди
	this->_reading = 0;
	// Выполняем сброс событий разбираемой строки
	this->_staged.clear();
	// Выполняем сброс события, выданного последним
	this->_current = item_t();
	// Выполняем сброс значения, выданного последним событием
	this->_content = content_t();
	// Выполняем сброс стопы открытых уровней вложенности
	this->_levels.clear();
	// Выполняем сброс номера разбираемой строки
	this->_line = 0;
	// Выполняем сброс количества строк, склейкой присоединённых
	this->_joined = 0;
	// Выполняем сброс смещения от начала текста
	this->_position = 0;
	// Выполняем сброс признака выдачи начала потока
	this->_started = false;
	// Выполняем сброс признака открытия документа
	this->_opened = false;
	// Выполняем сброс признака наполнения документа
	this->_filled = false;
	// Выполняем сброс признака сборки блочного значения
	this->_blocking = false;
	// Выполняем сброс собираемого содержимого блочного значения
	this->_block_text.clear();
	// Выполняем сброс количества пустых строк блочного значения
	this->_breaks = 0;
	// Выполняем сброс наибольшего отступа пустых строк, содержимому предпосланных
	this->_padding = 0;
	// Выполняем сброс признака строки, глубже отступа содержимого стоявшей
	this->_deepened = false;
	// Выполняем сброс отступа содержимого блочного значения
	this->_inner = 0;
	// Выполняем сброс признака ожидания значения пары
	this->_expected = false;
	// Выполняем сброс признака имени, вопросом объявленного
	this->_asked = false;
	// Выполняем сброс признака ожидания значения имени, вопросом объявленного
	this->_answering = false;
	// Выполняем сброс признака простого значения, внутри скобок собираемого
	this->_flowning = false;
	// Выполняем сброс собираемого содержимого простого значения внутри скобок
	this->_flown.clear();
	// Выполняем сброс признака подачи значения пары, объявленной прежде
	this->_awaited = false;
	// Выполняем сброс признака разбора значения пары в строке имени её
	this->_valued = false;
	// Выполняем сброс признака разбора содержимого на строке черты начала документа
	this->_headed = false;
	// Выполняем сброс признака принадлежности ожидаемого значения записи перечня
	this->_entered = false;
	// Выполняем сброс отступа, на котором ожидается значение пары
	this->_pending = 0;
	// Выполняем возврат схемы разрешения видов к назначенной настройками
	this->_schema = this->_settings.schema;
	// Выполняем сброс имени метки, узла своего ожидающей
	this->_anchor.clear();
	// Выполняем сброс метки типа, узла своего ожидающей
	this->_tag.clear();
	// Выполняем сброс имени метки, вместилищу отложенной
	this->_delayed.clear();
	// Выполняем сброс метки типа, вместилищу отложенной
	this->_delayedTag.clear();
	// Выполняем сброс признака сборки простого значения
	this->_plaining = false;
	// Выполняем сброс собираемого содержимого простого значения
	this->_plain.clear();
	// Выполняем сброс количества пустых строк простого значения
	this->_folds = 0;
	// Выполняем сброс положения начала простого значения
	this->_origin = location_t();
	// Выполняем сброс стопы открытых поточных построений
	this->_flow.clear();
	// Выполняем сброс состояния разбора поточного построения
	this->_phase = flow_t::ENTRY;
	// Выполняем сброс имён меток, документом объявленных
	this->_anchors.clear();
	// Выполняем сброс сокращений меток типов, директивами объявленных
	this->_handles.clear();
	// Выполняем сброс признака предпосланных документу директив
	this->_directed = false;
	// Выполняем сброс признака объявленного директивой наречия
	this->_versioned = false;
	// Выполняем сброс признака объявленного директивой наречия за весь текст
	this->_declared = false;
	// Выполняем сброс схемы, директивой наречия назначенной
	this->_dialect = this->_settings.schema;
	/**
	 * Выполняем сброс остатка полей состояния, разбором заново назначаемых
	 *
	 * @details Сброс обязан снимать состояние ЦЕЛИКОМ: поля ниже он обходил стороною, и
	 * остаток их доставался тексту следующему. Нашёл это ворошитель правилом «чтение
	 * сброшенное равно свежему» - чтением, живущим от прохода к проходу
	 *
	 * @warning Парою текстов остаток НЕ ЛОВИТСЯ: сличение всех пар из 351 текста набора
	 *          соответствия при снятых сбросах этих расхождений не дало ни одного - нужна
	 *          череда. Оттого и проверка ResetClearsEveryTraceOfPreviousText порчею не
	 *          доказывается, а стережёт заставою; довод же за сбросы даёт ворошитель:
	 *          без них правило валится, с ними проходит, а поток тот же самый - обе
	 *          кампании прошли ровно 500 000 ходов с одинаковым числом событий
	 */
	// Выполняем сброс признака определённого отступа блочного значения
	this->_detected = false;
	// Выполняем сброс признака блочного значения, содержимым документа целиком стоящего
	this->_rooted = false;
	// Выполняем сброс признака документа, чертою начала своего открытого
	this->_dashed = false;
	// Выполняем сброс признака подачи в отступе вложенного построения
	this->_tabbed = false;
	// Выполняем сброс признака разбора свойств узла в разбираемой строке
	this->_propped = false;
	// Выполняем сброс признака объявления метки узла в разбираемой строке
	this->_anchoredHere = false;
	// Выполняем сброс признака огранённого значения в несколько строк
	this->_stretched = false;
	// Выполняем сброс наименьшего отступа строк, склейкой присоединённых
	this->_shallow = 0;
	// Выполняем сброс отступа, какой обязано превышать продолжение простого значения
	this->_required = 0;
	// Выполняем сброс отступа строки, заголовок блочного значения несущей
	this->_outer = 0;
	// Выполняем сброс положения заголовка блочного значения в строке
	this->_opening = 0;
	// Выполняем сброс отступа разбираемой строки
	this->_margin = 0;
	// Выполняем сброс отступа, заголовком блочного значения заданного
	this->_marked = NO_INDENT;
	// Выполняем сброс отступа, на котором стоит вопрос составного имени
	this->_questioned = 0;
	// Выполняем сброс количества открытых уровней на миг объявления имени вопросом
	this->_asking = 0;
	// Выполняем сброс состояния приведения кодировки
	this->_decoder.reset();
}
/**
 * @brief Метод получения состояния потокового чтения
 *
 * @return состояние потокового чтения текста
 *
 */
state_t awh::codec::yaml::Reader::state() const noexcept {
	// Выводим состояние потокового чтения текста
	return this->_state;
}
/**
 * @brief Метод получения кода ошибки разбора текста
 *
 * @return код ошибки разбора текста
 *
 */
awh::codec::yaml::error_t awh::codec::yaml::Reader::error() const noexcept {
	// Выводим код ошибки разбора текста
	return this->_error;
}
/**
 * @brief Метод получения положения отказа в исходном тексте
 *
 * @return положение отказа разбора в исходном тексте
 *
 */
const location_t & awh::codec::yaml::Reader::location() const noexcept {
	// Выводим положение отказа разбора в исходном тексте
	return this->_location;
}
/**
 * @brief Метод извлечения схемы, над разбором действующей
 *
 * @return схема, над разбором действующая
 *
 */
schema_t awh::codec::yaml::Reader::dialect() const noexcept {
	// Выводим схему, директивой наречия назначенную
	return this->_dialect;
}
/**
 * @brief Метод проверки объявления наречия директивой
 *
 * @return признак объявления наречия директивой
 *
 */
bool awh::codec::yaml::Reader::declared() const noexcept {
	// Выводим признак объявления наречия директивой хоть раз за текст
	return this->_declared;
}
/**
 * @brief Метод получения опознанной кодировки исходного текста
 *
 * @return опознанная кодировка исходного текста
 *
 */
encoding_t awh::codec::yaml::Reader::encoding() const noexcept {
	// Выводим опознанную кодировку исходного текста
	return this->_decoder.encoding();
}
/**
 * @brief Метод получения вида последнего события разбора
 *
 * @return вид последнего события разбора
 *
 */
event_t awh::codec::yaml::Reader::event() const noexcept {
	// Выводим вид последнего события разбора
	return this->_current.event;
}
/**
 * @brief Метод получения значения последнего события разбора
 *
 * @return значение последнего события разбора
 *
 */
const content_t & awh::codec::yaml::Reader::value() const noexcept {
	// Выводим значение последнего события разбора
	return this->_content;
}
/**
 * @brief Метод объявления отказа разбора
 *
 * @param error  код ошибки разбора
 * @param column положение отказа в разбираемой строке
 * @return       признак прекращения разбора
 *
 */
bool awh::codec::yaml::Reader::fail(const error_t error, const size_t column) noexcept {
	// Запоминаем код ошибки разбора текста
	this->_error = error;
	// Запоминаем состояние прекращения разбора
	this->_state = state_t::FAILED;
	// Запоминаем смещение отказа от начала текста
	this->_location.offset = (this->_position + column);
	// Запоминаем номер строки, где отказ произошёл
	this->_location.line = this->_line;
	// Запоминаем положение отказа в строке
	this->_location.column = static_cast <uint32_t> (column + 1);
	// Запоминаем глубину вложенности, где отказ произошёл
	this->_location.depth = static_cast <uint32_t> (this->_levels.size());
	/**
	 * Выполняем сброс событий разбираемой строки
	 *
	 * @note Сбрасываются лишь события строки, на которой отказ и случился: выдать их
	 *       значило бы оставить потребителя с началом построения без конца его. События,
	 *       собранные строками прежними, остаются в очереди - они прочитаны верно, и
	 *       отзывать их поздно, ибо при подаче кусками они уже выданы
	 */
	this->_staged.clear();
	/**
	 * Выполняем вывод сообщения об отказе в лог
	 *
	 * @note Код отказа остаётся доступен через error(), а место его - через location():
	 *       журнал есть оповещение, а не единственный способ узнать о случившемся
	 */
	if(this->_log != nullptr)
		// Выполняем вывод сообщения об отказе разбора текста
		this->_log->print("YAML parsing failed: %s at line %u column %u", log_t::flag_t::CRITICAL, awh::codec::yaml::message(error), this->_location.line, this->_location.column);
	// Выводим признак прекращения разбора
	return false;
}
/**
 * @brief Метод постановки собранного события в очередь выдачи
 *
 * @param event  вид собранного события
 * @param column положение события в разбираемой строке
 * @return       ссылка на поставленное событие
 *
 */
awh::codec::yaml::Reader::item_t & awh::codec::yaml::Reader::emit(const event_t event, const size_t column) noexcept {
	// Выполняем постановку события в накопитель разбираемой строки
	this->_staged.emplace_back();
	// Получаем поставленное событие
	item_t & result = this->_staged.back();
	// Запоминаем вид собранного события
	result.event = event;
	// Запоминаем смещение события от начала текста
	result.location.offset = (this->_position + column);
	// Запоминаем номер строки, где событие собрано
	result.location.line = this->_line;
	// Запоминаем положение события в строке
	result.location.column = static_cast <uint32_t> (column + 1);
	// Запоминаем глубину вложенности, где событие собрано
	result.location.depth = static_cast <uint32_t> (this->_levels.size());
	// Запоминаем признак того, что событие собрано внутри поточного построения
	result.flow = !this->_flow.empty();
	// Запоминаем схему, при выдаче события действовавшую
	result.schema = this->_schema;
	// Запоминаем признак того, что документ наречие своё директивой объявил
	result.versioned = this->_versioned;
	// Выводим ссылку на поставленное событие
	return result;
}
/**
 * @brief Метод переноса собранных событий строки в очередь выдачи
 *
 */
void awh::codec::yaml::Reader::commit() noexcept {
	/**
	 * Выполняем перенос всех собранных событий строки в очередь выдачи
	 */
	for(size_t i = 0; i < this->_staged.size(); i++){
		/**
		 * Если все события очереди уже выданы
		 *
		 * @note Перечень сбрасывается лишь тогда, когда выдавать из него нечего: память
		 *       его тем переиспользуется, а выданные события уходят разом, а не по одному
		 */
		if(this->_reading >= this->_events.size()){
			// Выполняем сброс очереди выданных событий
			this->_events.clear();
			// Выполняем сброс номера очередного события очереди
			this->_reading = 0;
		}
		// Выполняем перенос очередного собранного события
		this->_events.emplace_back(this->_staged.at(i));
	}
	// Выполняем сброс накопителя событий разобранной строки
	this->_staged.clear();
}
/**
 * @brief Метод постановки события примечания
 *
 * @param line     разбираемая строка
 * @param position положение знака примечания в строке
 *
 */
void awh::codec::yaml::Reader::remark(const string_view line, const size_t position) noexcept {
	/**
	 * Если выдача примечаний не затребована
	 */
	if(!this->_settings.emitComments)
		// Выходим из постановки события примечания
		return;
	// Выполняем постановку события примечания
	item_t & item = this->emit(event_t::COMMENT, position);
	// Получаем содержимое примечания без знака его и без пробельной обвязки
	const string_view comment = stripped(line.substr(position + 1));
	// Запоминаем смещение содержимого события в хранилище знаков
	item.offset = this->_storage.size();
	// Запоминаем длину содержимого события
	item.length = comment.size();
	// Выполняем перенос содержимого события в хранилище знаков
	this->_storage.append(comment);
}
/**
 * @brief Метод постановки события скалярного значения
 *
 * @param text   содержимое скалярного значения
 * @param style  вид записи значения в исходном тексте
 * @param column положение значения в разбираемой строке
 * @return       признак успешной постановки события
 *
 */
/**
 * @warning Отказ этой связки ПУСТОМУ значению недостижим, и оттого недостижимы же
 *          все четырнадцать заходов распространения его у зовущих, ставящих значение
 *          пустым: предел длины пустоте не помеха, метка порядка байтов в пустоте не
 *          встречается, а метка типа неведомая отвергается прежде - замерено
 *          охватом на шести построениях (пара, перечень, имя составное, скобки
 *          перечня и отображения, корень): ни одна строка распространения не
 *          зажглась. Сносу заходы не подлежат: правка поверок здесь вернёт им
 *          управление, и значение негодное легло бы в дерево молча
 */
bool awh::codec::yaml::Reader::scalar(const string_view text, const style_t style, const size_t column) noexcept {
	// Получаем предел длины скалярного значения
	const size_t limit = ((this->_settings.maxScalar > 0) ? this->_settings.maxScalar : MAX_SCALAR);
	/**
	 * Если длина скалярного значения предел превышает
	 */
	if(text.size() > limit)
		// Выводим отказ превышения длины скалярного значения
		return this->fail(error_t::SCALAR_TOO_LONG, column);
	/**
	 * Если простое значение метку порядка байтов несёт
	 *
	 * @details Описание изымает метку порядка байтов из знаков содержимого правилом
	 *          `nb-char` прямо: метка принадлежит тексту целиком, а не значению в нём.
	 *          Внутри ограды она дозволена - там содержимое строится правилом `nb-json`,
	 *          метки не изымающим, - и оттого правило это касается лишь значения простого
	 *
	 * @note Без правила этого метка, значением проглоченная, при перезаписи выходила
	 *       началом текста и обращалась меткой настоящей: разбор перезаписи получал
	 *       директиву там, где стояло значение. Нашёл это ворошитель
	 */
	if((style == style_t::PLAIN) && (text.find("\xEF\xBB\xBF") != string::npos))
		// Выводим отказ недопустимого знака в этом месте текста
		return this->fail(error_t::INVALID_CHARACTER, column);
	// Вид значения, разрешённый меткой типа либо действующей схемой
	type_t type = type_t::UNDEFINED;
	/**
	 * Если разрешить вид скалярного значения не удалось
	 *
	 * @note Разрешение идёт прежде постановки события: отказ метки типа не вправе
	 *       оставить в накопителе строки событие полусобранное
	 */
	if(!this->typing(text, style, column, type))
		// Выводим признак неудачной постановки события
		return false;
	// Выполняем постановку события скалярного значения
	item_t & item = this->emit(event_t::SCALAR, column);
	// Запоминаем вид записи значения в исходном тексте
	item.style = style;
	// Запоминаем вид значения, разрешённый меткой типа либо действующей схемой
	item.type = type;
	// Выполняем перенос накопленных свойств узла в собранное событие
	this->attach(item);
	// Запоминаем смещение содержимого события в хранилище знаков
	item.offset = this->_storage.size();
	// Запоминаем длину содержимого события
	item.length = text.size();
	// Выполняем перенос содержимого события в хранилище знаков
	this->_storage.append(text);
	// Запоминаем признак наполнения открытого документа
	this->_filled = true;
	// Выводим признак успешной постановки события
	return true;
}
/**
 * @brief Метод закрытия открытых уровней глубже заданного отступа
 *
 * @param indent отступ, до которого закрываются уровни
 * @param column положение закрытия в разбираемой строке
 * @return       признак успешного закрытия уровней
 *
 */
/**
 * @warning Связка эта отказа НЕ ВЫДАЁТ вовсе: единственный выход её - согласие, и
 *          оттого недостижимы все две строк распространения отказа у зовущих её с
 *          проверкою «if(!collapse(...))». Строки эти пересечение прогонов числило
 *          слепыми, и слепы они по устройству, а не по недосмотру набора
 *
 * @note Обвязка отказа у зовущих оставлена намеренно: связка сворачивает уровни разбора, и отказать она
 *       может впредь - снятие обвязки пришлось бы возвращать по частям
 */
bool awh::codec::yaml::Reader::collapse(const uint32_t indent, const size_t column) noexcept {
	/**
	 * Выполняем закрытие всех уровней глубже заданного отступа
	 */
	while(!this->_levels.empty() && (this->_levels.back().indent > indent)){
		// Получаем вид закрываемого уровня вложенности
		const nesting_t kind = this->_levels.back().kind;
		// Выполняем снятие закрываемого уровня со стопы
		this->_levels.pop_back();
		// Выполняем постановку события закрытия уровня
		this->emit(((kind == nesting_t::MAPPING) ? event_t::MAPPING_END : event_t::SEQUENCE_END), column);
	}
	// Выводим признак успешного закрытия уровней
	return true;
}
/**
 * @brief Метод сличения метки типа с видом открываемого построения
 *
 * @param kind   вид открываемого построения
 * @param column положение открытия в разбираемой строке
 * @return       признак соответствия метки типа виду построения
 *
 */
bool awh::codec::yaml::Reader::matched(const nesting_t kind, const size_t column) noexcept {
	/**
	 * Если открываемому построению метка типа не предпослана
	 */
	if(this->_tag.empty())
		// Выводим признак соответствия метки типа виду построения
		return true;
	// Получаем окончание метки типа, вид её задающее
	const string_view suffix = ((this->_tag.compare(0, STANDARD_TAG.size(), STANDARD_TAG) == 0) ?
	 string_view(this->_tag).substr(STANDARD_TAG.size()) : string_view());
	/**
	 * Если метка типа задаёт построение, открываемому противное
	 *
	 * @note Метка `!!seq` над отображением есть не мелкая небрежность записи, а
	 *       расхождение объявленного с записанным: держащий документ построил бы по
	 *       метке одно, а по содержимому иное
	 */
	if((suffix == "seq") && (kind != nesting_t::SEQUENCE))
		// Выводим отказ несоответствия содержимого метке типа
		return this->fail(error_t::TAG_MISMATCH, column);
	/**
	 * Если метка типа задаёт отображение, открываемому построению противное
	 */
	else if((suffix == "map") && (kind != nesting_t::MAPPING))
		// Выводим отказ несоответствия содержимого метке типа
		return this->fail(error_t::TAG_MISMATCH, column);
	/**
	 * Если метка типа задаёт скалярное значение
	 */
	else if((suffix == "str") || (suffix == "int") || (suffix == "float") ||
	        (suffix == "bool") || (suffix == "null") || (suffix == "binary") || (suffix == "timestamp"))
		// Выводим отказ несоответствия содержимого метке типа
		return this->fail(error_t::TAG_MISMATCH, column);
	// Выводим признак соответствия метки типа виду построения
	return true;
}
/**
 * @brief Метод открытия уровня вложенности заданного вида
 *
 * @param kind    вид открываемого уровня вложенности
 * @param indent  отступ, на котором уровень открывается
 * @param implied признак открытия уровня значением пары на отступе имени её
 * @param column  положение открытия в разбираемой строке
 * @return       признак успешного открытия уровня
 *
 */
bool awh::codec::yaml::Reader::expand(const nesting_t kind, const uint32_t indent, const bool implied, const size_t column) noexcept {
	// Получаем предел глубины вложенности
	const size_t limit = ((this->_settings.maxDepth > 0) ? this->_settings.maxDepth : MAX_DEPTH);
	/**
	 * Если глубина вложенности предел превышает
	 */
	if(this->_levels.size() >= limit)
		// Выводим отказ превышения глубины вложенности
		return this->fail(error_t::DEPTH_EXCEEDED, column);
	/**
	 * Если метка типа, уровню предпосланная, виду его противна
	 */
	if(!this->matched(kind, column))
		// Выводим признак неудачного открытия уровня
		return false;
	// Выполняем постановку события открытия уровня
	item_t & item = this->emit(((kind == nesting_t::MAPPING) ? event_t::MAPPING_START : event_t::SEQUENCE_START), column);
	// Выполняем перенос накопленных свойств узла в собранное событие
	this->attach(item);
	// Выполняем открытие уровня вложенности
	this->_levels.emplace_back(kind, indent, implied);
	// Запоминаем признак наполнения открытого документа
	this->_filled = true;
	// Выводим признак успешного открытия уровня
	return true;
}
/**
 * @brief Метод закрытия открытого документа
 *
 * @param column положение закрытия в разбираемой строке
 * @return       признак успешного закрытия документа
 *
 */
bool awh::codec::yaml::Reader::finish(const size_t column) noexcept {
	/**
	 * Если документ не открыт вовсе
	 */
	if(!this->_opened)
		// Выводим признак успешного закрытия документа
		return true;
	/**
	 * Если пара осталась без значения своего
	 *
	 * @details Выдаётся оно прежде закрытия уровней, а не за ними: значение принадлежит
	 *          отображению, и выданное за концом его оказалось бы вне всякого построения.
	 *          Нашло это дерево документа - там значение легло вторым корнем потока
	 *
	 * @note Пустое значение описанием дозволено: `ключ:` знаменует пару с пустым
	 *       значением, и выдать её надлежит именно так
	 */
	if(this->_expected){
		// Выполняем сброс признака ожидания значения пары
		this->_expected = false;
		/**
		 * Если пустота эта принадлежит имени, вопросом объявленному
		 *
		 * @details Правило то же, каким пустота эта выдаётся обрывом ожидания строкою
		 *          следующей: построение имени составного стоит отступом глубже вопроса
		 *          своего, и пустота значения принадлежит отображению вопроса, а не ему
		 *
		 * @note Конец текста ожидание обрывает наравне со строкою, и закрытие уровней
		 *       имени надлежит здесь ровно то же. Случай M2N8 набора yaml-test-suite
		 */
		if(this->_asked && this->_answering){
			// Выполняем сброс признака имени, вопросом объявленного
			this->_asked = false;
			/**
			 * Выполняем закрытие всех уровней, за вопросом открытых
			 */
			while(this->_levels.size() > this->_asking){
				// Получаем вид закрываемого уровня вложенности
				const nesting_t kind = this->_levels.back().kind;
				// Выполняем снятие закрываемого уровня со стопы
				this->_levels.pop_back();
				// Выполняем постановку события закрытия уровня
				this->emit(((kind == nesting_t::MAPPING) ? event_t::MAPPING_END : event_t::SEQUENCE_END), column);
			}
		}
		/**
		 * Если поставить событие пустого значения не удалось
		 */
		if(!this->scalar(string(), style_t::PLAIN, column))
			// Выводим признак неудачного закрытия документа
			return false;
		// Устанавливаем вид пустого значения последнему событию
		this->emptied();
		/**
		 * Устанавливаем место пустого значения там, где оно ожидалось
		 *
		 * @note Закрытие документа - тот же обрыв ожидания, лишь концом текста, а не
		 *       строкою следующей: место значения и здесь есть место ожидания его
		 */
		this->_staged.back().location.offset = this->_awaiting.offset;
		// Устанавливаем строку пустого значения там, где оно ожидалось
		this->_staged.back().location.line = this->_awaiting.line;
		// Устанавливаем столбец пустого значения там, где оно ожидалось
		this->_staged.back().location.column = this->_awaiting.column;
		/**
		 * Если пустота эта была именем, вопросом объявленным
		 *
		 * @details Имя своё вопрос получил здесь же, пустотою, а значения ему никто так и
		 *          не дал: написание `? &метка` есть пара из имени пустого с меткою и
		 *          значения пустого без неё. Одною пустотою обойтись нельзя - отображение
		 *          осталось бы с именем без пары
		 *
		 * @note Случай PW8X набора yaml-test-suite
		 */
		if(this->_asked){
			// Выполняем сброс признака имени, вопросом объявленного
			this->_asked = false;
			/**
			 * Если поставить событие пустого значения не удалось
			 *
			 * @warning Заход этот НЕДОСТИЖИМ, покуда держится условие: событие пустоты ставится
			 *          там, где метки вида уже нет, а без метки разрешение вида отказа не даёт -
			 *          запись пустая ни предела длины не превышает, ни метки порядка байтов не
			 *          несёт. Замерено шестнадцатью записями с меткою `!!bool` над пустотою
			 *          построения поточного: ни одна сюда не дошла - метку забирает заход
			 *          скалярного значения раньше
			 *
			 * @note Сносу заход не подлежит: у закрытия документа метка до пустоты доживает, и
			 *       там отказ этот управление получает - проверка `TagsAndAnchors` тому порукой
			 */
			if(!this->scalar(string(), style_t::PLAIN, column))
				// Выводим признак неудачного закрытия документа
				return false;
			// Устанавливаем вид пустого значения последнему событию
			this->emptied();
		}
	}
	/**
	 * Если документ чертою открыт, а содержимого так и не получил
	 *
	 * @details Узел свой он всё же имеет: описание берёт его правилом `e-node` - пустым
	 *          узлом. Написание `---` без содержимого есть документ с пустым значением, а
	 *          не документ без значения вовсе, и потребитель, по узлам обходящий, обязан
	 *          застать его наравне с прочими
	 *
	 * @note Документ, черты не имеющий, под правило подпадает лишь свойствами узла: запись
	 *       `!` без содержимого есть узел пустой с меткою типа, и без неё документ такой
	 *       не заводится вовсе. Случай UKK6 набора yaml-test-suite
	 */
	if((this->_dashed || !this->_anchor.empty() || !this->_tag.empty()) && !this->_filled){
		/**
		 * Если поставить событие пустого значения не удалось
		 */
		if(!this->scalar(string(), style_t::PLAIN, column))
			// Выводим признак неудачного закрытия документа
			return false;
		// Устанавливаем вид пустого значения последнему событию
		this->emptied();
	}
	/**
	 * Если закрыть открытые уровни вложенности не удалось
	 *
	 * @warning Заход этот НЕДОСТИЖИМ, покуда держится условие: закрытие уровней отказа
	 *          не даёт ни при каком написании - у `collapse` выход один, и тот успех.
	 *          Замерено покрытием: заход не задет ни разу
	 *
	 * @note Сносу заход не подлежит: заведись у закрытия случай негодный - разбор пошёл
	 *       бы дальше с уровнями, оставшимися открытыми
	 */
	if(!this->collapse(0, column))
		// Выводим признак неудачного закрытия документа
		return false;
	/**
	 * Если стопа уровней всё же не пуста
	 *
	 * @note Уровень нулевого отступа закрытием по отступу не снимается: снимается он
	 *       здесь, при закрытии документа
	 */
	while(!this->_levels.empty()){
		// Получаем вид закрываемого уровня вложенности
		const nesting_t kind = this->_levels.back().kind;
		// Выполняем снятие закрываемого уровня со стопы
		this->_levels.pop_back();
		// Выполняем постановку события закрытия уровня
		this->emit(((kind == nesting_t::MAPPING) ? event_t::MAPPING_END : event_t::SEQUENCE_END), column);
	}
	// Выполняем постановку события закрытия документа
	this->emit(event_t::DOCUMENT_END, column);
	// Выполняем сброс признака открытия документа
	this->_opened = false;
	// Выполняем сброс признака наполнения документа
	this->_filled = false;
	// Выполняем сброс признака документа, чертою открытого
	this->_dashed = false;
	/**
	 * Выполняем сброс всего, объявленного закрытым документом
	 *
	 * @details Метки, сокращения меток типов и наречие объявляются документом и живут
	 *          ровно столько, сколько живёт он сам: ссылка из второго документа на метку
	 *          первого описанием запрещена, и знать о ней читающему уже незачем
	 */
	this->_anchors.clear();
	// Выполняем сброс сокращений меток типов, директивами объявленных
	this->_handles.clear();
	// Выполняем сброс признака объявленного директивой наречия
	this->_versioned = false;
	// Выполняем возврат схемы разрешения видов к назначенной настройками
	this->_schema = this->_settings.schema;
	// Выполняем сброс имени метки, узла своего так и не дождавшейся
	this->_anchor.clear();
	// Выполняем сброс метки типа, узла своего так и не дождавшейся
	this->_tag.clear();
	// Выполняем сброс имени метки, вместилищу отложенной
	this->_delayed.clear();
	// Выполняем сброс метки типа, вместилищу отложенной
	this->_delayedTag.clear();
	// Выводим признак успешного закрытия документа
	return true;
}
/**
 * @brief Метод снятия ограды со скалярного значения
 *
 * @param text   разбираемая запись значения вместе с оградою
 * @param style  вид ограды разбираемого значения
 * @param column положение значения в разбираемой строке
 * @param result строка, куда помещается содержимое значения
 * @return       признак успешного снятия ограды
 *
 */
bool awh::codec::yaml::Reader::unquote(const string_view text, const style_t style, const size_t column, string & result) noexcept {
	// Выполняем сброс собираемого содержимого значения
	result.clear();
	/**
	 * Если значение записано без ограды
	 */
	if(style == style_t::PLAIN){
		/**
		 * @warning Заход этот есть застава последнего рубежа, ничем не задетая: снятие
		 *          ограды у значения без ограды не зовут вовсе - вид записи сличается
		 *          прежде вызова у всякого места разбора. Сносу заход не подлежит:
		 *          новое место вызова, вида не сличившее, срезало бы значению по знаку
		 *          с обоих концов
		 */
		// Выполняем перенос записи значения как она есть
		result.assign(text);
		// Выводим признак успешного снятия ограды
		return true;
	}
	// Получаем содержимое значения без ограды
	string_view inner = text.substr(1, (text.size() - 2));
	/**
	 * Собранное содержимое значения со свёрнутыми переводами строк
	 *
	 * @note Держится оно здесь ради вида: свёртка нужна одним лишь значениям многострочным,
	 *       и однострочные разбираются видом на запись, ничего не выделяя
	 */
	string folded;
	/**
	 * Если содержимое значения переводы строк несёт
	 *
	 * @details Значение огранённое вправе стоять в несколько строк, и переводы внутри него
	 *          свёртке подлежат: один обращается пробелом, каждый следующий остаётся
	 *          переводом, а пробельная обвязка по обе стороны его снимается
	 */
	if(inner.find('\n') != string_view::npos){
		// Выполняем свёртку переводов строк содержимого значения
		folded = folding(inner, style);
		// Переставляем содержимое значения на свёрнутое
		inner = folded;
	}
	/**
	 * Если значение обнесено одинарной оградой
	 *
	 * @note Отменяющих последовательностей одинарная ограда не знает вовсе: единственная
	 *       её условность - удвоение кавычки, каким кавычка и записывается
	 */
	if(style == style_t::SINGLE){
		// Смещение разбираемого знака записи
		size_t offset = 0;
		/**
		 * Выполняем перебор всех знаков содержимого значения
		 */
		while(offset < inner.size()){
			// Получаем очередной знак содержимого значения
			const char letter = inner[offset];
			/**
			 * Если знак является удвоенной кавычкой
			 */
			if((letter == '\'') && ((offset + 1) < inner.size()) && (inner[offset + 1] == '\'')){
				// Выполняем запись одной кавычки в содержимое значения
				result.push_back('\'');
				// Выполняем переход за удвоенную кавычку
				offset += 2;
				// Выполняем переход к следующему знаку записи
				continue;
			}
			// Выполняем перенос знака в содержимое значения
			result.push_back(letter);
			// Выполняем переход к следующему знаку записи
			offset++;
		}
		// Выводим признак успешного снятия ограды
		return true;
	}
	// Смещение разбираемого знака записи
	size_t offset = 0;
	/**
	 * Выполняем перебор всех знаков содержимого значения
	 */
	while(offset < inner.size()){
		// Получаем очередной знак содержимого значения
		const char letter = inner[offset];
		/**
		 * Если знак отменяющей последовательностью не открывается
		 */
		if(letter != '\\'){
			// Выполняем перенос знака в содержимое значения
			result.push_back(letter);
			// Выполняем переход к следующему знаку записи
			offset++;
			// Выполняем переход к следующему знаку записи
			continue;
		}
		/**
		 * Если отменяющая последовательность оборвана концом значения
		 *
		 * @warning Заход этот НЕДОСТИЖИМ, покуда держится условие: содержимое приходит
		 *          сюда уже без ограды, а ограду закрывает лишь кавычка НЕОТМЕНЁННАЯ -
		 *          одинокая косая черта концом содержимого невозможна. Замерено
		 *          проверкой `TrailingEscapeLeavesScalarUnterminated`: записи `a: "x\"`
		 *          разбор отвечает кодом UNTERMINATED_SCALAR, до снятия ограды не доходя
		 *
		 * @note Сносу заход не подлежит: значения огранённые многострочные заводятся
		 *       следующим этапом работ, и там ограда закрывается строкою иною - косая
		 *       черта концом строки станет возможной
		 */
		if((offset + 1) >= inner.size())
			// Выводим отказ ошибочного построения отменяющей последовательности
			return this->fail(error_t::INVALID_ESCAPE, (column + offset));
		// Получаем знак, отменяющей последовательностью заданный
		const char escaped = inner[offset + 1];
		// Выполняем переход за знак отмены и заданный им знак
		offset += 2;
		/**
		 * Определяем знак, отменяющей последовательностью заданный
		 */
		switch(escaped){
			// Если последовательность задаёт нулевой знак
			case '0': result.push_back('\0'); break;
			// Если последовательность задаёт звонок
			case 'a': result.push_back('\a'); break;
			// Если последовательность задаёт возврат на знак
			case 'b': result.push_back('\b'); break;
			// Если последовательность задаёт горизонтальную подачу
			case 't': result.push_back('\t'); break;
			// Если последовательность задаёт горизонтальную подачу знаком её
			case '\t': result.push_back('\t'); break;
			// Если последовательность задаёт перевод строки
			case 'n': result.push_back('\n'); break;
			// Если последовательность задаёт вертикальную подачу
			case 'v': result.push_back('\v'); break;
			// Если последовательность задаёт подачу страницы
			case 'f': result.push_back('\f'); break;
			// Если последовательность задаёт возврат каретки
			case 'r': result.push_back('\r'); break;
			// Если последовательность задаёт знак ухода
			case 'e': result.push_back('\x1b'); break;
			// Если последовательность задаёт пробел
			case ' ': result.push_back(' '); break;
			// Если последовательность задаёт кавычку
			case '"': result.push_back('"'); break;
			// Если последовательность задаёт косую черту
			case '/': result.push_back('/'); break;
			// Если последовательность задаёт знак отмены
			case '\\': result.push_back('\\'); break;
			/**
			 * Если последовательность задаёт знак смены строки
			 */
			case 'N': {
				/**
				 * Если записать знак смены строки не удалось
				 */
				/**
				 * @warning Отказ этот есть застава последнего рубежа, ничем не задетая:
				 *          знак задан здесь же числом, и приведению к UTF-8 он поддаётся
				 *          всегда. Сносу заход не подлежит по доводу заставы
				 */
				if(!encode(0x85, result))
					// Выводим отказ ошибочного построения отменяющей последовательности
					return this->fail(error_t::INVALID_ESCAPE, (column + offset));
			} break;
			/**
			 * Если последовательность задаёт неразрывный пробел
			 */
			case '_': {
				/**
				 * Если записать неразрывный пробел не удалось
				 */
				/**
				 * @warning Отказ этот есть застава последнего рубежа, ничем не задетая:
				 *          знак задан здесь же числом, и приведению к UTF-8 он поддаётся
				 *          всегда. Сносу заход не подлежит по доводу заставы
				 */
				if(!encode(0xA0, result))
					// Выводим отказ ошибочного построения отменяющей последовательности
					return this->fail(error_t::INVALID_ESCAPE, (column + offset));
			} break;
			/**
			 * Если последовательность задаёт разделитель строк
			 */
			case 'L': {
				/**
				 * Если записать разделитель строк не удалось
				 */
				/**
				 * @warning Отказ этот есть застава последнего рубежа, ничем не задетая:
				 *          знак задан здесь же числом, и приведению к UTF-8 он поддаётся
				 *          всегда. Сносу заход не подлежит по доводу заставы
				 */
				if(!encode(0x2028, result))
					// Выводим отказ ошибочного построения отменяющей последовательности
					return this->fail(error_t::INVALID_ESCAPE, (column + offset));
			} break;
			/**
			 * Если последовательность задаёт разделитель абзацев
			 */
			case 'P': {
				/**
				 * Если записать разделитель абзацев не удалось
				 */
				/**
				 * @warning Отказ этот есть застава последнего рубежа, ничем не задетая:
				 *          знак задан здесь же числом, и приведению к UTF-8 он поддаётся
				 *          всегда. Сносу заход не подлежит по доводу заставы
				 */
				if(!encode(0x2029, result))
					// Выводим отказ ошибочного построения отменяющей последовательности
					return this->fail(error_t::INVALID_ESCAPE, (column + offset));
			} break;
			/**
			 * Если последовательность задаёт знак шестнадцатеричной записью
			 */
			case 'x':
			case 'u':
			case 'U': {
				// Получаем количество разрядов записи знака
				const size_t count = ((escaped == 'x') ? 2 : ((escaped == 'u') ? 4 : 8));
				// Разбираемый знак Юникода
				uint32_t code = 0;
				/**
				 * Если разобрать запись знака не удалось
				 */
				if(!hexadecimal(inner, offset, count, code))
					// Выводим отказ ошибочного построения записи знака Юникода
					return this->fail(error_t::INVALID_UNICODE, (column + offset));
				// Выполняем переход за разряды записи знака
				offset += count;
				/**
				 * Если записать разобранный знак не удалось
				 *
				 * @note Отказ этот означает суррогат либо знак за пределом набора Юникода:
				 *       записать их последовательностью UTF-8 нельзя вовсе
				 */
				if(!encode(code, result))
					// Выводим отказ ошибочного построения записи знака Юникода
					return this->fail(error_t::INVALID_UNICODE, (column + offset));
			} break;
			/**
			 * Если последовательность не опознана вовсе
			 */
			default: return this->fail(error_t::INVALID_ESCAPE, (column + offset));
		}
	}
	// Выводим признак успешного снятия ограды
	return true;
}
/**
 * @brief Метод поиска конца скалярного значения в разбираемой строке
 *
 * @param line   разбираемая строка
 * @param offset смещение начала значения в строке
 * @param style  вид записи значения, определяемый первым знаком
 * @param length длина записи значения вместе с оградою
 * @return       признак того, что значение прочитано целиком
 *
 */
bool awh::codec::yaml::Reader::bounds(const string_view line, const size_t offset, style_t & style, size_t & length) noexcept {
	/**
	 * Если читать значение неоткуда
	 *
	 * @warning Заход этот НЕДОСТИЖИМ, покуда держится условие: зовущих у поверки
	 *          двое, и оба входят с остатком строки непустым - один прочёл ограду
	 *          `line[offset]` перед вызовом, а второй стоит за поверкой `content`,
	 *          пустое содержимое отсекающей. Замерено покрытием: заход не задет ни разу
	 *
	 * @note Сносу заход не подлежит: без него чтение вида записи взяло бы знак за
	 *       краем строки
	 */
	if(offset >= line.size()){
		// Запоминаем вид записи значения
		style = style_t::PLAIN;
		// Запоминаем длину записи значения
		length = 0;
		// Выводим признак того, что значение прочитано целиком
		return true;
	}
	// Получаем первый знак записи значения
	const char leading = line[offset];
	/**
	 * Если значение обнесено оградою
	 */
	if((leading == '\'') || (leading == '"')){
		// Запоминаем вид записи значения
		style = ((leading == '\'') ? style_t::SINGLE : style_t::DOUBLE);
		// Смещение разбираемого знака записи
		size_t position = (offset + 1);
		/**
		 * Выполняем перебор всех знаков записи значения
		 */
		while(position < line.size()){
			// Получаем очередной знак записи значения
			const char letter = line[position];
			/**
			 * Если ограда двойная, а знак открывает отменяющую последовательность
			 */
			if((style == style_t::DOUBLE) && (letter == '\\')){
				// Выполняем переход за отменяющую последовательность
				position += 2;
				// Выполняем переход к следующему знаку записи
				continue;
			}
			/**
			 * Если знак закрывает ограду значения
			 */
			if(letter == leading){
				/**
				 * Если ограда одинарная, а кавычка удвоена
				 */
				if((style == style_t::SINGLE) && ((position + 1) < line.size()) && (line[position + 1] == '\'')){
					// Выполняем переход за удвоенную кавычку
					position += 2;
					// Выполняем переход к следующему знаку записи
					continue;
				}
				// Запоминаем длину записи значения вместе с оградою
				length = ((position + 1) - offset);
				// Выводим признак того, что значение прочитано целиком
				return true;
			}
			// Выполняем переход к следующему знаку записи
			position++;
		}
		// Выводим признак того, что ограда значения не закрыта
		return false;
	}
	// Запоминаем вид записи значения
	style = style_t::PLAIN;
	// Смещение разбираемого знака записи
	size_t position = offset;
	/**
	 * Выполняем перебор всех знаков записи значения
	 */
	while(position < line.size()){
		// Получаем очередной знак записи значения
		const char letter = line[position];
		/**
		 * Если знак открывает примечание, стоя за пробельным знаком
		 */
		if((letter == '#') && (position > offset) && spacing(line[position - 1]))
			// Выходим из перебора знаков записи значения
			break;
		/**
		 * Если знак разделяет имя пары и значение её
		 *
		 * @note Разделяет он лишь тогда, когда за ним стоит пробельный знак либо конец
		 *       строки: `a:b` есть значение целиком, а `a: b` есть пара
		 */
		if((letter == ':') && (((position + 1) >= line.size()) || spacing(line[position + 1])))
			// Выходим из перебора знаков записи значения
			break;
		// Выполняем переход к следующему знаку записи
		position++;
	}
	// Запоминаем длину записи значения без пробельной обвязки
	length = trimmed(line.substr(offset, (position - offset))).size();
	// Выводим признак того, что значение прочитано целиком
	return true;
}
/**
 * @brief Метод переноса накопленных свойств узла в собранное событие
 *
 * @param item событие, свойства узла принимающее
 *
 */
void awh::codec::yaml::Reader::attach(item_t & item) noexcept {
	/**
	 * Если событию предпослана метка
	 */
	if(!this->_anchor.empty()){
		// Запоминаем смещение имени метки в хранилище знаков
		item.anchor.offset = this->_storage.size();
		// Запоминаем длину имени метки
		item.anchor.length = this->_anchor.size();
		// Выполняем перенос имени метки в хранилище знаков
		this->_storage.append(this->_anchor);
		// Выполняем сброс имени метки, узла своего дождавшейся
		this->_anchor.clear();
	}
	/**
	 * Если событию предпослана метка типа
	 */
	if(!this->_tag.empty()){
		// Запоминаем смещение метки типа в хранилище знаков
		item.tag.offset = this->_storage.size();
		// Запоминаем длину метки типа
		item.tag.length = this->_tag.size();
		// Выполняем перенос метки типа в хранилище знаков
		this->_storage.append(this->_tag);
		// Выполняем сброс метки типа, узла своего дождавшейся
		this->_tag.clear();
	}
}
/**
 * @brief Метод назначения вида пустого значения последнему событию
 *
 * @details Значение, содержимого не имеющее, пустым является по умолчанию - но не тогда,
 * когда метка типа сказала иное: написание `foo: !!str` есть по описанию пустая СТРОКА,
 * а не пустое значение. Разрешение по метке ведёт `typing()`, и назначение пустоты
 * поверх него метку затирало: набор сверки давал `{"foo": ""}`, а дерево - `{"foo": null}`
 *
 * @note Мест назначения десять, и стояло в них назначение безусловное. Свести их в одно
 *       место пришлось затем, что довод у всех один и тот же: пустота есть УМОЛЧАНИЕ, а
 *       умолчание метке уступает. Нашло это сличение дерева с эталонным деревом набора -
 *       поток событий метку нёс верно, и сличение по событиям порока не видело
 *
 */
void awh::codec::yaml::Reader::emptied() noexcept {
	/**
	 * Если последнему событию метка типа СТАНДАРТНАЯ предпослана
	 *
	 * @note Метка своя - местная либо чужого объявления - вида не задаёт: разрешать её
	 *       читающему нечем, и пустота под нею остаётся пустотою. Написание
	 *       `- !<tag:x,2000:mine>` тому порукой - проверка `EmptyRewrite` держит его
	 *       пустым, - а `foo: !!str` есть по описанию пустая строка
	 */
	if(this->_staged.back().tag.length > STANDARD_TAG.size()){
		// Получаем запись метки типа, событию предпосланной
		const string_view tag(this->_storage.data() + this->_staged.back().tag.offset, this->_staged.back().tag.length);
		/**
		 * Если метка типа началом своим описанию отвечает
		 */
		if(tag.compare(0, STANDARD_TAG.size(), STANDARD_TAG) == 0)
			// Выходим из функции, вид меткою разрешённый сохраняя
			return;
	}
	// Устанавливаем вид пустого значения последнему событию
	this->_staged.back().type = type_t::NUL;
}
/**
 * @brief Метод разрешения вида скалярного значения
 *
 * @param text   содержимое скалярного значения
 * @param style  вид записи значения в исходном тексте
 * @param column положение значения в разбираемой строке
 * @param type   разрешённый вид скалярного значения
 * @return       признак успешного разрешения вида
 *
 */
bool awh::codec::yaml::Reader::typing(const string_view text, const style_t style, const size_t column, type_t & type) noexcept {
	/**
	 * Если метка типа значению не предпослана
	 */
	if(this->_tag.empty()){
		/**
		 * Запоминаем вид значения, разрешённый действующей схемой
		 *
		 * @note Значение, обнесённое оградою, схеме не подлежит вовсе - оно строка всегда:
		 *       ограда для того и ставится, чтобы `12` осталось строкой
		 */
		type = ((style == style_t::PLAIN) ? resolve(text, this->_schema) : type_t::STRING);
		// Выводим признак успешного разрешения вида
		return true;
	}
	/**
	 * Если метка типа началом своим описанию не отвечает
	 *
	 * @note Метка своя - местная либо чужого объявления - схеме не подлежит: разрешать её
	 *       читающему нечем, и содержимое остаётся строкою, каким записано
	 */
	if(this->_tag.compare(0, STANDARD_TAG.size(), STANDARD_TAG) != 0){
		// Запоминаем вид значения, меткою своей не разрешаемый
		type = type_t::STRING;
		// Выводим признак успешного разрешения вида
		return true;
	}
	// Получаем окончание метки типа, вид значения задающее
	const string_view suffix = string_view(this->_tag).substr(STANDARD_TAG.size());
	/**
	 * Если метка типа задаёт строку
	 */
	if(suffix == "str"){
		// Запоминаем вид значения, меткою типа заданный
		type = type_t::STRING;
		// Выводим признак успешного разрешения вида
		return true;
	}
	/**
	 * Если метка типа задаёт двоичное содержимое
	 *
	 * @note Запись base64 здесь не сверяется: сверяет её извлечение содержимого, ибо там
	 *       она и разбирается, а разбирать её дважды - работа впустую
	 */
	if(suffix == "binary"){
		// Запоминаем вид значения, меткою типа заданный
		type = type_t::BINARY;
		// Выводим признак успешного разрешения вида
		return true;
	}
	/**
	 * Если метка типа задаёт отметку времени
	 */
	if(suffix == "timestamp"){
		// Запоминаем вид значения, меткою типа заданный
		type = type_t::STAMP;
		// Выводим признак успешного разрешения вида
		return true;
	}
	/**
	 * Если метка типа задаёт построение, скалярным значением не являющееся
	 */
	if((suffix == "seq") || (suffix == "map"))
		// Выводим отказ несоответствия содержимого метке типа
		return this->fail(error_t::TAG_MISMATCH, column);
	/**
	 * Схема, которою сверяется содержимое с меткою типа
	 *
	 * @note Схема защитная объявляет строкою всё подряд, и сверять ею содержимое с меткою
	 *       значило бы отвергнуть `!!int 12`. Метка сказана прямо, и разрешение под неё
	 *       идёт схемою ядровой - либо схемою наречия 1.1, коли текст её объявил
	 */
	const schema_t schema = ((this->_schema == schema_t::LEGACY) ? schema_t::LEGACY : schema_t::CORE);
	// Получаем вид значения, разрешённый схемою по записи его
	const type_t resolved = resolve(text, schema);
	/**
	 * Если метка типа задаёт пустое значение
	 */
	if(suffix == "null"){
		/**
		 * Если содержимое пустым значением не является
		 */
		if((resolved != type_t::NUL) && !text.empty())
			// Выводим отказ несоответствия содержимого метке типа
			return this->fail(error_t::TAG_MISMATCH, column);
		// Запоминаем вид значения, меткою типа заданный
		type = type_t::NUL;
		// Выводим признак успешного разрешения вида
		return true;
	}
	/**
	 * Если метка типа задаёт логическое значение
	 */
	if(suffix == "bool"){
		/**
		 * Если содержимое логическим значением не является
		 */
		if(resolved != type_t::BOOL)
			// Выводим отказ несоответствия содержимого метке типа
			return this->fail(error_t::TAG_MISMATCH, column);
		// Запоминаем вид значения, меткою типа заданный
		type = type_t::BOOL;
		// Выводим признак успешного разрешения вида
		return true;
	}
	/**
	 * Если метка типа задаёт целое число
	 */
	if(suffix == "int"){
		/**
		 * Если содержимое числом не является вовсе
		 *
		 * @details Сверяется здесь именно числовая природа записи, а не целость её: разбор
		 *          записи числа - работа извлечения, и он там и делается. Требовать целости
		 *          здесь значило бы завести второй свод правил чтения чисел рядом с первым,
		 *          а два свода расходятся всегда. Запись `.inf`, разрешённая дробным видом
		 *          прямо, сюда всё же не пройдёт: целым она не бывает никогда
		 */
		if(!(static_cast <uint32_t> (resolved) & static_cast <uint32_t> (type_t::INT)))
			// Выводим отказ несоответствия содержимого метке типа
			return this->fail(error_t::TAG_MISMATCH, column);
		// Запоминаем вид значения, меткою типа заданный
		type = type_t::INT;
		// Выводим признак успешного разрешения вида
		return true;
	}
	/**
	 * Если метка типа задаёт дробное число
	 */
	if(suffix == "float"){
		/**
		 * Если содержимое числом не является вовсе
		 */
		if(!(static_cast <uint32_t> (resolved) & static_cast <uint32_t> (type_t::NUMBER)))
			// Выводим отказ несоответствия содержимого метке типа
			return this->fail(error_t::TAG_MISMATCH, column);
		/**
		 * Запоминаем вид значения, меткою типа заданный
		 *
		 * @note Целое, меткою `!!float` помеченное, дробным и становится: метка сказана
		 *       прямо, и `!!float 1` есть единица дробная, а не целая
		 */
		type = type_t::REAL;
		// Выводим признак успешного разрешения вида
		return true;
	}
	/**
	 * Запоминаем вид значения, меткою описания не разрешаемый
	 *
	 * @note Метка начала описанного, но окончания неведомого, разрешению не подлежит:
	 *       наречия последующие вправе завести свои, и отвергать их нельзя
	 */
	type = type_t::STRING;
	// Выводим признак успешного разрешения вида
	return true;
}
/**
 * @brief Метод разбора свойств узла, стоящих прежде него
 *
 * @param line   разбираемая строка
 * @param offset смещение начала свойств в строке, по выходе - смещение за ними
 * @return       признак успешного разбора свойств узла
 *
 */
bool awh::codec::yaml::Reader::property(const string_view line, size_t & offset) noexcept {
	/**
	 * Выполняем разбор всех свойств, узлу предпосланных
	 */
	while(offset < line.size()){
		// Получаем первый знак разбираемого свойства
		const char leading = line[offset];
		/**
		 * Если свойство объявляет метку узла
		 */
		if(leading == '&'){
			/**
			 * Если метка узлу уже предпослана
			 */
			if(!this->_anchor.empty()){
				/**
				 * Если метка предпослана была в этой же строке
				 *
				 * @note Двух меток один узел не несёт: описание дозволяет узлу метку одну
				 */
				if(this->_anchoredHere || !this->_delayed.empty())
					// Выводим отказ недопустимого знака в этом месте текста
					return this->fail(error_t::INVALID_CHARACTER, offset);
				/**
				 * Выполняем откладывание прежней метки вместилищу
				 *
				 * @details Метка, строкою выше объявленная, принадлежит вместилищу, какое
				 *          строка эта открывает, а не имени пары её: написание `top: &m`
				 *          со строкою `&k имя: значение` ниже несёт метку вместилища и
				 *          метку имени разом
				 */
				this->_delayed.swap(this->_anchor);
			}
			// Получаем смещение начала имени метки
			const size_t begin = (offset + 1);
			// Смещение разбираемого знака строки
			size_t position = begin;
			/**
			 * Выполняем чтение имени метки до первого знака, ему не принадлежащего
			 */
			while((position < line.size()) && naming(line[position]))
				// Выполняем переход к следующему знаку строки
				position++;
			/**
			 * Если имя метки пусто
			 */
			if(position == begin)
				// Выводим отказ недопустимого знака в этом месте текста
				return this->fail(error_t::INVALID_CHARACTER, offset);
			/**
			 * Если длина имени метки предел превышает
			 */
			if((position - begin) > MAX_ANCHOR)
				// Выводим отказ превышения длины имени метки
				return this->fail(error_t::ANCHOR_TOO_LONG, offset);
			// Запоминаем имя метки, узла своего ожидающей
			this->_anchor.assign(line.substr(begin, (position - begin)));
			// Запоминаем признак объявления метки узла в разбираемой строке
			this->_anchoredHere = true;
			/**
			 * Запоминаем метку среди объявленных документом
			 *
			 * @note Повторное объявление имени описанием дозволено и отказом не является:
			 *       ссылки последующие указывают на объявление последнее, а прежнее
			 *       остаётся у ссылок, прежде него стоявших
			 */
			this->_anchors.emplace(this->_anchor);
			// Выполняем переход за разобранное свойство
			offset = position;
		/**
		 * Если свойство объявляет метку типа
		 */
		} else if(leading == '!') {
			/**
			 * Если метка типа узлу уже предпослана
			 */
			if(!this->_tag.empty()){
				/**
				 * Если метка типа предпослана была в этой же строке
				 *
				 * @note Двух меток типа один узел не несёт: описание дозволяет узлу метку одну
				 */
				if(this->_taggedHere || !this->_delayedTag.empty())
					// Выводим отказ недопустимого знака в этом месте текста
					return this->fail(error_t::INVALID_CHARACTER, offset);
				/**
				 * Выполняем откладывание прежней метки типа вместилищу
				 *
				 * @details Метка типа, строкою выше объявленная, принадлежит вместилищу,
				 *          какое строка эта открывает, а не имени пары её - ровно как и
				 *          метка узла
				 */
				this->_delayedTag.swap(this->_tag);
			}
			// Запоминаем признак объявления метки типа в разбираемой строке
			this->_taggedHere = true;
			// Смещение разбираемого знака строки
			size_t position = (offset + 1);
			/**
			 * Если метка типа записана указателем дословно
			 */
			if((position < line.size()) && (line[position] == '<')){
				// Разыскиваем знак окончания дословной записи
				const size_t closing = line.find('>', position);
				/**
				 * Если дословная запись не закрыта либо пуста
				 */
				if((closing == string_view::npos) || (closing == (position + 1)))
					// Выводим отказ ошибочного построения метки типа
					return this->fail(error_t::INVALID_TAG, offset);
				/**
				 * Выполняем перебор всех знаков дословной записи метки типа
				 *
				 * @details Описание дозволяет в записи этой одни лишь знаки URI: знак
				 *          пробельный да знак управляющий среди них не значатся. Прежде
				 *          бралось всё, что стоит между скобками, и метка с табуляцией
				 *          принималась молча - а учёт границ записей сбивался на ней:
				 *          правка узла оставляла запись его прежнюю в тексте, дописывая
				 *          значение новое соседом ей
				 *
				 * @note Знаки не-ASCII не трогаются: описание велит записывать их долями
				 *       вида `%D0%B0`, но запись дословная их принимает, и сужать её здесь
				 *       значило бы ломать то, что работает. Нашёл это ворошитель длинным
				 *       прогоном
				 */
				for(size_t i = (position + 1); i < closing; i++){
					/**
					 * Если знак записи пробельным либо управляющим является
					 */
					if(::spacing(line[i]) || (static_cast <unsigned char> (line[i]) < 0x20) ||
					   (static_cast <unsigned char> (line[i]) == 0x7F))
						// Выводим отказ ошибочного построения метки типа
						return this->fail(error_t::INVALID_TAG, offset);
				}
				// Запоминаем метку типа, узла своего ожидающую
				this->_tag.assign(line.substr((position + 1), (closing - position - 1)));
				/**
				 * Если раскрыть долевые записи знаков метки типа не удалось
				 */
				if(!unescaped(this->_tag))
					// Выводим отказ ошибочного построения метки типа
					return this->fail(error_t::INVALID_TAG, offset);
				// Выполняем переход за разобранное свойство
				offset = (closing + 1);
			/**
			 * Если метка типа записана сокращением
			 */
			} else {
				// Получаем смещение начала окончания метки типа
				size_t begin = position;
				/**
				 * Выполняем чтение записи метки до первого знака, ей не принадлежащего
				 */
				while((position < line.size()) && tagging(line[position]) &&
				      !separated(line, position))
					// Выполняем переход к следующему знаку строки
					position++;
				// Сокращение метки типа, начало её задающее
				string handle("!");
				/**
				 * Если прочитанное есть сокращение метки типа, а не окончание её
				 *
				 * @note Отличить одно от другого можно лишь знаком, следом стоящим:
				 *       восклицательный знак за прочитанным делает его сокращением
				 */
				if((position < line.size()) && (line[position] == '!')){
					// Запоминаем сокращение метки типа вместе с обоими знаками его
					handle.assign(line.substr(offset, (position - offset + 1)));
					// Выполняем переход за сокращение метки типа
					position++;
					// Запоминаем смещение начала окончания метки типа
					begin = position;
					/**
					 * Выполняем чтение окончания метки типа
					 */
					while((position < line.size()) && tagging(line[position]) &&
					      !separated(line, position))
						// Выполняем переход к следующему знаку строки
						position++;
				}
				// Начало метки типа, сокращением её задаваемое
				string_view prefix(handle);
				/**
				 * Если сокращение объявлено директивою документа
				 */
				const auto i = this->_handles.find(handle);
				/**
				 * Если сокращение объявлено директивою документа
				 */
				if(i != this->_handles.end())
					// Запоминаем начало метки типа, директивою объявленное
					prefix = i->second;
				/**
				 * Если сокращение есть сокращение описания
				 */
				else if(handle.compare("!!") == 0)
					// Запоминаем начало метки типа, описанием заданное
					prefix = STANDARD_TAG;
				/**
				 * Если сокращение объявлено не было вовсе
				 *
				 * @note Сокращение `!` объявления не требует: оно есть начало меток местных,
				 *       и объявлено оно всегда. Прочие же объявляются директивой `%TAG`, и
				 *       без объявления читающий не знает, во что их раскрывать
				 */
				else if(handle.compare("!") != 0)
					// Выводим отказ необъявленного сокращения метки типа
					return this->fail(error_t::UNKNOWN_TAG_HANDLE, offset);
				/**
				 * Если запись метки оборвалась знаком, ей не принадлежащим
				 *
				 * @note Знаки записи метки типа описанием заданы перечнем, и знаков вне
				 *       перечня того - хотя бы и буквы иной письменности - метка нести не
				 *       вправе: записываются они долею с точкою кода, а не собою
				 */
				if((position == begin) && (position < line.size()) && !spacing(line[position]) &&
				 !(!this->_flow.empty() && ((line[position] == ',') || (line[position] == '}') || (line[position] == ']'))))
					// Выводим отказ ошибочного построения метки типа
					return this->fail(error_t::INVALID_TAG, offset);
				// Собираем метку типа из начала её и окончания
				this->_tag.assign(prefix);
				// Выполняем присоединение окончания метки типа
				this->_tag.append(line.substr(begin, (position - begin)));
				/**
				 * Если раскрыть долевые записи знаков метки типа не удалось
				 *
				 * @note Раскрывается метка целиком, а не окончание её: начало, директивой
				 *       `%TAG` объявленное, записью тою же задаётся. Случай 6CK3 набора
				 *       yaml-test-suite
				 */
				if(!unescaped(this->_tag))
					// Выводим отказ ошибочного построения метки типа
					return this->fail(error_t::INVALID_TAG, offset);
				// Выполняем переход за разобранное свойство
				offset = position;
			}
		// Если знак свойством узла не является
		} else break;
		// Запоминаем признак разбора свойств узла в этой строке
		this->_propped = true;
		/**
		 * Если за разобранным свойством содержимое строки исчерпано
		 */
		if(offset >= line.size())
			// Выводим признак успешного разбора свойств узла
			return true;
		/**
		 * Если за разобранным свойством стоит знак, пробельным не являющийся
		 *
		 * @note Свойства отделяются пробельными знаками и от узла своего, и друг от друга:
		 *       запись `&метка!тип` описанию противна, и разбирать её наугад нельзя
		 */
		if(!spacing(line[offset])){
			/**
			 * Если знак ограду поточного построения завершает
			 *
			 * @note Внутри построения свойство завершается запятой либо скобкой закрывающей,
			 *       а не одним лишь пробелом: написание `[!!str, xxx]` описанию отвечает.
			 *       Вне построения знаки эти свойству чужие, и написание `- !!str, xxx`
			 *       есть ошибка
			 */
			if(!this->_flow.empty() && ((line[offset] == ',') || (line[offset] == ']') || (line[offset] == '}')))
				// Выводим признак успешного разбора свойств узла
				return true;
			/**
			 * Если знак разделителем имени пары является
			 *
			 * @details Свойство, за каким сразу стоит разделитель, принадлежит имени пары
			 * ПУСТОМУ: описание правилом `c-l-block-map-implicit-entry` дозволяет имени
			 * быть пустым узлом со своими свойствами, и написание `!t: v` есть пара с
			 * именем пустым, меткою `!t` помеченным, и значением `v`
			 *
			 * @warning Прежде двоеточие поглощалось самим розыском метки - описание числит
			 *          его знаком записи метки правилом `ns-tag-char`, - и написание это
			 *          обращалось скаляром `v` с меткою `t:`, а пара пропадала вовсе. Тем
			 *          сбивалась разбивка на пары у всего отображения: имя своего события
			 *          не получало, и значение соседа снизу становилось именем его.
			 *          Розыск метки на разделителе теперь останавливается, а заход этот
			 *          принимает то, что за ним осталось
			 */
			if(this->_flow.empty() && (line[offset] == ':') &&
			   (((offset + 1) >= line.size()) || spacing(line[offset + 1])))
				// Выводим признак успешного разбора свойств узла
				return true;
			// Выводим отказ недопустимого знака в этом месте текста
			return this->fail(error_t::INVALID_CHARACTER, offset);
		}
		/**
		 * Выполняем пропуск пробельных знаков за разобранным свойством
		 */
		while((offset < line.size()) && spacing(line[offset]))
			// Выполняем переход к следующему знаку строки
			offset++;
	}
	// Выводим признак успешного разбора свойств узла
	return true;
}
/**
 * @brief Метод разбора ссылки на объявленную метку
 *
 * @param line   разбираемая строка
 * @param offset смещение начала ссылки в строке, по выходе - смещение за нею
 * @return       признак успешного разбора ссылки
 *
 */
bool awh::codec::yaml::Reader::referred(const string_view line, size_t & offset) noexcept {
	/**
	 * Если ссылке предпослано свойство узла
	 *
	 * @note Ссылка узлом не является - она указывает на узел, прежде объявленный, - и
	 *       своих свойств иметь не вправе: свойства эти были бы отнесены к узлу чужому
	 */
	if(!this->_anchor.empty() || !this->_tag.empty())
		// Выводим отказ недопустимого знака в этом месте текста
		return this->fail(error_t::INVALID_CHARACTER, offset);
	// Получаем смещение начала имени метки, ссылкою указанной
	const size_t begin = (offset + 1);
	// Смещение разбираемого знака строки
	size_t position = begin;
	/**
	 * Выполняем чтение имени метки до первого знака, ему не принадлежащего
	 */
	while((position < line.size()) && naming(line[position]))
		// Выполняем переход к следующему знаку строки
		position++;
	/**
	 * Если имя метки пусто
	 */
	if(position == begin)
		// Выводим отказ недопустимого знака в этом месте текста
		return this->fail(error_t::INVALID_CHARACTER, offset);
	// Получаем имя метки, ссылкою указанной
	const string_view name = line.substr(begin, (position - begin));
	/**
	 * Если метка с таким именем документом не объявлена
	 *
	 * @note Описание велит метке стоять прежде ссылки на неё, и ссылка вперёд объявления
	 *       есть отказ: раскрыть её потребитель не сможет ничем
	 */
	if(this->_anchors.find(string(name)) == this->_anchors.end())
		// Выводим отказ ссылки на необъявленную метку
		return this->fail(error_t::UNKNOWN_ALIAS, offset);
	// Выполняем постановку события ссылки на объявленную метку
	item_t & item = this->emit(event_t::ALIAS, offset);
	// Запоминаем смещение содержимого события в хранилище знаков
	item.offset = this->_storage.size();
	// Запоминаем длину содержимого события
	item.length = name.size();
	// Выполняем перенос содержимого события в хранилище знаков
	this->_storage.append(name);
	// Запоминаем признак наполнения открытого документа
	this->_filled = true;
	// Выполняем переход за разобранную ссылку
	offset = position;
	// Выводим признак успешного разбора ссылки
	return true;
}
/**
 * @brief Метод разбора директивы, документу предпосланной
 *
 * @param line   разбираемая строка
 * @param offset смещение начала директивы в строке
 * @return       признак успешного разбора директивы
 *
 */
bool awh::codec::yaml::Reader::directive(const string_view line, const size_t offset) noexcept {
	/**
	 * Если документ уже открыт
	 *
	 * @note Директива правит толкование документа целиком, и стоять посреди него она не
	 *       вправе: половина документа оказалась бы прочитана одними правилами, половина иными
	 */
	if(this->_opened)
		// Выводим отказ ошибочного построения директивы
		return this->fail(error_t::INVALID_DIRECTIVE, offset);
	// Получаем смещение начала имени директивы
	const size_t begin = (offset + 1);
	// Смещение разбираемого знака строки
	size_t position = begin;
	/**
	 * Выполняем чтение имени директивы до первого пробельного знака
	 */
	while((position < line.size()) && !spacing(line[position]))
		// Выполняем переход к следующему знаку строки
		position++;
	// Получаем имя разбираемой директивы
	const string_view name = line.substr(begin, (position - begin));
	/**
	 * Если имя директивы пусто
	 */
	if(name.empty())
		// Выводим отказ ошибочного построения директивы
		return this->fail(error_t::INVALID_DIRECTIVE, offset);
	// Получаем остаток строки за именем директивы
	string_view rest = line.substr(position);
	/**
	 * Разыскиваем знак примечания в остатке строки
	 */
	for(size_t i = 0; i < rest.size(); i++){
		/**
		 * Если знак примечания стоит за пробельным знаком
		 */
		if((rest[i] == '#') && ((i == 0) || spacing(rest[i - 1]))){
			// Выполняем снятие примечания с остатка строки
			rest = rest.substr(0, i);
			// Выходим из поиска знака примечания
			break;
		}
	}
	// Выполняем снятие пробельной обвязки с остатка строки
	rest = stripped(rest);
	// Запоминаем признак предпосланных документу директив
	this->_directed = true;
	/**
	 * Если директива объявляет наречие текста
	 */
	if(name.compare("YAML") == 0){
		/**
		 * Если наречие объявлено директивою уже
		 */
		if(this->_versioned)
			// Выводим отказ ошибочного построения директивы
			return this->fail(error_t::INVALID_DIRECTIVE, offset);
		// Разыскиваем разделитель старшего и младшего чисел наречия
		const size_t separator = rest.find('.');
		/**
		 * Если разделителя чисел наречия в записи нет вовсе
		 */
		if(separator == string_view::npos)
			// Выводим отказ ошибочного построения директивы
			return this->fail(error_t::INVALID_DIRECTIVE, offset);
		// Получаем старшее число объявленного наречия
		const string_view major = rest.substr(0, separator);
		// Получаем младшее число объявленного наречия
		const string_view minor = rest.substr(separator + 1);
		/**
		 * Если хоть одно из чисел наречия числом не является
		 */
		if(major.empty() || minor.empty() ||
		   (major.find_first_not_of("0123456789") != string_view::npos) ||
		   (minor.find_first_not_of("0123456789") != string_view::npos))
			// Выводим отказ ошибочного построения директивы
			return this->fail(error_t::INVALID_DIRECTIVE, offset);
		/**
		 * Если объявленное наречие чтением не поддерживается
		 *
		 * @details Описание различает два случая: наречие с иным СТАРШИМ числом читать
		 *          нельзя вовсе - устройство языка там иное, - а наречие с младшим числом
		 *          выше нашего читается наречием последним известным. Второе есть указание
		 *          описания, а не поблажка: текст, писанный наречием будущим, разбирается
		 *          сколько сможется, и разойтись он вправе лишь в том, чего мы не знаем
		 *
		 * @note Прежде отвергались оба разом, и `%YAML 1.3` отказ получал наравне с
		 *       `%YAML 2.0`. Случай BEC7 набора yaml-test-suite
		 */
		if(major.compare("1") != 0)
			// Выводим отказ неподдерживаемого наречия текста
			return this->fail(error_t::UNSUPPORTED_VERSION, offset);
		// Запоминаем признак объявленного директивой наречия
		this->_versioned = true;
		// Запоминаем признак объявленного директивой наречия за весь текст
		this->_declared = true;
		/**
		 * Если текст объявлен наречием 1.1, а схема разрешения потребителем не назначена
		 *
		 * @details Наречие 1.1 разрешает виды иначе: `yes` там есть истина, `0777` есть
		 *          восьмеричное число, а `12:30` есть число шестидесятиричное. Объявив
		 *          наречие, текст сказал об этом прямо, и читать его схемою ядровой значило
		 *          бы прочесть не то, что писано. Схему же, потребителем назначенную,
		 *          текст перебивать не вправе: назначил её потребитель осознанно
		 */
		if((minor.compare("1") == 0) && (this->_settings.schema == schema_t::CORE))
			// Запоминаем схему наречия 1.1 действующей над документом
			this->_schema = schema_t::LEGACY;
		// Запоминаем схему, директивой наречия назначенную
		this->_dialect = this->_schema;
		// Выводим признак успешного разбора директивы
		return true;
	}
	/**
	 * Если директива объявляет сокращение метки типа
	 */
	if(name.compare("TAG") == 0){
		// Разыскиваем разделитель сокращения и начала метки типа
		const size_t separator = rest.find(' ');
		/**
		 * Если разделителя сокращения и начала метки в записи нет вовсе
		 */
		if(separator == string_view::npos)
			// Выводим отказ ошибочного построения директивы
			return this->fail(error_t::INVALID_DIRECTIVE, offset);
		// Получаем объявляемое сокращение метки типа
		const string_view handle = rest.substr(0, separator);
		// Получаем начало метки типа, сокращением задаваемое
		const string_view prefix = stripped(rest.substr(separator + 1));
		/**
		 * Если сокращение построено ошибочно
		 *
		 * @note Сокращение обносится восклицательными знаками с обеих сторон, и знак один
		 *       есть сокращение меток местных - оно тоже дозволено
		 */
		if((handle.size() < 1) || (handle.front() != '!') || (handle.back() != '!'))
			// Выводим отказ ошибочного построения директивы
			return this->fail(error_t::INVALID_DIRECTIVE, offset);
		/**
		 * Если начало метки типа пусто
		 *
		 * @warning Страж этот затенён снятием обвязки пробельной: запись директивы
		 *          приходит сюда без пробелов по краям, и разделитель, в ней стоящий,
		 *          пустого хвоста за собою оставить не может. Запись `%TAG !e!` до
		 *          сюда не доходит вовсе - её отвергает отсутствие разделителя выше.
		 *          Замер это и показал: место не задето ни набором проверок, ни
		 *          корпусом yaml-test-suite, ни ворошителем
		 *
		 * @note Страж оставлен заставою последнего рубежа: снятие обвязки стоит выше
		 *       по разбору, и разойдись оно с ожиданием, пустое начало ушло бы в
		 *       объявленные сокращения молча
		 */
		if(prefix.empty())
			// Выводим отказ ошибочного построения директивы
			return this->fail(error_t::INVALID_DIRECTIVE, offset);
		/**
		 * Если сокращение объявлено директивою уже
		 *
		 * @note Второе объявление того же сокращения описанием запрещено прямо: неведомо,
		 *       которое из двух начал имел в виду писавший
		 */
		if(!this->_handles.emplace(string(handle), string(prefix)).second)
			// Выводим отказ ошибочного построения директивы
			return this->fail(error_t::INVALID_DIRECTIVE, offset);
		// Выводим признак успешного разбора директивы
		return true;
	}
	// Выводим признак успешного разбора директивы
	return true;
}
/**
 * @brief Метод разбора содержимого строки за отступом
 *
 * @param line   разбираемая строка без знака конца строки
 * @param offset смещение начала содержимого в строке
 * @param indent отступ, на котором содержимое стоит
 * @return       признак успешного разбора содержимого
 *
 */
bool awh::codec::yaml::Reader::content(const string_view line, const size_t offset, const uint32_t indent) noexcept {
	/**
	 * Если содержимое строки исчерпано
	 */
	if(offset >= line.size())
		// Выводим признак успешного разбора содержимого
		return true;
	// Получаем первый знак содержимого строки
	const char leading = line[offset];
	/**
	 * Если содержимое открывается вопросом составного имени
	 *
	 * @details Имя, вопросом объявленное, есть узел наравне со значением своим, и событиями
	 *          выдаётся оно так же, как имя обычной пары: скалярное значение имени, за ним
	 *          скалярное значение пары. Двоеточие строкою ниже объявляет значение
	 *
	 * @note Имя, самo построением являющееся, дереву деть некуда - узел пары имя своё
	 *       записью держит, а не поддеревом, - и отвергается оно ниже, при постановке
	 *       события построения на месте имени
	 */
	if((leading == '?') && (((offset + 1) >= line.size()) || spacing(line[offset + 1]))){
		/**
		 * Если уровень отображения на этом отступе ещё не открыт
		 */
		if(this->_levels.empty() || (this->_levels.back().indent < indent) ||
		   (this->_levels.back().kind != nesting_t::MAPPING)){
			/**
			 * Если перечень и отображение смешаны на одном уровне
			 */
			if(!this->_levels.empty() && (this->_levels.back().indent == indent) &&
			   (this->_levels.back().kind != nesting_t::MAPPING))
				// Выводим отказ смешения перечня и отображения на одном уровне
				return this->fail(error_t::MIXED_COLLECTION, offset);
			/**
			 * Если открыть уровень отображения не удалось
			 */
			if(!this->expand(nesting_t::MAPPING, indent, false, offset))
				// Выводим признак неудачного разбора содержимого
				return false;
		}
		// Запоминаем признак имени, вопросом объявленного
		this->_asked = true;
		// Запоминаем отступ, на котором стоит вопрос составного имени
		this->_questioned = indent;
		// Запоминаем количество открытых уровней на миг объявления имени вопросом
		this->_asking = this->_levels.size();
		// Получаем смещение содержимого за вопросом составного имени
		size_t position = (offset + 1);
		/**
		 * Выполняем пропуск пробельных знаков за вопросом составного имени
		 */
		while((position < line.size()) && spacing(line[position])){
			/**
			 * Если пробельный знак есть знак горизонтальной подачи
			 *
			 * @details Построение вложенное отступ свой берёт правилом `s-indent` описания, а
			 *          тот задан одними пробелами: подача отступом не является, и написание
			 *          `?<подача>-` отступа вложенному построению не даёт вовсе
			 *
			 * @note Случай Y79Y набора yaml-test-suite
			 */
			if(line[position] == '\t')
				// Запоминаем признак подачи в отступе вложенного построения
				this->_tabbed = true;
			// Выполняем переход к следующему знаку строки
			position++;
		}
		/**
		 * Запоминаем признак ожидания имени пары
		 *
		 * @note Признак тот же, каким ожидается значение пары: имя, вопросом объявленное и
		 *       строкою своей не заполненное, пустоту получает ровно так же
		 */
		this->_expected = true;
		/**
		 * Выполняем сброс признака ожидания значения имени
		 *
		 * @note Ожидается здесь имя, а не значение его: пустота имени принадлежит
		 *       отображению вопроса прямо, и закрывать перед нею нечего
		 */
		this->_answering = false;
		// Выполняем сброс признака принадлежности ожидаемого значения записи перечня
		this->_entered = false;
		// Запоминаем отступ, на котором ожидается имя пары
		this->_pending = indent;
		// Запоминаем смещение, на котором ожидается имя пары
		this->_awaiting.offset = (this->_position + position);
		// Запоминаем строку, на которой ожидается имя пары
		this->_awaiting.line = this->_line;
		// Запоминаем столбец, на котором ожидается имя пары
		this->_awaiting.column = static_cast <uint32_t> (position + 1);
		/**
		 * Если содержимое строки исчерпано либо за ним стоит одно примечание
		 */
		if((position >= line.size()) || (line[position] == '#')){
			/**
			 * Если за вопросом составного имени стоит примечание
			 */
			if(position < line.size())
				// Выполняем постановку события примечания
				this->remark(line, position);
			// Выводим признак успешного разбора содержимого
			return true;
		}
		// Выполняем разбор имени пары, за вопросом стоящего
		return this->content(line, position, static_cast <uint32_t> (position));
	}
	/**
	 * Если содержимое открывается двоеточием значения составного имени
	 *
	 * @details Двоеточие это объявляет значение имени, вопросом объявленного прежде, и
	 *          стоит оно на том же отступе, что и вопрос. Без него имя получает пустоту
	 *
	 * @note Двоеточие, вопроса не дождавшееся, объявляет пару с именем пустым: описание
	 *       того дозволяет, и имя такое выдаётся пустым скалярным значением
	 */
	if((leading == ':') && (((offset + 1) >= line.size()) || spacing(line[offset + 1]))){
		/**
		 * Признак того, что двоеточие есть ответ вопросу, имя объявившему
		 *
		 * @details Двоеточие ответа стоит ровно на отступе вопроса своего: описание
		 *          правилом `c-l-block-map-explicit-value` держит его на отступе правила
		 *          `c-l-block-map-explicit-key`. Двоеточие глубже вопроса ответом ему не
		 *          является вовсе - оно открывает пару вложенную, и пара эта есть часть
		 *          имени составного, а пустоту своего значения имя получит концом своим
		 *
		 * @note Прежде сличения отступа не было, и написание `- ? : x` читалось одною
		 *       парою с именем пустым: имя составное пропадало, а вместе с ним и пустота
		 *       значения его. Случай M2N8 набора yaml-test-suite
		 */
		const bool answered = (this->_asked && (indent == this->_questioned));
		/**
		 * Если имя вопросом объявлялось
		 *
		 * @details Имя, вопросом объявленное, вправе быть построением, и стоит оно на
		 *          отступе самого вопроса: закрыть его отступом нельзя - отступ у имени и
		 *          у двоеточия один. Оттого закрывается оно счётом уровней: двоеточие
		 *          снимает всё, что открылось за вопросом его
		 *
		 * @note Прежде перечень имени и перечень значения сливались в один: записи
		 *       второго дописывались к первому. Случай 6PBE набора yaml-test-suite
		 */
		if(answered){
			/**
			 * Выполняем закрытие всех уровней, за вопросом открытых
			 */
			while(this->_levels.size() > this->_asking){
				// Получаем вид закрываемого уровня вложенности
				const nesting_t kind = this->_levels.back().kind;
				// Выполняем снятие закрываемого уровня со стопы
				this->_levels.pop_back();
				// Выполняем постановку события закрытия уровня
				this->emit(((kind == nesting_t::MAPPING) ? event_t::MAPPING_END : event_t::SEQUENCE_END), offset);
			}
		}
		/**
		 * Если имя вопросом не объявлялось
		 */
		if(!answered){
			/**
			 * Выполняем закрытие уровней перечня, отступа своего не имеющих
			 *
			 * @details Перечень, значением пары стоящий, вправе держаться отступа самой
			 * пары: написание `a:\n- x\nb: 1` описанию отвечает, и пара `b` есть сестра
			 * паре `a`, а не запись перечня. Уровень такой оттого закрывается всякою парою
			 * на своём отступе
			 *
			 * @warning Закрытие это стояло лишь у пары ИМЕНОВАННОЙ, а у пары с именем
			 *          пустым его не было вовсе: написание `a:\n- x\n: 1` отвергалось
			 *          отказом «перечень и отображение смешаны», хотя от принимаемого
			 *          отличается одним лишь именем. Всплыло это перезаписью: запись
			 *          обращала поточный перечень блочным, и текст, ею собранный, обратно
			 *          не читался
			 */
			while(!this->_levels.empty() && (this->_levels.back().indent == indent) &&
			      (this->_levels.back().kind == nesting_t::SEQUENCE) && this->_levels.back().implied){
				// Выполняем снятие закрываемого уровня со стопы
				this->_levels.pop_back();
				// Выполняем постановку события закрытия перечня
				this->emit(event_t::SEQUENCE_END, offset);
			}
			/**
			 * Если уровень отображения на этом отступе ещё не открыт
			 */
			if(this->_levels.empty() || (this->_levels.back().indent < indent) ||
			   (this->_levels.back().kind != nesting_t::MAPPING)){
				/**
				 * Если перечень и отображение смешаны на одном уровне
				 */
				if(!this->_levels.empty() && (this->_levels.back().indent == indent) &&
				   (this->_levels.back().kind != nesting_t::MAPPING))
					// Выводим отказ смешения перечня и отображения на одном уровне
					return this->fail(error_t::MIXED_COLLECTION, offset);
				/**
				 * Свойства узла, имени пары принадлежащие
				 *
				 * @details Свойства, в этой же строке разобранные, принадлежат имени пары,
				 *          а не отображению, её несущему: написание `!!null : a` метку типа
				 *          отдаёт имени пустому, а метка эта пустоте отвечает. Прежде она
				 *          доставалась отображению и отвергалась несоответствием виду
				 *
				 * @note Правило то же, каким свойства отделяются у имени пары обычной.
				 *       Случай FH7J набора yaml-test-suite
				 */
				string anchor, tag;
				/**
				 * Если свойства узла разобраны в этой же строке
				 */
				if(this->_propped){
					// Выполняем изъятие метки узла у открываемого отображения
					anchor.swap(this->_anchor);
					// Выполняем изъятие метки типа у открываемого отображения
					tag.swap(this->_tag);
				}
				// Признак успешного открытия уровня отображения
				const bool opened = this->expand(nesting_t::MAPPING, indent, false, offset);
				/**
				 * Если метка узла изъята была
				 */
				if(!anchor.empty())
					// Выполняем возврат метки узла имени пары
					this->_anchor.swap(anchor);
				/**
				 * Если метка типа изъята была
				 */
				if(!tag.empty())
					// Выполняем возврат метки типа имени пары
					this->_tag.swap(tag);
				/**
				 * Если открыть уровень отображения не удалось
				 */
				if(!opened)
					// Выводим признак неудачного разбора содержимого
					return false;
			}
			/**
			 * Если поставить событие пустого имени пары не удалось
			 *
			 * @warning Заход этот НЕДОСТИЖИМ, покуда держится условие: событие пустоты ставится
			 *          там, где метки вида уже нет, а без метки разрешение вида отказа не даёт -
			 *          запись пустая ни предела длины не превышает, ни метки порядка байтов не
			 *          несёт. Замерено шестнадцатью записями с меткою `!!bool` над пустотою
			 *          построения поточного: ни одна сюда не дошла - метку забирает заход
			 *          скалярного значения раньше
			 *
			 * @note Сносу заход не подлежит: у закрытия документа метка до пустоты доживает, и
			 *       там отказ этот управление получает - проверка `TagsAndAnchors` тому порукой
			 */
			if(!this->scalar(string(), style_t::PLAIN, offset))
				// Выводим признак неудачного разбора содержимого
				return false;
			// Устанавливаем вид пустого имени последнему событию
			this->emptied();
		}
		/**
		 * Если двоеточие есть ответ вопросу, имя объявившему
		 */
		if(answered)
			// Выполняем сброс признака имени, вопросом объявленного
			this->_asked = false;
		// Получаем смещение содержимого за двоеточием значения
		size_t position = (offset + 1);
		/**
		 * Выполняем пропуск пробельных знаков за двоеточием значения
		 */
		while((position < line.size()) && spacing(line[position])){
			/**
			 * Если пробельный знак есть знак горизонтальной подачи
			 *
			 * @details Построение вложенное отступ свой берёт правилом `s-indent` описания, а
			 *          тот задан одними пробелами: подача отступом не является, и написание
			 *          `:<подача>-` отступа вложенному построению не даёт вовсе
			 *
			 * @note Случай Y79Y набора yaml-test-suite
			 */
			if(line[position] == '\t')
				// Запоминаем признак подачи в отступе вложенного построения
				this->_tabbed = true;
			// Выполняем переход к следующему знаку строки
			position++;
		}
		// Запоминаем признак ожидания значения пары
		this->_expected = true;
		// Выполняем сброс признака принадлежности ожидаемого значения записи перечня
		this->_entered = false;
		// Запоминаем отступ, на котором ожидается значение пары
		this->_pending = indent;
		// Запоминаем смещение, на котором ожидается значение пары
		this->_awaiting.offset = (this->_position + position);
		// Запоминаем строку, на которой ожидается значение пары
		this->_awaiting.line = this->_line;
		// Запоминаем столбец, на котором ожидается значение пары
		this->_awaiting.column = static_cast <uint32_t> (position + 1);
		/**
		 * Если содержимое строки исчерпано либо за ним стоит одно примечание
		 */
		if((position >= line.size()) || (line[position] == '#')){
			/**
			 * Если за двоеточием значения стоит примечание
			 */
			if(position < line.size())
				// Выполняем постановку события примечания
				this->remark(line, position);
			// Выводим признак успешного разбора содержимого
			return true;
		}
		// Выполняем разбор значения пары, за двоеточием стоящего
		return this->content(line, position, static_cast <uint32_t> (position));
	}
	/**
	 * Если содержимое открывается вопросом, за каким пробельного знака нет
	 *
	 * @note Вопрос составное имя объявляет лишь тогда, когда за ним стоит пробельный знак
	 *       либо конец строки: запись `?имя` есть простое значение целиком
	 */
	/**
	 * Если значение открывается знаком примечания
	 *
	 * @details Знак примечания простого значения не открывает: описанием он дозволен лишь
	 *          внутри значения либо за пробельным знаком. Запись `[ a, b,#invalid ]`
	 *          принималась значением `#invalid`, а примечанием там оно тоже не является -
	 *          пробела перед ним нет
	 *
	 * @note Нашло это сличение с набором yaml-test-suite
	 */
	if(leading == '#'){
		/**
		 * Если знак примечания стоит за пробельным знаком либо с начала строки
		 *
		 * @details Описание примечание дозволяет всюду, где перед ним стоит пробельный
		 *          знак: запись `- # пусто` есть запись перечня с пустым значением и
		 *          примечанием за нею. Прежде отказ шёл на всякий знак примечания в
		 *          начале содержимого, и запись такая отвергалась вместе с `,#invalid`
		 *
		 * @note Случай W42U набора yaml-test-suite
		 */
		if((offset == 0) || spacing(line[offset - 1])){
			// Выполняем постановку события примечания
			this->remark(line, offset);
			// Выводим признак успешного разбора содержимого
			return true;
		}
		/**
		 * @warning Отказ этот недостижим: ни один из восьми зовущих не подаёт знак примечания на место,
		 *          перед которым стоит знак непробельный. Пятеро отсекают примечание своею поверкою прежде
		 *          вызова, черта начала документа требует пробельного знака за собою, а разбор записи
		 *          перечня и разбор строки заходят сюда с места, пробелами отделённого либо строку
		 *          открывающего
		 */
		// Выводим отказ недопустимого знака в этом месте текста
		return this->fail(error_t::INVALID_CHARACTER, offset);
	}
	/**
	 * Если содержимое открывается ссылкой на объявленную метку
	 */
	if(leading == '*'){
		/**
		 * Если ожидалось значение пары, объявленной прежде
		 */
		if(this->_expected)
			// Выполняем сброс признака ожидания значения пары
			this->_expected = false;
		// Смещение разбираемого знака строки
		size_t position = offset;
		/**
		 * Место начала записи ссылки в накопителе строки
		 *
		 * @note Помнится оно ради имени пары, ссылкою являющегося: открытие отображения
		 *       вставляется перед записью её
		 */
		const size_t origin = this->_staged.size();
		/**
		 * Выполняем откладывание свойств, строкою выше объявленных
		 *
		 * @details Ссылка своих свойств иметь не вправе, и свойства, в этой же строке ей
		 *          предпосланные, есть отказ. Свойства же строки прежней ссылке не
		 *          принадлежат вовсе: они дожидаются вместилища, какое строка эта
		 *          открывает - написание `top: &метка` со строкою `*ссылка : значение`
		 *          ниже метку отдаёт отображению, ссылкою открытому
		 *
		 * @note Не дождавшись вместилища своего, отложенное отказом и обернётся - концом
		 *       строки, а не здесь. Случай 26DV набора yaml-test-suite
		 */
		if(!this->_anchoredHere && this->_delayed.empty())
			// Выполняем откладывание метки узла вместилищу
			this->_delayed.swap(this->_anchor);
		/**
		 * Если метка типа объявлена была строкою выше
		 */
		if(!this->_taggedHere && this->_delayedTag.empty())
			// Выполняем откладывание метки типа вместилищу
			this->_delayedTag.swap(this->_tag);
		/**
		 * Если разобрать ссылку не удалось
		 */
		if(!this->referred(line, position))
			// Выводим признак неудачного разбора содержимого
			return false;
		/**
		 * Выполняем пропуск пробельных знаков за ссылкой
		 */
		while((position < line.size()) && spacing(line[position]))
			// Выполняем переход к следующему знаку строки
			position++;
		/**
		 * Если за ссылкой стоит примечание
		 */
		if((position < line.size()) && (line[position] == '#'))
			// Выполняем постановку события примечания
			this->remark(line, position);
		/**
		 * Если за ссылкой стоит разделитель имени пары
		 *
		 * @details Ссылка именем пары описанием дозволена правилом `ns-flow-yaml-node`:
		 *          читается она событием своим, а раскрытие её есть дело дерева, а не
		 *          потокового чтения. Прежде написание это отвергалось вовсе - раскрыть
		 *          имя чтению нечем, - но выдавать событие ссылки оно вправе и без
		 *          раскрытия: дерево ссылку разрешит само либо откажет своим отказом
		 *
		 * @note Случай E76Z набора yaml-test-suite
		 */
		else if((position < line.size()) && (line[position] == ':') &&
		        (((position + 1) >= line.size()) || spacing(line[position + 1]))){
			/**
			 * Если разобрать имя пары, ссылкою являющееся, не удалось
			 */
			if(!this->keyed(line, position, indent, origin))
				// Выводим признак неудачного разбора содержимого
				return false;
			// Выводим признак успешного разбора содержимого
			return true;
		}
		/**
		 * Если за ссылкой стоит содержимое, примечанием не являющееся
		 */
		else if(position < line.size())
			// Выводим отказ содержимого за завершённой записью
			return this->fail(error_t::TRAILING_CHARACTERS, position);
		// Выводим признак успешного разбора содержимого
		return true;
	}
	/**
	 * Если содержимое открывается свойствами узла
	 */
	if((leading == '&') || (leading == '!')){
		// Смещение разбираемого знака строки
		size_t position = offset;
		/**
		 * Если разобрать свойства узла не удалось
		 */
		if(!this->property(line, position))
			// Выводим признак неудачного разбора содержимого
			return false;
		/**
		 * Если за свойствами узла содержимое строки исчерпано
		 *
		 * @note Свойства вправе стоять и в строке, узлу своему предшествующей: узел ждёт их
		 *       строкою ниже, и накопленное дожидается его
		 */
		if(position >= line.size())
			// Выводим признак успешного разбора содержимого
			return true;
		/**
		 * Если за свойствами узла стоит одно примечание
		 */
		if(line[position] == '#'){
			// Выполняем постановку события примечания
			this->remark(line, position);
			// Выводим признак успешного разбора содержимого
			return true;
		}
		// Выполняем разбор содержимого за свойствами узла
		return this->content(line, position, indent);
	}
	/**
	 * Если содержимое открывается заголовком блочного значения
	 */
	if((leading == '|') || (leading == '>'))
		// Выполняем разбор заголовка блочного значения
		return this->opening(line, offset, this->_margin);
	/**
	 * Если содержимое открывается поточным построением
	 */
	if((leading == '[') || (leading == '{')){
		/**
		 * Если ожидалось значение пары, объявленной прежде
		 */
		if(this->_expected)
			// Выполняем сброс признака ожидания значения пары
			this->_expected = false;
		// Получаем предел глубины вложенности
		const size_t limit = ((this->_settings.maxDepth > 0) ? this->_settings.maxDepth : MAX_DEPTH);
		/**
		 * Если глубина вложенности предел превышает
		 */
		if(this->_levels.size() >= limit)
			// Выводим отказ превышения глубины вложенности
			return this->fail(error_t::DEPTH_EXCEEDED, offset);
		/**
		 * Если метка типа, построению предпосланная, виду его противна
		 */
		if(!this->matched(((leading == '[') ? nesting_t::SEQUENCE : nesting_t::MAPPING), offset))
			// Выводим признак неудачного разбора содержимого
			return false;
		/**
		 * Место начала записи построения в накопителе строки
		 *
		 * @note Помнится оно ради имени пары, самим построением являющегося: открытие
		 *       отображения вставляется перед записью его, а узнаём мы о том лишь по
		 *       двоеточию за скобкою закрывающей
		 */
		const size_t origin = this->_staged.size();
		// Выполняем постановку события открытия поточного построения
		item_t & item = this->emit(((leading == '[') ? event_t::SEQUENCE_START : event_t::MAPPING_START), offset);
		// Выполняем перенос накопленных свойств узла в собранное событие
		this->attach(item);
		// Запоминаем признак наполнения открытого документа
		this->_filled = true;
		// Выполняем открытие поточного построения
		this->_flow.emplace_back((leading == '[') ? nesting_t::SEQUENCE : nesting_t::MAPPING);
		// Запоминаем ожидание очередного значения построения
		this->_phase = flow_t::ENTRY;
		// Смещение разбираемого знака строки
		size_t position = (offset + 1);
		/**
		 * Если разобрать поточное построение не удалось
		 */
		if(!this->flowing(line, position))
			// Выводим признак неудачного разбора содержимого
			return false;
		/**
		 * Если построение скобками ещё не закрыто
		 *
		 * @note Построение продолжается следующею строкой, и остатка строки этой нет вовсе:
		 *       разбор её дошёл до конца
		 */
		if(!this->_flow.empty())
			// Выводим признак успешного разбора содержимого
			return true;
		/**
		 * Выполняем пропуск пробельных знаков за поточным построением
		 */
		while((position < line.size()) && spacing(line[position]))
			/**
			 * @warning Тело это истины не принимает: `flowing` пропускает пробельные знаки в начале всякого
			 *          оборота, и выход его с опустевшею стопою скобок стоит за этим пропуском - смещение,
			 *          им возвращённое, на пробел не указывает. То же и в `record`, где стоит такой же пропуск
			 */
			// Выполняем переход к следующему знаку строки
			position++;
		/**
		 * Если за построением стоит примечание
		 *
		 * @note Примечание опознаётся лишь за пробельным знаком: запись `]#invalid`
		 *       примечания не открывает, а является содержимым за завершённым
		 *       построением - и отвергается отказом. Нашло это сличение с набором
		 *       yaml-test-suite
		 */
		if((position < line.size()) && (line[position] == '#') &&
		   ((position == 0) || spacing(line[position - 1])))
			// Выполняем постановку события примечания
			this->remark(line, position);
		/**
		 * Если за построением стоит разделитель имени пары
		 *
		 * @details Описание берёт поточное построение годным именем пары правилом
		 *          `c-flow-json-node`: имя такое стоит одною строкой и двоеточием
		 *          отделяется от значения своего. Отображение, парою этой открываемое,
		 *          вставляется перед записью построения - узнаём мы о нём лишь тогда,
		 *          когда запись имени прочитана целиком
		 *
		 * @note Пробел за двоеточием обязателен, как и у имени простого: запись
		 *       `[a]:b` именем пары не является. Случаи LX3P и Q9WF набора
		 *       yaml-test-suite
		 */
		else if((position < line.size()) && (line[position] == ':') &&
		        (((position + 1) >= line.size()) || spacing(line[position + 1]))){
			/**
			 * Если разобрать имя пары, построением являющееся, не удалось
			 */
			if(!this->keyed(line, position, indent, origin))
				// Выводим признак неудачного разбора содержимого
				return false;
			// Выводим признак успешного разбора содержимого
			return true;
		}
		/**
		 * Если за построением стоит содержимое, примечанием не являющееся
		 */
		else if(position < line.size())
			// Выводим отказ содержимого за завершённой записью
			return this->fail(error_t::TRAILING_CHARACTERS, position);
		// Выводим признак успешного разбора содержимого
		return true;
	}
	/**
	 * Если содержимое объявляет очередное значение перечня
	 */
	if((leading == '-') && (((offset + 1) >= line.size()) || spacing(line[offset + 1]))){
		/**
		 * Если черта записи стоит на строке черты начала документа
		 *
		 * @details Блочное построение строки черты начала документа не занимает: отступ
		 *          его отсчитывался бы от черты, а не от начала строки, и написание
		 *          `--- - a` двусмысленно. Скаляр же простой да построение поточное там
		 *          дозволены - отступа они не задают
		 *
		 * @note Отвечает rapidyaml отказом разбора. Нашло это сличение с набором
		 *       yaml-test-suite
		 */
		if(this->_headed)
			// Выводим отказ недопустимого знака в этом месте текста
			return this->fail(error_t::INVALID_CHARACTER, offset);
		/**
		 * Если черте записи предпослана подача в отступе вложенного построения
		 */
		if(this->_tabbed)
			// Выводим отказ знака горизонтальной подачи в отступе
			return this->fail(error_t::TAB_IN_INDENTATION, offset);
		/**
		 * Если черте записи предпосланы свойства узла в той же строке
		 *
		 * @details Свойства блочного построения отделяются от него переводом строки:
		 *          правило `s-l+block-collection` описания ставит между ними
		 *          `s-l-comments`, а тот перевода строки требует. Написание
		 *          `&метка - запись` перевода не несёт, и метка узла своего не имеет
		 *
		 * @note Написание `&метка` строкою выше черты дозволено и правилу не противно.
		 *       Случай SY6V набора yaml-test-suite
		 */
		if(this->_propped && (!this->_anchor.empty() || !this->_tag.empty()))
			// Выводим отказ недопустимого знака в этом месте текста
			return this->fail(error_t::INVALID_CHARACTER, offset);
		/**
		 * Если черте записи предпосланы свойства узла при уже открытом перечне
		 *
		 * @details Строка перечня на отступе его обязана открываться чертою записи:
		 *          правило `l+block-sequence` описания иного там не дозволяет. Свойства,
		 *          строку эту занявшие, узлу принадлежать не могут - записи своей у них
		 *          нет, а перечень уже открыт, - и написание `- один`, `&метка`,
		 *          `- два` есть ошибка
		 *
		 * @note Случай GT5M набора yaml-test-suite
		 */
		if(!this->_levels.empty() && (this->_levels.back().indent == indent) &&
		   (this->_levels.back().kind == nesting_t::SEQUENCE) &&
		   (!this->_anchor.empty() || !this->_tag.empty()))
			// Выводим отказ недопустимого знака в этом месте текста
			return this->fail(error_t::INVALID_CHARACTER, offset);
		/**
		 * Признак того, что перечень открывается значением пары на отступе имени её
		 *
		 * @note Построение это описанием дозволено: пара `ключ:` со значениями перечня
		 *       отступа не требует вовсе. Закрытием по отступу такой уровень не снимается,
		 *       и снимает его следующая пара того же отображения
		 */
		/**
		 * @note Ожидание берётся обоими признаками: свойства, строкою между именем пары и
		 *       значением её стоящие, ожидание переносят с признака подачи на признак
		 *       ожидания, и написание `имя:` со строкою `&метка` и перечнем вровень с
		 *       именем отвергалось смешением построений. Случай SKE5 набора yaml-test-suite
		 */
		const bool implied = ((this->_expected || this->_awaited) && (indent <= this->_pending));
		/**
		 * Если ожидалось значение пары, объявленной прежде
		 */
		if(implied){
			// Выполняем сброс признака ожидания значения пары
			this->_expected = false;
			// Выполняем сброс признака подачи значения пары
			this->_awaited = false;
		}
		/**
		 * Если уровень перечня на этом отступе ещё не открыт
		 */
		if(this->_levels.empty() || (this->_levels.back().indent < indent) ||
		   (this->_levels.back().kind != nesting_t::SEQUENCE)){
			/**
			 * Если перечень стоит глубже открытого построения, значения его не будучи
			 *
			 * @details Перечень глубже открытого построения заводится лишь значением пары
			 * либо записи, объявленной прежде: написание `имя:` с перечнем строкою ниже
			 * того и требует. Черта же, стоящая глубже уже завершённой записи, значением
			 * быть некому - отступ её не отвечает ни одному из открытых уровней
			 *
			 * @note Правило это то же, каким разбирается пара глубже завершённой пары, и
			 *       расходиться им нельзя: обе стороны сличены с libyaml, отвечающей
			 *       отказом «did not find expected key». Нашёл это ворошитель правкой дерева
			 */
			if(!implied && !this->_expected && !this->_awaited && !this->_plaining &&
			   !this->_levels.empty() && (this->_levels.back().indent < indent))
				// Выводим отказ построения, стоящего глубже открытого
				return this->fail(error_t::INVALID_INDENTATION, offset);
			/**
			 * Если на этом отступе открыт уровень отображения, а перечень значением его не является
			 */
			if(!implied && !this->_levels.empty() && (this->_levels.back().indent == indent) &&
			   (this->_levels.back().kind == nesting_t::MAPPING))
				// Выводим отказ смешения перечня и отображения на одном уровне
				return this->fail(error_t::MIXED_COLLECTION, offset);
			/**
			 * Если открыть уровень перечня не удалось
			 */
			if(!this->expand(nesting_t::SEQUENCE, indent, implied, offset))
				// Выводим признак неудачного разбора содержимого
				return false;
		}
		// Получаем смещение содержимого за объявлением значения перечня
		size_t position = (offset + 1);
		/**
		 * Выполняем пропуск пробельных знаков за объявлением значения перечня
		 */
		while((position < line.size()) && spacing(line[position])){
			/**
			 * Если пробельный знак есть знак горизонтальной подачи
			 *
			 * @details Построение вложенное, чертою записи открытое, отступ свой берёт
			 *          правилом `s-indent` описания, а тот задан одними пробелами: подача
			 *          отступом не является, и написания `-<подача>-` да `-<подача>имя:`
			 *          отступа вложенному построению не дают вовсе. Скаляру же подача
			 *          дозволена - отступа он не задаёт
			 *
			 * @note Случай Y79Y набора yaml-test-suite. Rapidyaml отвергает написание
			 *       `-<пробел><подача>-`, а `-<подача>-` принимает, чем себе же и
			 *       противоречит: правило описания порядка знаков не различает
			 */
			if(line[position] == '\t')
				// Запоминаем признак подачи в отступе вложенного построения
				this->_tabbed = true;
			// Выполняем переход к следующему знаку строки
			position++;
		}
		/**
		 * Запоминаем признак ожидания значения записи перечня
		 *
		 * @details Признак ставится прежде разбора остатка строки, ровно как у имени пары:
		 *          остаток вправе не нести значения вовсе либо нести одни свойства узла, и
		 *          значение придёт лишь строкою ниже. Снимают признак этот сами разборы
		 *          значений, каждый у себя. Нашёл это ворошитель на перезаписи: без него
		 *          запись `- ` пустоты своей не выдавала вовсе, и запись перечня пропадала
		 */
		this->_expected = true;
		// Запоминаем признак принадлежности ожидаемого значения записи перечня
		this->_entered = true;
		// Запоминаем отступ, на котором ожидается значение записи перечня
		this->_pending = indent;
		// Запоминаем смещение, на котором ожидается значение записи перечня
		this->_awaiting.offset = (this->_position + position);
		// Запоминаем строку, на которой ожидается значение записи перечня
		this->_awaiting.line = this->_line;
		// Запоминаем столбец, на котором ожидается значение записи перечня
		this->_awaiting.column = static_cast <uint32_t> (position + 1);
		// Выполняем разбор содержимого за объявлением значения перечня
		return this->content(line, position, static_cast <uint32_t> (position));
	}
	// Вид записи первого прочитанного значения
	style_t style = style_t::PLAIN;
	// Длина записи первого прочитанного значения
	size_t length = 0;
	/**
	 * Если ограда первого значения не закрыта
	 *
	 * @note Многострочные значения заводятся следующим этапом работ: пока ограда обязана
	 *       закрыться в той же строке, где открылась
	 */
	if(!this->bounds(line, offset, style, length))
		// Выводим отказ незакрытой ограды скалярного значения
		return this->fail(error_t::UNTERMINATED_SCALAR, offset);
	/**
	 * Если значение огранённое склейкой строк собрано
	 *
	 * @details Продолжение огранённого значения обязано стоять глубже построения, значение
	 *          объемлющего: описание берёт его правилом `s-flow-line-prefix`, а тот отступ
	 *          построения превышать велит. Значение, содержимым документа целиком стоящее,
	 *          построений над собою не имеет, и продолжению его дозволено стоять с начала
	 *          строки
	 *
	 * @note Случаи QB6E и JKF3 набора yaml-test-suite: написание `имя: "a` со строкою `b`
	 *       на нулевом отступе принималось значением `a b`, а описание его отвергает
	 */
	if(this->_stretched && (style != style_t::PLAIN) && !this->_levels.empty() &&
	   (this->_shallow <= this->_levels.back().indent))
		// Выводим отказ отступа, ни одному из открытых уровней не отвечающего
		return this->fail(error_t::INVALID_INDENTATION, offset);
	// Получаем смещение содержимого за первым значением
	size_t position = (offset + length);
	/**
	 * Выполняем пропуск пробельных знаков за первым значением
	 */
	while((position < line.size()) && spacing(line[position]))
		// Выполняем переход к следующему знаку строки
		position++;
	/**
	 * Если за первым значением стоит разделитель имени пары
	 */
	if((position < line.size()) && (line[position] == ':') &&
	   (((position + 1) >= line.size()) || spacing(line[position + 1]))){
		/**
		 * Если имя пары собрано огранённым значением в несколько строк
		 *
		 * @details Имя пары описание берёт правилом `ns-s-implicit-yaml-key`, а тому
		 *          дозволена одна строка и только одна: имя, в несколько строк стоящее,
		 *          именем пары быть не вправе. Внутри скобок правило иное - там имя
		 *          берётся правилом `ns-flow-map-implicit-entry`, и многострочность ему
		 *          дозволена
		 *
		 * @note Случаи 7LBH и D49Q набора yaml-test-suite
		 */
		if(this->_stretched && (style != style_t::PLAIN) && this->_flow.empty())
			// Выводим отказ недопустимого знака в этом месте текста
			return this->fail(error_t::INVALID_CHARACTER, position);
		/**
		 * Если имя пары в этой строке уже объявлено
		 *
		 * @details Описание дозволяет строке блочного построения нести одно имя пары:
		 *          запись `a: b: c` двусмысленна - неведомо, пара ли это со значением
		 *          `b: c` либо отображение внутри пары, - и разбор её наугад выдал бы
		 *          дерево, исходному тексту не отвечающее. Прежде вторым двоеточием
		 *          заводилась пара внутри значения
		 *
		 * @note Написание `время: 12:30` под правило не подпадает: двоеточие там пробелом
		 *       не отделено и разделителем не является. Отвечает rapidyaml отказом «two
		 *       consecutive keys». Нашло это сличение с набором yaml-test-suite
		 */
		if(this->_valued)
			// Выводим отказ недопустимого знака в этом месте текста
			return this->fail(error_t::INVALID_CHARACTER, position);
		/**
		 * Если имя пары стоит на строке черты начала документа
		 *
		 * @details Блочное отображение строки черты начала документа не занимает: отступ
		 *          его отсчитывался бы от черты, а не от начала строки, и продолжение
		 *          написания `--- key1: value1` строкою ниже читать нечем
		 *
		 * @note Отвечает rapidyaml отказом разбора. Нашло это сличение с набором
		 *       yaml-test-suite
		 */
		if(this->_headed)
			// Выводим отказ недопустимого знака в этом месте текста
			return this->fail(error_t::INVALID_CHARACTER, position);
		/**
		 * Если имени пары предпослана подача в отступе вложенного построения
		 */
		if(this->_tabbed)
			// Выводим отказ знака горизонтальной подачи в отступе
			return this->fail(error_t::TAB_IN_INDENTATION, position);
		/**
		 * Если ожидалось значение пары, объявленной прежде
		 *
		 * @note Пара, стоящая на отступе имени прежней пары, знаменует не значение её, а
		 *       следующую пару того же отображения
		 */
		if(this->_expected && (indent <= this->_pending))
			// Выполняем сброс признака ожидания значения пары
			this->_expected = false;
		/**
		 * Если на этом отступе открыт перечень, бывший значением прежней пары
		 *
		 * @note Закрытием по отступу он не снимается - отступ у него тот же, что у имён
		 *       отображения, - и снять его обязана именно следующая пара
		 */
		while(!this->_levels.empty() && (this->_levels.back().indent == indent) &&
		      (this->_levels.back().kind == nesting_t::SEQUENCE) && this->_levels.back().implied){
			// Выполняем снятие закрываемого уровня со стопы
			this->_levels.pop_back();
			// Выполняем постановку события закрытия перечня
			this->emit(event_t::SEQUENCE_END, offset);
		}
		/**
		 * Если уровень отображения на этом отступе ещё не открыт
		 */
		if(this->_levels.empty() || (this->_levels.back().indent < indent) ||
		   (this->_levels.back().kind != nesting_t::MAPPING)){
			/**
			 * Если пара стоит глубже открытого построения, значения его не будучи
			 *
			 * @details Отображение глубже открытого построения заводится лишь значением
			 * пары, объявленной прежде: пара `имя:` со значением строкою ниже того и
			 * требует. Пара же, стоящая глубже уже завершённой пары, значением быть
			 * некому - описание такое написание запрещает, а разбор его наугад выдал бы
			 * дерево, исходному тексту не отвечающее
			 *
			 * @note Нашёл это ворошитель правкой дерева, а сличение с libyaml и libfyaml
			 *       подтвердило: обе отвечают отказом «did not find expected key», а
			 *       чтение выдумывало вложенное отображение молча
			 */
			if(!this->_expected && !this->_awaited && !this->_levels.empty() && (this->_levels.back().indent < indent))
				// Выводим отказ построения, стоящего глубже открытого
				return this->fail(error_t::INVALID_INDENTATION, offset);
			/**
			 * Если на этом отступе открыт уровень перечня
			 */
			if(!this->_levels.empty() && (this->_levels.back().indent == indent) &&
			   (this->_levels.back().kind != nesting_t::MAPPING))
				// Выводим отказ смешения перечня и отображения на одном уровне
				return this->fail(error_t::MIXED_COLLECTION, offset);
			/**
			 * Свойства узла, имени пары в той же строке предпосланные
			 *
			 * @details Свойства эти принадлежат имени пары, а не отображению, ею
			 *          открываемому: описание берёт имя правилом `ns-s-implicit-yaml-key`,
			 *          а то есть узел со своими свойствами. Отображение же берёт свойства
			 *          лишь тогда, когда они отделены от него переводом строки. Прежде
			 *          написание `&метка имя: значение` метку отдавало отображению, а
			 *          написание `!!str имя: значение` отказ получало - метка типа
			 *          сличалась с видом отображения
			 *
			 * @note Нашло это сличение с набором yaml-test-suite
			 */
			string anchor, tag;
			/**
			 * Если свойства узла разобраны в этой же строке
			 */
			if(this->_propped){
				// Выполняем изъятие метки узла у открываемого отображения
				anchor.swap(this->_anchor);
				// Выполняем изъятие метки типа у открываемого отображения
				tag.swap(this->_tag);
				/**
				 * Выполняем возврат отложенных свойств открываемому вместилищу
				 *
				 * @note Метка, строкою выше объявленная, вместилищу и предназначалась:
				 *       изъятие выше отняло у него метку имени пары, а эта - его
				 */
				if(!this->_delayed.empty())
					// Выполняем возврат отложенной метки открываемому отображению
					this->_anchor.swap(this->_delayed);
				/**
				 * Если метка типа вместилищу отложена была
				 */
				if(!this->_delayedTag.empty())
					// Выполняем возврат отложенной метки типа открываемому отображению
					this->_tag.swap(this->_delayedTag);
			}
			// Признак успешного открытия уровня отображения
			const bool opened = this->expand(nesting_t::MAPPING, indent, false, offset);
			/**
			 * Выполняем возврат изъятых свойств узла имени пары
			 */
			if(!anchor.empty())
				// Выполняем возврат метки узла имени пары
				this->_anchor.swap(anchor);
			/**
			 * Если метка типа изъята была
			 */
			if(!tag.empty())
				// Выполняем возврат метки типа имени пары
				this->_tag.swap(tag);
			/**
			 * Если открыть уровень отображения не удалось
			 */
			if(!opened)
				// Выводим признак неудачного разбора содержимого
				return false;
		}
		/**
		 * Если имя пары записано простым видом
		 *
		 * @details Простое имя ограды не имеет, и снимать с него нечего: переносится оно
		 *          в хранилище как есть. Снятие ограды у такого имени сводилось к заводу
		 *          строки и переписыванию в неё уже имеющегося
		 *
		 * @note Наружу это торчало счётом выделений: короткий запас строки у libc++
		 *       вмещает 22 октета и прятал их, у libstdc++ он 15 - и там выделение шло
		 *       на всякое имя длиннее пятнадцати. Работа делалась на ВСЕХ системах,
		 *       видна была на пяти из семи
		 */
		if(style == style_t::PLAIN){
			/**
			 * Если поставить событие имени пары не удалось
			 */
			if(!this->scalar(line.substr(offset, length), style, offset))
				// Выводим признак неудачного разбора содержимого
				return false;
		/**
		 * Если имя пары оградою окружено
		 */
		} else {
			// Собираемое содержимое имени пары
			string name;
			/**
			 * Если снять ограду с имени пары не удалось
			 */
			if(!this->unquote(line.substr(offset, length), style, offset, name))
				// Выводим признак неудачного разбора содержимого
				return false;
			/**
			 * Если поставить событие имени пары не удалось
			 */
			if(!this->scalar(name, style, offset))
				// Выводим признак неудачного разбора содержимого
				return false;
		}
		// Выполняем переход за разделитель имени пары
		position++;
		/**
		 * Выполняем пропуск пробельных знаков за разделителем имени пары
		 */
		while((position < line.size()) && spacing(line[position]))
			// Выполняем переход к следующему знаку строки
			position++;
		/**
		 * Запоминаем признак ожидания значения пары
		 *
		 * @details Признак ставится прежде разбора остатка строки, а не вместо него:
		 *          остаток вправе нести одни свойства узла - метку да метку типа, - и
		 *          значение придёт лишь строкою ниже. Снимают признак этот сами разборы
		 *          значений, каждый у себя, и остаётся он стоять ровно тогда, когда
		 *          значения в строке не оказалось. Нашёл это ворошитель: без признака
		 *          запись `имя: &метка` со значением ниже читалась смешением построений
		 */
		this->_expected = true;
		/**
		 * Выполняем сброс признака имени, вопросом объявленного
		 *
		 * @details Пара обычная, вопросом не объявленная, пару вопроса и заканчивает: имя
		 *          его пустоту своего значения уже получило, и держать признак дальше
		 *          значило бы выдать ему пустоту вторично - концом текста
		 *
		 * @note Сличается отступ: пара, глубже вопроса стоящая, есть часть имени его, а
		 *       не соседка ему - написание `? имя: значение` кладёт отображение именем
		 *       пары. Прежде написание `? имя` со строкою `пара: значение` ниже давало
		 *       пустоту лишнюю в самом конце, а сброс без сличения отступа терял имя
		 *       составное. Случаи ZWK4 и V9D5 набора yaml-test-suite
		 */
		if(indent <= this->_questioned)
			// Выполняем сброс признака имени, вопросом объявленного
			this->_asked = false;
		// Выполняем сброс признака принадлежности ожидаемого значения записи перечня
		this->_entered = false;
		// Запоминаем отступ, на котором ожидается значение пары
		this->_pending = indent;
		// Запоминаем смещение, на котором ожидается значение пары
		this->_awaiting.offset = (this->_position + position);
		// Запоминаем строку, на которой ожидается значение пары
		this->_awaiting.line = this->_line;
		// Запоминаем столбец, на котором ожидается значение пары
		this->_awaiting.column = static_cast <uint32_t> (position + 1);
		/**
		 * Если содержимое строки исчерпано либо за ним стоит одно примечание
		 */
		if((position >= line.size()) || (line[position] == '#')){
			/**
			 * Если за разделителем имени пары стоит примечание
			 */
			if(position < line.size())
				// Выполняем постановку события примечания
				this->remark(line, position);
			// Выводим признак успешного разбора содержимого
			return true;
		}
		/**
		 * Если значение пары открывается чертою записи перечня
		 *
		 * @details Перечень блочного построения строки имени своей пары не занимает:
		 * записи его отделяются переводом строки и стоят отступом своим. Написание
		 * `имя: -` разбирать нечем - записи перечня тут не место, - и разбор его наугад
		 * выдал бы перечень, отступ какого исходному тексту не отвечает
		 *
		 * @note Нашёл это ворошитель правкой дерева, а сличение подтвердило: libyaml
		 *       отвечает отказом «block sequence entries are not allowed in this context».
		 *       Поточное построение под правило не подпадает: `имя: [1]` строку имени
		 *       занимать вправе, и скобки от черты отличны
		 */
		if((line[position] == '-') && (((position + 1) >= line.size()) || spacing(line[position + 1])))
			// Выводим отказ записи перечня в строке имени пары
			return this->fail(error_t::MIXED_COLLECTION, position);
		// Запоминаем признак разбора значения пары, в строке имени её стоящего
		this->_valued = true;
		// Выполняем разбор значения пары, стоящего в той же строке
		const bool result = this->content(line, position, static_cast <uint32_t> (position));
		// Выполняем сброс признака разбора значения пары в строке имени её
		this->_valued = false;
		// Выводим признак разбора значения пары
		return result;
	}
	/**
	 * Если значение стоит на отступе, значения пары не ожидающем
	 *
	 * @note Скалярное значение вне пары и вне перечня есть содержимое документа целиком,
	 *       и второго такого в одном документе быть не может
	 */
	/**
	 * Если скалярное значение стоит на отступе открытого перечня
	 *
	 * @details Перечень несёт одни записи свои, чертою объявленные: значение, на отступе
	 * его стоящее и чертою не объявленное, ни записью перечня не является, ни объемлющему
	 * построению не принадлежит - отступ у него не тот. Разобрать его нечем, и разбор
	 * наугад выдал бы запись перечня, какой в тексте нет
	 *
	 * @note Сличение это идёт и отступу глубже: значение, глубже отступа перечня стоящее,
	 *       есть либо значение записи его, либо продолжение простого значения, а оба
	 *       случая опознаются признаками своими. Всё прочее libyaml отвергает отказом
	 *       «did not find expected '-' indicator». Нашёл это ворошитель правкой дерева
	 */
	if(!this->_expected && !this->_awaited && !this->_plaining && !this->_levels.empty() &&
	   (this->_levels.back().kind == nesting_t::SEQUENCE) && (indent >= this->_levels.back().indent))
		// Выводим отказ значения, записью перечня не объявленного
		return this->fail(error_t::INVALID_INDENTATION, offset);
	/**
	 * Если скалярное значение стоит на отступе открытого отображения
	 *
	 * @details Отображение несёт одни пары свои, двоеточием объявленные: значение, на
	 *          отступе его стоящее и двоеточия за собою не имеющее, ни именем пары не
	 *          является, ни значением её - имени, какому оно принадлежало бы, нет вовсе.
	 *          Разобрать его нечем, и разбор молча ронял его: текст `a: 1` со строкою
	 *          `b` под ним давал дерево об одной паре, а вторая строка пропадала бесследно
	 *
	 * @note Отказ этот отвечает rapidyaml с libyaml: обе отвергают такое написание
	 *       отказом «could not find ':' colon after key». Пропажа же вскрылась правкой
	 *       дерева: строка, дереву неведомая, уходила дословным переносом вместе с
	 *       соседом, а правка ставила рядом с нею новую пару - и перезапись читаться
	 *       обратно переставала. Нашёл это ворошитель правкой дерева
	 */
	if(!this->_expected && !this->_awaited && !this->_plaining && !this->_levels.empty() &&
	   (this->_levels.back().kind == nesting_t::MAPPING) && (indent >= this->_levels.back().indent))
		// Выводим отказ значения, парою отображения не объявленного
		return this->fail(error_t::INVALID_INDENTATION, offset);
	/**
	 * Если ожидалось значение пары, объявленной прежде
	 */
	if(this->_expected)
		// Выполняем сброс признака ожидания значения пары
		this->_expected = false;
	/**
	 * Если значение пусто
	 *
	 * @warning Ветвь эта истины не принимает: нулевую длину `bounds` выдаёт лишь двум написаниям -
	 *          содержимому, за концом строки начатому, и двоеточию с пробельным знаком либо концом
	 *          записи за ним. Первое отсекает поверка в начале приёма, второе разбирается ветвью пары
	 *          с пустым именем, выше стоящей. Замерено девятью написаниями: `- : 1`, `? : 1`, `--- : 1`,
	 *          `a: : 1`, `- :`, `a:` с двоеточием на строке ниже и подобными им
	 */
	if(length == 0){
		/**
		 * Если за значением стоит примечание
		 */
		if((position < line.size()) && (line[position] == '#')){
			// Выполняем постановку события примечания
			this->remark(line, position);
			// Выводим признак успешного разбора содержимого
			return true;
		}
		// Выводим признак успешного разбора содержимого
		return true;
	}
	/**
	 * Собираемое содержимое значения
	 *
	 * @note Простое значение ограды не имеет, и снимать с него нечего: строка заводится
	 *       лишь ради откладывания выдачи, а при выдаче немедленной обходится и без неё
	 */
	string value;
	/**
	 * Если значение оградою окружено
	 */
	if(style != style_t::PLAIN){
		/**
		 * Если снять ограду со значения не удалось
		 */
		if(!this->unquote(line.substr(offset, length), style, offset, value))
			// Выводим признак неудачного разбора содержимого
			return false;
	}
	/**
	 * Если значение записано без ограды и добежало до конца строки
	 *
	 * @details Простое значение вправе продолжиться строкою ниже, и знать о том сейчас
	 *          нечем: узнаётся это лишь отступом строки следующей. Выдача оттого
	 *          откладывается до неё. Значение с оградою продолжения не имеет - ограда
	 *          закрылась, - а значение с примечанием за ним завершено примечанием
	 */
	if((style == style_t::PLAIN) && (position >= line.size()))
		// Выполняем откладывание выдачи простого значения
		return this->deferred(line.substr(offset, length), offset);
	/**
	 * Если поставить событие значения не удалось
	 *
	 * @note Простое значение уходит в хранилище своим срезом исходной строки, без
	 *       промежутка: заводить под него строку незачем
	 */
	if(!this->scalar(((style == style_t::PLAIN) ? line.substr(offset, length) : string_view(value)), style, offset))
		// Выводим признак неудачного разбора содержимого
		return false;
	/**
	 * Если за значением стоит примечание, а выдача примечаний затребована
	 *
	 * @note Примечание опознаётся лишь за пробельным знаком: запись `key: "value"# нет`
	 *       примечания не открывает, а является содержимым за завершённой записью.
	 *       Отвечает rapidyaml отказом «comment must be preceded by whitespace». Нашло
	 *       это сличение с набором yaml-test-suite
	 */
	if((position < line.size()) && (line[position] == '#') &&
	   ((position == 0) || spacing(line[position - 1]))){
		// Выполняем постановку события примечания
		this->remark(line, position);
	/**
	 * Если за значением стоит содержимое, значением не являющееся
	 *
	 * @note Сличение со знаком примечания здесь снято: знак этот, пробелом не
	 *       предварённый, примечания не открывает, а прежнее условие пропускало его
	 *       мимо обеих ветвей - и запись `key: "value"# нет` принималась молча
	 */
	} else if(position < line.size())
		// Выводим отказ содержимого за завершённой записью
		return this->fail(error_t::TRAILING_CHARACTERS, position);
	// Выводим признак успешного разбора содержимого
	return true;
}
/**
 * @brief Метод разбора имени пары, записью составною являющегося
 *
 * @details Именем пары описание дозволяет быть и построению поточному, и ссылке на
 * метку: правило `ns-s-implicit-yaml-key` требует от такого имени лишь одной строки.
 * Отображение, парою этой открываемое, вставляется перед записью имени - узнаём мы о
 * нём лишь тогда, когда запись прочитана целиком, а стоять оно обязано прежде неё
 *
 * @note Разбор ведётся здесь общим для обоих видов записи: разнятся они лишь тем, чем
 *       имя собрано, а обхождение с двоеточием и с открытием отображения у них одно
 *
 * @param line   разбираемая строка
 * @param offset смещение разделителя имени пары в строке
 * @param indent отступ разбираемой строки
 * @param origin место начала записи имени в накопителе строки
 * @return       признак успешного разбора имени пары
 *
 */
bool awh::codec::yaml::Reader::keyed(const string_view line, size_t offset, const uint32_t indent, const size_t origin) noexcept {
	/**
	 * Если уровня отображения на этом отступе ещё нет
	 */
	if(this->_levels.empty() || (this->_levels.back().kind != nesting_t::MAPPING) ||
	   (this->_levels.back().indent != indent)){
		/**
		 * Если место начала записи имени за накопителем строки вышло
		 */
		if(origin > this->_staged.size())
			/**
			 * @warning Отказ этот недостижим: накопитель событий внутри разбора одной строки не убывает
			 *          ниже места, зовущим запомненного. Оба зовущих запоминают место прежде выдачи события -
			 *          ссылки либо открытия построения, - а снятие с конца накопителя в разборе построения
			 *          тут же возвращает снятое вставкою. Опустошают накопитель лишь `clear`, `fail` и `commit`,
			 *          и ни один из них внутри разбора содержимого строки не зовётся
			 */
			// Выводим отказ недопустимого знака в этом месте текста
			return this->fail(error_t::INVALID_CHARACTER, offset);
		/**
		 * Выполняем возврат отложенных свойств открываемому вместилищу
		 *
		 * @details Метка, строкою выше объявленная, принадлежит вместилищу, какое строка
		 *          эта открывает, а не имени пары её: свойства самого имени разобраны уже
		 *          и узлу его отданы, а отложенное дожидается здесь своего отображения
		 *
		 * @note Прежде возврата этого не было, и написание `&метка` со строкою
		 *       `&имя [a]: значение` ниже отказ получало: отложенное вместилища своего не
		 *       дожидалось. Случаи 6BFJ и 26DV набора yaml-test-suite
		 */
		if(!this->_delayed.empty())
			// Выполняем возврат отложенной метки открываемому отображению
			this->_anchor.swap(this->_delayed);
		/**
		 * Если метка типа вместилищу отложена была
		 */
		if(!this->_delayedTag.empty())
			// Выполняем возврат отложенной метки типа открываемому отображению
			this->_tag.swap(this->_delayedTag);
		/**
		 * Если открыть уровень отображения не удалось
		 */
		if(!this->expand(nesting_t::MAPPING, indent, false, offset))
			// Выводим признак неудачного разбора имени пары
			return false;
		/**
		 * Если событие открытия отображения в накопителе стоит
		 *
		 * @note Место события открытия берётся у записи имени: отображение стоит там же,
		 *       где стоит имя его, а не там, где стоит двоеточие
		 */
		if(!this->_staged.empty() && (origin < (this->_staged.size() - 1))){
			// Переносим место события открытия отображения на запись имени
			this->_staged.back().location = this->_staged.at(origin).location;
			// Получаем поставленное событие открытия отображения
			const item_t opening = this->_staged.back();
			// Выполняем снятие события открытия с конца накопителя
			this->_staged.pop_back();
			// Выполняем вставку события открытия отображения перед записью имени
			this->_staged.insert((this->_staged.begin() + static_cast <ptrdiff_t> (origin)), opening);
		}
	}
	// Выполняем переход за разделитель имени пары
	offset++;
	/**
	 * Выполняем пропуск пробельных знаков за разделителем имени пары
	 */
	while((offset < line.size()) && spacing(line[offset]))
		// Выполняем переход к следующему знаку строки
		offset++;
	// Запоминаем признак ожидания значения пары
	this->_expected = true;
	// Выполняем сброс признака принадлежности ожидаемого значения записи перечня
	this->_entered = false;
	// Запоминаем отступ, на котором ожидается значение пары
	this->_pending = indent;
	// Запоминаем смещение, на котором ожидается значение пары
	this->_awaiting.offset = (this->_position + offset);
	// Запоминаем строку, на которой ожидается значение пары
	this->_awaiting.line = this->_line;
	// Запоминаем столбец, на котором ожидается значение пары
	this->_awaiting.column = static_cast <uint32_t> (offset + 1);
	/**
	 * Если содержимое строки исчерпано либо за ним стоит одно примечание
	 */
	if((offset >= line.size()) || (line[offset] == '#')){
		/**
		 * Если за разделителем имени пары стоит примечание
		 */
		if(offset < line.size())
			// Выполняем постановку события примечания
			this->remark(line, offset);
		// Выводим признак успешного разбора имени пары
		return true;
	}
	// Выполняем разбор значения пары
	return this->content(line, offset, indent);
}
/**
 * @brief Метод разбора заголовка блочного значения
 *
 * @param line   разбираемая строка
 * @param offset смещение заголовка блочного значения в строке
 * @param indent отступ строки, заголовок несущей
 * @return       признак успешного разбора заголовка
 *
 */
bool awh::codec::yaml::Reader::opening(const string_view line, const size_t offset, const uint32_t indent) noexcept {
	/**
	 * Если ожидалось значение пары, объявленной прежде
	 *
	 * @note Блочное значение и есть то значение, какого пара ожидала: признак ожидания
	 *       снимается здесь, у себя, тем же порядком, каким снимают его прочие разборы
	 */
	if(this->_expected)
		// Выполняем сброс признака ожидания значения пары
		this->_expected = false;
	// Запоминаем вид собираемого блочного значения
	this->_block = ((line[offset] == '|') ? style_t::LITERAL : style_t::FOLDED);
	// Выполняем сброс правила усечения переводов строк
	this->_chomp = chomp_t::CLIP;
	// Выполняем сброс отступа, заголовком заданного
	this->_marked = NO_INDENT;
	// Смещение разбираемого знака заголовка
	size_t position = (offset + 1);
	// Признак того, что правило усечения уже задано
	bool chomped = false;
	/**
	 * Выполняем перебор всех знаков заголовка блочного значения
	 */
	while((position < line.size()) && !spacing(line[position])){
		// Получаем очередной знак заголовка блочного значения
		const char letter = line[position];
		/**
		 * Если знак задаёт правило усечения переводов строк
		 */
		if((letter == '-') || (letter == '+')){
			/**
			 * Если правило усечения уже задано
			 */
			if(chomped)
				// Выводим отказ ошибочного построения заголовка
				return this->fail(error_t::INVALID_BLOCK_HEADER, position);
			// Запоминаем правило усечения переводов строк
			this->_chomp = ((letter == '-') ? chomp_t::STRIP : chomp_t::KEEP);
			// Запоминаем признак того, что правило усечения задано
			chomped = true;
		/**
		 * Если знак задаёт отступ содержимого блочного значения
		 *
		 * @note Указатель отступа - цифра от единицы до девяти, и отсчитывается он от
		 *       отступа строки, заголовок несущей. Нуль указателем не является: отступа
		 *       нулевой ширины у содержимого быть не может
		 */
		} else if((letter >= '1') && (letter <= '9')){
			/**
			 * Если отступ уже задан
			 */
			if(this->_marked != NO_INDENT)
				// Выводим отказ ошибочного построения заголовка
				return this->fail(error_t::INVALID_BLOCK_HEADER, position);
			// Запоминаем отступ, заголовком заданный
			this->_marked = static_cast <uint8_t> (letter - '0');
		/**
		 * Если знак заголовку не принадлежит вовсе
		 */
		} else return this->fail(error_t::INVALID_BLOCK_HEADER, position);
		// Выполняем переход к следующему знаку заголовка
		position++;
	}
	/**
	 * Выполняем пропуск пробельных знаков за заголовком
	 */
	while((position < line.size()) && spacing(line[position]))
		// Выполняем переход к следующему знаку строки
		position++;
	/**
	 * Если за заголовком стоит примечание
	 */
	if((position < line.size()) && (line[position] == '#'))
		// Выполняем постановку события примечания
		this->remark(line, position);
	/**
	 * Если за заголовком стоит содержимое, примечанием не являющееся
	 */
	else if(position < line.size())
		// Выводим отказ содержимого за завершённой записью
		return this->fail(error_t::TRAILING_CHARACTERS, position);
	// Запоминаем признак сборки блочного значения
	this->_blocking = true;
	/**
	 * Запоминаем отступ, глубже которого обязано стоять содержимое блочного значения
	 *
	 * @details Отсчёт ведётся не от начала строки, а от отступа объемлющего построения:
	 *          написание `- имя: |` кладёт отображение на отступ два, строку же открывает
	 *          черта на отступе ноль. Отсчёт от строки брал бы содержимым и следующую пару
	 *          того же отображения. Нашёл это ворошитель сличением перезаписи
	 *
	 * @note Отступ строки берётся лишь тогда, когда построений над значением нет вовсе.
	 *       Прежде он брался и там, где строка стояла глубже объемлющего построения, -
	 *       а заголовок, строкою ниже пары своей стоящий, тем самым отсчитывался от
	 *       себя же: написание `a:` со строкою `  >1` ниже клало содержимое на отступ
	 *       три вместо одного. Указатель отступа описанием отсчитывается от узла
	 *       объемлющего, и строка, заголовок несущая, узлом тем не является
	 *       (случай M5C3 набора yaml-test-suite)
	 */
	this->_outer = (this->_levels.empty() ? indent : this->_levels.back().indent);
	// Запоминаем положение заголовка блочного значения в строке
	this->_opening = offset;
	/**
	 * Запоминаем положение заголовка блочного значения в исходном тексте
	 *
	 * @details Событие значения ставится там, где содержимое его окончилось, а стоит оно
	 *          там, где заголовок его начался: потребителю указывать надлежит на начало
	 *          записи. Поле это делится с откладыванием простого значения - собираться
	 *          вместе они не могут, ибо оба суть записи значения
	 */
	this->_origin.offset = (this->_position + offset);
	// Запоминаем номер строки, где заголовок стоит
	this->_origin.line = this->_line;
	// Запоминаем положение заголовка в строке
	this->_origin.column = static_cast <uint32_t> (offset + 1);
	// Запоминаем глубину вложенности, где заголовок стоит
	this->_origin.depth = static_cast <uint32_t> (this->_levels.size());
	/**
	 * Запоминаем отступ содержимого блочного значения
	 *
	 * @note Отступ, заголовком заданный, отсчитывается от отступа объемлющего построения -
	 *       того же самого, глубже которого содержимое обязано стоять, - а не от начала
	 *       строки; отступ же, заголовком не заданный, берётся по первой непустой строке
	 *       содержимого и здесь ещё неизвестен
	 */
	this->_inner = ((this->_marked != NO_INDENT) ? (this->_outer + this->_marked) : 0);
	/**
	 * Запоминаем признак того, что блочное значение стоит содержимым документа целиком
	 *
	 * @note Построений над ним нет вовсе, и описание берёт правилом `s-l+block-node`
	 *       отступ мельче нулевого: содержимое такого значения вправе стоять с начала
	 *       строки. Прежде написание `--- >` со строками с начала строки отказ получало
	 */
	this->_rooted = this->_levels.empty();
	// Запоминаем признак того, что отступ содержимого заголовком задан
	this->_detected = (this->_marked != NO_INDENT);
	// Выполняем сброс собираемого содержимого блочного значения
	this->_block_text.clear();
	// Выполняем сброс количества пустых строк, содержимого не дождавшихся
	this->_breaks = 0;
	// Выполняем сброс наибольшего отступа пустых строк, содержимому предпосланных
	this->_padding = 0;
	// Выполняем сброс признака строки, глубже отступа содержимого стоявшей
	this->_deepened = false;
	// Выполняем сброс признака ожидания значения пары
	this->_expected = false;
	// Выводим признак успешного разбора заголовка
	return true;
}
/**
 * @brief Метод присоединения очередной строки к блочному значению
 *
 * @param line     присоединяемая строка
 * @param attached признак присоединения строки к блочному значению
 * @return         признак успешного присоединения строки
 *
 */
bool awh::codec::yaml::Reader::blocking(const string_view line, bool & attached) noexcept {
	// Выполняем сброс признака присоединения строки
	attached = false;
	// Смещение начала содержимого строки за отступом
	size_t offset = 0;
	/**
	 * Выполняем пропуск отступа присоединяемой строки
	 */
	while((offset < line.size()) && (line[offset] == ' '))
		// Выполняем переход к следующему знаку строки
		offset++;
	/**
	 * Если строка пуста
	 *
	 * @note Пустая строка блочного значения не завершает: она вправе стоять и внутри
	 *       содержимого, и перед строкой, отступом его задающей. Учитывается она счётом
	 *       и дописывается лишь тогда, когда содержимое продолжилось
	 *
	 * @note Строка, одними пробелами набранная, пуста лишь до отступа содержимого:
	 *       пробелы за ним суть содержимое её, а не отступ. Описание берёт правилом
	 *       `l-nb-literal-text` отступ ровно заданной ширины, а всё за ним - знаками
	 *       содержимого, пробел то будет либо иной знак. Прежде такая строка выдавалась
	 *       пустою, и пробелы её пропадали. Случаи DWX9, T26H, 6FWR, H2RW и L24T набора
	 *       yaml-test-suite
	 */
	if((offset >= line.size()) && (!this->_detected || (offset <= this->_inner))){
		/**
		 * Если отступ содержимого ещё не определён
		 *
		 * @note Отступ пустых строк, содержимому предпосланных, запоминается наибольшим:
		 *       сличить его с отступом содержимого возможно лишь тогда, когда содержимое
		 *       первою непустою строкой своей этот отступ и задаст
		 */
		if(!this->_detected && (offset > this->_padding))
			// Запоминаем наибольший отступ пустых строк, содержимому предпосланных
			this->_padding = static_cast <uint32_t> (offset);
		// Выполняем учёт пустой строки блочного значения
		this->_breaks++;
		// Запоминаем признак присоединения строки
		attached = true;
		// Выводим признак успешного присоединения строки
		return true;
	}
	// Получаем отступ присоединяемой строки
	const uint32_t indent = static_cast <uint32_t> (offset);
	/**
	 * Если отступ строки блочного значения не глубже отступа заголовка
	 *
	 * @note Строка эта содержимому не принадлежит, и блочное значение ею завершается
	 */
	/**
	 * Если значение стоит содержимым документа целиком, а строка чертою открывается
	 *
	 * @details Содержимое такого значения вправе стоять с начала строки, и завершить его
	 *          отступом нечем: завершают его лишь черты начала да конца документа.
	 *          Описание запрещает их внутри содержимого правилом `c-forbidden` прямо
	 */
	if(this->_rooted && (indent == 0) && ((line.compare(0, 3, "---") == 0) || (line.compare(0, 3, "...") == 0)) &&
	   ((line.size() == 3) || spacing(line[3])))
		// Выводим признак успешного присоединения строки
		return true;
	if((indent <= this->_outer) && !this->_rooted){
		/**
		 * Если строка знаком горизонтальной подачи открывается, содержимого же ещё не было
		 *
		 * @details Пустая строка, содержимому предпосланная, отступом своим стоит мельче
		 *          содержимого, а отступ описанием задан одними пробелами: знак подачи
		 *          отступом не является и пустою строку эту не делает. Содержимым же ей
		 *          быть некем - стоит она не глубже заголовка. Написание `foo: |` с одною
		 *          подачей строкою ниже принималось со значением пустым, подачу теряя
		 *
		 * @note Строка та же за содержимым собранным дозволена: блочное значение ею
		 *       завершается, и она есть строка обыкновенная. Случай Y79Y набора
		 *       yaml-test-suite, сверено с rapidyaml
		 */
		if((line[offset] == '\t') && (this->_inner == 0) && this->_block_text.empty())
			// Выводим отказ знака горизонтальной подачи в отступе
			return this->fail(error_t::TAB_IN_INDENTATION, offset);
		// Выводим признак успешного присоединения строки
		return true;
	}
	/**
	 * Если отступ содержимого ещё не определён
	 */
	if(!this->_detected){
		/**
		 * Если пустая строка, содержимому предпосланная, стоит глубже первой непустой строки
		 *
		 * @note Отступ содержимого задаётся первою непустою строкой, и строка пустая,
		 *       её глубже стоящая, оказалась бы содержимым с отступом, ни заголовком
		 *       не заданным, ни строкою этой не подтверждённым: стандарт такое запрещает
		 */
		if(this->_padding > indent)
			return this->fail(error_t::INVALID_INDENTATION, offset);
		// Запоминаем отступ содержимого по первой непустой строке его
		this->_inner = indent;
		// Запоминаем признак того, что отступ содержимого определён
		this->_detected = true;
	}
	/**
	 * Если отступ строки мельче отступа содержимого
	 *
	 * @note Строка мельче отступом содержимому не принадлежит, а стоя глубже отступа
	 *       заголовка, она не принадлежит и объемлющему построению: разобрать её нечем
	 */
	if(indent < this->_inner){
		/**
		 * Если строка одним примечанием и составлена
		 *
		 * @details Отступ примечания описанием не связан ничем: примечание содержимым не
		 *          является и уровня собою не задаёт. Строка такая блочное значение
		 *          закрывает и разбирается затем обычным порядком, а прежде отвергалась
		 *          отказом - она стояла глубже заголовка и мельче содержимого разом
		 *
		 * @note Нашло это сличение с набором yaml-test-suite: случаи DWX9 и T26H
		 */
		if(line[offset] == '#')
			// Выводим признак успешного разбора без присоединения строки
			return true;
		return this->fail(error_t::INVALID_INDENTATION, offset);
	}
	/**
	 * Признак того, что присоединяемая строка стоит глубже отступа содержимого
	 *
	 * @details Глубже стоит и строка, содержимое какой открывается пробельным знаком:
	 *          описание берёт правилом `s-nb-folded-text` строку, знаком непробельным
	 *          начинающуюся, а всё прочее - строкою `l-nb-spaced-text`, свёртке не
	 *          подлежащей. Подача же в счёт отступа не идёт вовсе, и строка `  \tbar`
	 *          при отступе содержимого в два пробела стоит на нём ровно - глубже её
	 *          делает подача, а не отступ
	 *
	 * @note Прежде сличался один отступ, и строка такая свёртывалась с соседями своими,
	 *       теряя переводы вокруг себя. Случаи MJS9 и R4YG набора yaml-test-suite
	 */
	const bool deepened = ((indent > this->_inner) ||
	 ((static_cast <size_t> (this->_inner) < line.size()) && spacing(line[this->_inner])));
	/**
	 * Если содержимое блочного значения уже собрано хотя бы одной строкой
	 */
	if(!this->_block_text.empty()){
		/**
		 * Количество переводов строк, разделяющих присоединяемую строку с прежней
		 *
		 * @note Пустых строк накоплено на один перевод меньше: перевод, самою прежнею
		 *       строкой завершаемый, счётом пустых строк не учитывается
		 */
		const size_t breaks = (this->_breaks + 1);
		/**
		 * Если свёртка строк применению не подлежит
		 *
		 * @details Свёртка складывает строки пробелом, а пустых строк даёт на один
		 * перевод меньше. Применяется она лишь тогда, когда обе строки, переводом
		 * разделяемые, стоят ровно на отступе содержимого: строка, стоящая глубже,
		 * свёртке не подлежит ни собою, ни соседкой своей, и переводы вокруг неё
		 * сохраняются все до единого
		 *
		 * @note Правило это взято стандартом, а не догадкой: оно сличено с выдачею
		 *       эталонных реализаций libyaml и libfyaml на шести случаях свёртки, и
		 *       расхождение с ними было изъяном разбора, а не разностью прочтения
		 */
		if((this->_block == style_t::LITERAL) || this->_deepened || deepened){
			/**
			 * Выполняем запись всех переводов строк, строки разделяющих
			 */
			for(size_t i = 0; i < breaks; i++)
				// Выполняем запись перевода строки в содержимое блочного значения
				this->_block_text.push_back('\n');
		/**
		 * Если переводов строк накоплено более одного
		 */
		} else if(breaks > 1) {
			/**
			 * Выполняем запись переводов строк, свёрткою уменьшенных на один
			 */
			for(size_t i = 1; i < breaks; i++)
				// Выполняем запись перевода строки в содержимое блочного значения
				this->_block_text.push_back('\n');
		// Выполняем запись пробела свёртки в содержимое блочного значения
		} else this->_block_text.push_back(' ');
	/**
	 * Если содержимое ещё не собрано, а пустые строки уже накоплены
	 *
	 * @note Пустые строки, содержимому предпосланные, свёртке не подлежат ни при
	 *       каком виде блочного значения: складывать их пробелом не с чем, и они
	 *       сохраняются переводами как есть
	 */
	} else {
		/**
		 * Выполняем запись всех пустых строк, содержимого дождавшихся
		 */
		for(size_t i = 0; i < this->_breaks; i++)
			// Выполняем запись перевода строки в содержимое блочного значения
			this->_block_text.push_back('\n');
	}
	// Выполняем сброс количества пустых строк
	this->_breaks = 0;
	// Запоминаем признак того, что присоединяемая строка стоит глубже отступа содержимого
	this->_deepened = deepened;
	// Выполняем запись содержимого строки без отступа блочного значения
	this->_block_text.append(line.substr(this->_inner));
	// Запоминаем признак присоединения строки
	attached = true;
	// Выводим признак успешного присоединения строки
	return true;
}
/**
 * @brief Метод завершения собираемого блочного значения
 *
 * @param column положение завершения в разбираемой строке
 * @return       признак успешного завершения блочного значения
 *
 */
bool awh::codec::yaml::Reader::closing(const size_t column) noexcept {
	/**
	 * Если блочное значение не собирается вовсе
	 */
	if(!this->_blocking)
		// Выводим признак успешного завершения блочного значения
		return true;
	// Выполняем сброс признака сборки блочного значения
	this->_blocking = false;
	// Собираемое содержимое блочного значения
	string result(this->_block_text);
	/**
	 * Определяем правило усечения переводов строк
	 */
	switch(static_cast <uint8_t> (this->_chomp)){
		/**
		 * Если переводы строк снимаются все
		 */
		case static_cast <uint8_t> (chomp_t::STRIP): break;
		/**
		 * Если оставляется один перевод строки
		 */
		case static_cast <uint8_t> (chomp_t::CLIP): {
			/**
			 * Если содержимое блочного значения не пусто
			 */
			if(!result.empty())
				// Выполняем запись одного перевода строки
				result.push_back('\n');
		} break;
		/**
		 * Если переводы строк сохраняются все
		 */
		case static_cast <uint8_t> (chomp_t::KEEP): {
			/**
			 * Если содержимое блочного значения не пусто
			 */
			if(!result.empty())
				// Выполняем запись перевода строки, содержимое завершающего
				result.push_back('\n');
			/**
			 * Выполняем запись всех пустых строк, содержимого не дождавшихся
			 */
			for(size_t i = 0; i < this->_breaks; i++)
				// Выполняем запись перевода строки
				result.push_back('\n');
		} break;
	}
	// Выполняем сброс количества пустых строк
	this->_breaks = 0;
	// Выполняем сброс собираемого содержимого блочного значения
	this->_block_text.clear();
	/**
	 * Если поставить событие блочного значения не удалось
	 */
	if(!this->scalar(result, this->_block, this->_opening))
		// Выводим признак неудачного завершения блочного значения
		return false;
	// Устанавливаем вид строкового значения последнему событию
	this->_staged.back().type = type_t::STRING;
	// Устанавливаем положение заголовка значения поставленному событию
	this->_staged.back().location = this->_origin;
	// Не даём указателю на положение завершения пропасть без дела
	(void) column;
	// Выводим признак успешного завершения блочного значения
	return true;
}
/**
 * @brief Метод разбора значения внутри поточного построения
 *
 * @param line   разбираемая строка
 * @param offset смещение начала значения в строке, по выходе - смещение за ним
 * @return       признак успешного разбора значения
 *
 */
bool awh::codec::yaml::Reader::flowed(const string_view line, size_t & offset) noexcept {
	// Получаем первый знак записи значения
	const char leading = line[offset];
	/**
	 * Если значение открывается свойствами узла
	 *
	 * @warning Ветвь эта затенена зовущим и управления не получает никогда: перебор
	 *          знаков поточного построения разбирает свойства узла сам, знаком тем же
	 *          и до вызова разбора значения, а разобрав - переходит к знаку следующему.
	 *          Войти сюда со знаком `&` либо `!` неоткуда. Замер это и показал: сам
	 *          условный переход исполняется, тело его - ни разу, и то при всём корпусе
	 *          yaml-test-suite и двадцати тысячах текстов ворошителя
	 *
	 * @note Ветвь оставлена заставою последнего рубежа: разбор свойств здесь верен, и
	 *       зовущий, что перехвата того делать не станет, получит разбор правильный.
	 *       Проверкою она не держится - написать проверку на недостижимое нельзя
	 */
	if((leading == '&') || (leading == '!')){
		/**
		 * Если разобрать свойства узла не удалось
		 */
		if(!this->property(line, offset))
			// Выводим признак неудачного разбора значения
			return false;
		/**
		 * Если за свойствами узла содержимое строки исчерпано
		 *
		 * @note Свойства вправе стоять и в строке, узлу своему предшествующей: узел ждёт их
		 *       строкою ниже, и накопленное дожидается его
		 */
		if(offset >= line.size())
			// Выводим признак успешного разбора значения
			return true;
		// Выполняем разбор содержимого за свойствами узла
		return this->flowed(line, offset);
	}
	/**
	 * Если значение является ссылкой на объявленную метку
	 */
	if(leading == '*')
		// Выполняем разбор ссылки на объявленную метку
		return this->referred(line, offset);
	/**
	 * Если значение открывается вопросом составного имени
	 *
	 * @details Составные имена заводятся вместе с держащим документ целиком: имя, само
	 *          построением являющееся, нуждается в дереве, а потоковому чтению деть его
	 *          некуда
	 *
	 * @note Вопрос имя объявляет лишь тогда, когда за ним стоит пробельный знак либо
	 *       конец записи: запись `{ ?foo: bar }` несёт простое значение `?foo` целиком -
	 *       правило `ns-plain-first` вопрос простому значению дозволяет, коль скоро за
	 *       ним стоит знак непробельный. Случай 652Z набора yaml-test-suite
	 */
	if((leading == '?') && (((offset + 1) >= line.size()) || spacing(line[offset + 1])))
		/**
		 * @warning Отказ этот недостижим: то же написание вопроса - знак пробельный, запятая либо
		 *          скобка закрывающая за ним - разбирает `flowing` собственною ветвью прежде, и условие
		 *          её строго шире здешнего. Обе ветви лежат в одном разделе разбора ENTRY, и здешняя
		 *          получает вопрос лишь тогда, когда за ним стоит знак непробельный - а тогда условие лжёт
		 */
		// Выводим отказ недопустимого знака в этом месте текста
		return this->fail(error_t::INVALID_CHARACTER, offset);
	/**
	 * Если значение построения открывается знаком примечания
	 *
	 * @note Знак примечания простого значения не открывает: запись `[ a, b,#invalid ]`
	 *       принималась значением `#invalid`, а примечанием там оно тоже не является -
	 *       пробела перед ним нет. Нашло это сличение с набором yaml-test-suite
	 */
	if(leading == '#')
		// Выводим отказ недопустимого знака в этом месте текста
		return this->fail(error_t::INVALID_CHARACTER, offset);
	/**
	 * Если значение построения одною чертою записи перечня и составлено
	 *
	 * @details Внутри скобок черта записи перечня смысла не имеет - записи там отделяет
	 *          запятая, - а простым значением она быть не вправе: описание запрещает
	 *          простому значению открываться чертою, за какою стоит пробельный знак либо
	 *          конец записи. Прежде запись `[-]` принималась значением `-`
	 *
	 * @note Число `-1` под правило это не подпадает: за чертою там стоит цифра. Отвечает
	 *       rapidyaml отказом «invalid scalar». Нашло это сличение с набором
	 *       yaml-test-suite
	 */
	if((leading == '-') && (((offset + 1) >= line.size()) || spacing(line[offset + 1]) ||
	   (line[offset + 1] == ',') || (line[offset + 1] == ']') || (line[offset + 1] == '}')))
		// Выводим отказ недопустимого знака в этом месте текста
		return this->fail(error_t::INVALID_CHARACTER, offset);
	// Вид записи разбираемого значения
	style_t style = style_t::PLAIN;
	// Смещение конца записи значения
	size_t position = offset;
	/**
	 * Если значение обнесено оградою
	 */
	if((leading == '\'') || (leading == '"')){
		// Длина записи значения вместе с оградою
		size_t length = 0;
		/**
		 * Если ограда значения не закрыта
		 */
		if(!this->bounds(line, offset, style, length))
			// Выводим отказ незакрытой ограды скалярного значения
			return this->fail(error_t::UNTERMINATED_SCALAR, offset);
		// Запоминаем смещение конца записи значения
		position = (offset + length);
	/**
	 * Если значение записано без ограды
	 */
	} else {
		/**
		 * Выполняем перебор всех знаков записи значения
		 *
		 * @note Правила окончания внутри поточного построения иные, нежели в блочном:
		 *       значение оканчивается запятой, закрывающей скобкой либо разделителем
		 *       имени пары, а не одним лишь концом строки
		 */
		while(position < line.size()){
			// Получаем очередной знак записи значения
			const char letter = line[position];
			/**
			 * Если знак оканчивает значение поточного построения
			 */
			if((letter == ',') || (letter == ']') || (letter == '}'))
				// Выходим из перебора знаков записи значения
				break;
			/**
			 * Если знак разделяет имя пары и значение её
			 */
			if((letter == ':') && (((position + 1) >= line.size()) || spacing(line[position + 1]) ||
			   (line[position + 1] == ',') || (line[position + 1] == ']') || (line[position + 1] == '}')))
				// Выходим из перебора знаков записи значения
				break;
			/**
			 * Если знак открывает примечание, стоя за пробельным знаком
			 */
			if((letter == '#') && (position > offset) && spacing(line[position - 1]))
				// Выходим из перебора знаков записи значения
				break;
			// Выполняем переход к следующему знаку записи
			position++;
		}
	}
	/**
	 * Если простое значение оборвано концом строки, разделителя не принёсшим
	 *
	 * @details Записи поточного построения строкою не отделены, и простое значение внутри
	 *          скобок вправе стоять в несколько строк: обрывает его лишь запятая, скобка
	 *          либо двоеточие. Строка, ни одного из них не принёсшая, значение продолжает,
	 *          и выдавать его сейчас значило бы разорвать надвое
	 *
	 * @note Свёртка переводов идёт тем же правилом `s-flow-folded`, каким свёртываются
	 *       значения огранённые: собирается запись дословно, а свёртка ложится на неё
	 *       при выдаче
	 */
	if((style == style_t::PLAIN) && (position >= line.size())){
		/**
		 * Если простое значение собирается уже
		 */
		if(this->_flowning)
			// Выполняем присоединение перевода строки к собираемому значению
			this->_flown.push_back('\n');
		/**
		 * Если простое значение собирать только начато
		 */
		else {
			// Запоминаем признак сборки простого значения внутри скобок
			this->_flowning = true;
			// Выполняем сброс собираемого содержимого простого значения
			this->_flown.clear();
			// Запоминаем смещение начала значения от начала текста
			this->_flowned.offset = (this->_position + offset);
			// Запоминаем номер строки, где значение началось
			this->_flowned.line = this->_line;
			// Запоминаем положение начала значения в строке
			this->_flowned.column = static_cast <uint32_t> (offset + 1);
			// Запоминаем глубину вложенности, где значение началось
			this->_flowned.depth = static_cast <uint32_t> (this->_levels.size());
		}
		// Выполняем присоединение записи значения к собираемому содержимому
		this->_flown.append(trimmed(line.substr(offset, (position - offset))));
		// Запоминаем смещение за разобранной частью значения
		offset = position;
		// Выводим признак успешного разбора значения
		return true;
	}
	/**
	 * Если простое значение собиралось строками прежними
	 *
	 * @note Собранное дожидается разделителя, и разделитель этот пришёл: выдаём значение
	 *       целиком, свёрткою переводов сложенное
	 */
	if(this->_flowning && (style == style_t::PLAIN)){
		// Выполняем присоединение перевода строки к собираемому значению
		this->_flown.push_back('\n');
		// Выполняем присоединение последней записи значения к собираемому содержимому
		this->_flown.append(trimmed(line.substr(offset, (position - offset))));
		// Выполняем сброс признака сборки простого значения внутри скобок
		this->_flowning = false;
		// Получаем собранное содержимое значения со свёрнутыми переводами строк
		const string value = folding(this->_flown, style_t::PLAIN);
		// Выполняем сброс собираемого содержимого простого значения
		this->_flown.clear();
		/**
		 * Если поставить событие значения не удалось
		 */
		if(!this->scalar(value, style, offset))
			// Выводим признак неудачного разбора значения
			return false;
		// Устанавливаем положение начала значения поставленному событию
		this->_staged.back().location = this->_flowned;
		// Запоминаем смещение за разобранным значением
		offset = position;
		// Выводим признак успешного разбора значения
		return true;
	}
	// Получаем запись значения без пробельной обвязки
	const string_view text = ((style == style_t::PLAIN) ?
		trimmed(line.substr(offset, (position - offset))) : line.substr(offset, (position - offset)));
	/**
	 * Если значение записано простым видом
	 *
	 * @details Простое значение ограды не имеет, и снимать с него нечего: перенос его в
	 *          хранилище идёт как есть. Прежде оно всё же проходило через снятие ограды,
	 *          а то заводило строку и переписывало в неё уже имеющееся - выделение и
	 *          копия на КАЖДОЕ значение документа
	 *
	 * @note Наружу это торчало счётом выделений: короткий запас строки у libc++ вмещает
	 *       22 октета и прятал их, у libstdc++ он 15 - и там же выделение шло на всякое
	 *       значение длиннее пятнадцати. На тексте в 16 МБ выходило 460 756 выделений
	 *       против 66. Работа при том делалась на всех системах, видна была лишь на
	 *       пяти из семи
	 */
	if(style == style_t::PLAIN){
		/**
		 * Если поставить событие значения не удалось
		 */
		if(!this->scalar(text, style, offset))
			// Выводим признак неудачного разбора значения
			return false;
	/**
	 * Если значение оградою окружено
	 */
	} else {
		// Собираемое содержимое значения
		string value;
		/**
		 * Если снять ограду со значения не удалось
		 */
		if(!this->unquote(text, style, offset, value))
			// Выводим признак неудачного разбора значения
			return false;
		/**
		 * Если поставить событие значения не удалось
		 */
		if(!this->scalar(value, style, offset))
			// Выводим признак неудачного разбора значения
			return false;
	}
	// Запоминаем смещение за разобранным значением
	offset = position;
	// Выводим признак успешного разбора значения
	return true;
}
/**
 * @brief Метод разбора поточного построения
 *
 * @param line   разбираемая строка
 * @param offset смещение начала разбора в строке, по выходе - смещение за ним
 * @return       признак успешного разбора построения
 *
 */
bool awh::codec::yaml::Reader::flowing(const string_view line, size_t & offset) noexcept {
	/**
	 * Признак того, что разбираемая строка содержимого не несёт вовсе
	 *
	 * @details Признак берётся при входе, а не в самом переборе: перебор доходит до конца
	 *          строки у всякой строки, и содержательной тоже, а перевод строки в собираемое
	 *          значение вносит одна лишь строка пустая
	 */
	bool blank = true;
	/**
	 * Выполняем поиск содержимого в разбираемой строке
	 */
	for(size_t i = offset; i < line.size(); i++){
		/**
		 * Если знак строки пробельным не является
		 */
		if(!spacing(line[i])){
			// Запоминаем признак того, что строка содержимое несёт
			blank = false;
			// Выходим из поиска содержимого строки
			break;
		}
	}
	// Получаем предел глубины вложенности
	const size_t limit = ((this->_settings.maxDepth > 0) ? this->_settings.maxDepth : MAX_DEPTH);
	/**
	 * Выполняем разбор строки до исчерпания её либо до закрытия всех построений
	 */
	while(true){
		/**
		 * Выполняем пропуск пробельных знаков
		 */
		while((offset < line.size()) && spacing(line[offset]))
			// Выполняем переход к следующему знаку строки
			offset++;
		/**
		 * Если содержимое строки исчерпано
		 *
		 * @note Построение, скобками не закрытое, продолжается следующею строкой, и разбор
		 *       его прерывается здесь ровно на том месте, где остановился: стопа скобок
		 *       держится полем, а не возвратностью вызовов
		 */
		if(offset >= line.size()){
			/**
			 * Если внутри скобок собирается простое значение
			 *
			 * @note Строка пустая содержимого не несёт, а перевод свой несёт: описание велит
			 *       ей стать переводом строки в собранном значении. Без учёта её запись
			 *       `[ первая`, пустая строка, `  вторая ]` давала пробел вместо перевода
			 */
			if(this->_flowning && blank)
				// Выполняем присоединение перевода строки к собираемому значению
				this->_flown.push_back('\n');
			// Выводим признак успешного разбора построения
			return true;
		}
		/**
		 * Если стопа открытых построений опустела
		 *
		 * @note Разбор окончен, и остаток строки разбирается уже обычным порядком - тем,
		 *       кто разбор поточный и затеял
		 */
		if(this->_flow.empty())
			// Выводим признак успешного разбора построения
			return true;
		// Получаем очередной разбираемый знак строки
		const char letter = line[offset];
		/**
		 * Если простое значение собиралось строками прежними, а знак его обрывает
		 *
		 * @details Простое значение внутри скобок обрывает запятая, скобка либо двоеточие.
		 *          Знак этот разбирается ниже обычным порядком, а собранное значение надлежит
		 *          выдать прежде него: без выдачи запись `[\n  1,\n  2\n  ]` теряла значение
		 *          `2` вовсе - скобка закрывала построение, а собранное оставалось в накопителе
		 *
		 * @note Выдача идёт здесь, а не в разборе значения: разделитель до разбора значения
		 *       не доходит вовсе, его разбирает сам перебор знаков построения
		 *
		 * @warning Подусловия эти - двоеточие вплотную к запятой либо скобке - истины не
		 *          принимают ни при одном написании: накопление простого значения к тому
		 *          времени уже закрыто, и `_flowning` отсекает условие целиком раньше них.
		 *          Замерено десятью написаниями: `{a:}`, `[a:]`, `{a:,b: 1}`, `[a:,1]` и те же
		 *          с значением, на две строки растянутым, - ни одно сюда не дошло
		 *
		 * @note Сносу подусловия не подлежат: они держат выдачу собранного значения на случай,
		 *       когда накопление доживёт до разделителя - написание `[\n  1,\n  2\n  ]` ровно
		 *       этим и лечилось
		 */
		if(this->_flowning && ((letter == ',') || (letter == ']') || (letter == '}') ||
		   ((letter == ':') && (((offset + 1) >= line.size()) || spacing(line[offset + 1]) ||
		   (line[offset + 1] == ',') || (line[offset + 1] == ']') || (line[offset + 1] == '}'))))){
			/**
			 * Если значение собрано в несколько строк, а обрывается двоеточием
			 *
			 * @details Имя это принадлежит отображению об одной паре, а его описание берёт
			 *          правилом `ns-flow-pair`, где имя стоит правилом `ns-s-implicit-yaml-key`
			 *          - а тому дозволена одна строка и только одна. Внутри отображения
			 *          правило иное: `ns-flow-map-yaml-key-entry` отделяет имя от двоеточия
			 *          правилом `s-separate`, а тому перевод строки дозволен, и написание
			 *          `{имя` со строкою `: значение` ниже законно
			 *
			 * @note Сличаются строки, а не наличие перевода в собранном: запись `[ имя` со
			 *       строкою `: значение` ниже перевода в собранном не имеет вовсе - имя
			 *       собрано одною строкой, - а двоеточие стоит уже в строке следующей.
			 *       Случай DK4H набора yaml-test-suite, а обратные ему - 4MUZ и VJP3
			 */
			if((letter == ':') && (this->_flow.back().kind == nesting_t::SEQUENCE) && (this->_flowned.line != this->_line))
				// Выводим отказ недопустимого знака в этом месте текста
				return this->fail(error_t::INVALID_CHARACTER, offset);
			// Выполняем сброс признака сборки простого значения внутри скобок
			this->_flowning = false;
			// Получаем собранное содержимое значения со свёрнутыми переводами строк
			const string value = folding(this->_flown, style_t::PLAIN);
			// Выполняем сброс собираемого содержимого простого значения
			this->_flown.clear();
			/**
			 * Если поставить событие значения не удалось
			 */
			if(!this->scalar(value, style_t::PLAIN, offset))
				// Выводим признак неудачного разбора построения
				return false;
			// Устанавливаем положение начала значения поставленному событию
			this->_staged.back().location = this->_flowned;
			// Запоминаем ожидание запятой либо закрывающей скобки
			this->_phase = flow_t::AFTER;
		}
		/**
		 * Если разбираемый знак открывает примечание
		 *
		 * @note Примечание внутри построения дозволено, и оканчивается им строка: остаток
		 *       её содержимым не является
		 */
		if((letter == '#') && ((offset == 0) || spacing(line[offset - 1]))){
			// Выполняем постановку события примечания
			this->remark(line, offset);
			// Выполняем переход за примечание, строку окончившее
			offset = line.size();
			// Выводим признак успешного разбора построения
			return true;
		}
		// Получаем открытое поточное построение
		bracket_t & bracket = this->_flow.back();
		// Признак того, что построение является перечнем значений
		const bool sequence = (bracket.kind == nesting_t::SEQUENCE);
		// Получаем знак, поточное построение закрывающий
		const char closer = (sequence ? ']' : '}');
		/**
		 * Если ожидается очередное значение построения
		 */
		if(this->_phase == flow_t::ENTRY){
			/**
			 * Запоминаем место начала событий записи в накопителе строки
			 *
			 * @details Место это нужно записи перечня, отображением об одной паре оказавшейся:
			 *          опознаётся она двоеточием за именем, а событие имени к тому времени
			 *          поставлено уже, и открытие отображения вставляется перед ним
			 *
			 * @note Запоминается оно у всякой записи, а не у одной скалярной: запись, вложенным
			 *       построением занятая, тоже вправе оказаться именем пары, и место, у прошлой
			 *       записи оставшееся, вставило бы открытие невесть куда
			 */
			if(sequence && !bracket.paired)
				// Запоминаем место начала событий записи
				bracket.origin = this->_staged.size();
			/**
			 * Если запись поточного построения занята одними свойствами узла
			 *
			 * @details Написание `[!!str, xxx]` описанию отвечает: первая запись есть
			 *          значение пустое, меткою типа помеченное. Прежде свойства эти
			 *          пропадали вместе с записью своей - разбор ждал значения и, не
			 *          дождавшись, ни события не ставил, ни отказа не давал
			 *
			 * @note Нашло это сличение с набором yaml-test-suite
			 */
			if(((letter == closer) || (letter == ',')) && (!this->_anchor.empty() || !this->_tag.empty())){
				/**
				 * Если поставить событие пустого значения не удалось
				 */
				if(!this->scalar(string(), style_t::PLAIN, offset))
					// Выводим признак неудачного разбора построения
					return false;
				// Устанавливаем вид пустого значения последнему событию
				this->emptied();
				// Запоминаем признак наполнения открытого построения
				bracket.filled = true;
				// Запоминаем признак того, что запись построения начата
				bracket.entered = true;
				// Запоминаем ожидание запятой либо закрывающей скобки
				this->_phase = flow_t::AFTER;
				// Выполняем переход к разбору того же знака строки
				continue;
			}
			/**
			 * Если построение закрывается скобкой
			 */
			if(letter == closer){
				/**
				 * Если имя пары осталось без значения своего
				 *
				 * @details Случая тут два, и оба дают пустое значение: имя без двоеточия
				 *          вовсе - запись `{a}` - и двоеточие без значения за ним - запись
				 *          `{a:}`. Прежде сличался лишь первый, и второй терял значение
				 *          пары молча
				 *
				 * @note Случаи C2DT и DFF7 набора yaml-test-suite
				 */
				if(!sequence && (bracket.entered || bracket.valued)){
					/**
					 * Количество пустот, паре недостающих
					 *
					 * @note Вопрос, содержимого за собою не имеющий, даёт пару из двух пустот -
					 *       имени и значения, - а имя без двоеточия даёт одну лишь пустоту
					 *       значения
					 */
					const size_t missing = ((bracket.asked && !bracket.valued) ? 2 : 1);
					/**
					 * Выполняем постановку недостающих пустот пары
					 */
					for(size_t i = 0; i < missing; i++){
						/**
						 * Если поставить событие пустого значения не удалось
						 *
						 * @warning Заход этот НЕДОСТИЖИМ, покуда держится условие: событие пустоты ставится
						 *          там, где метки вида уже нет, а без метки разрешение вида отказа не даёт -
						 *          запись пустая ни предела длины не превышает, ни метки порядка байтов не
						 *          несёт. Замерено шестнадцатью записями с меткою `!!bool` над пустотою
						 *          построения поточного: ни одна сюда не дошла - метку забирает заход
						 *          скалярного значения раньше
						 *
						 * @note Сносу заход не подлежит: у закрытия документа метка до пустоты доживает, и
						 *       там отказ этот управление получает - проверка `TagsAndAnchors` тому порукой
						 */
						if(!this->scalar(string(), style_t::PLAIN, offset))
							// Выводим признак неудачного разбора построения
							return false;
						// Устанавливаем вид пустого значения последнему событию
						this->emptied();
					}
				}
				/**
				 * Если запись перечня отображением об одной паре объявлена
				 *
				 * @details Скобок своих отображение это не имеет вовсе, и закрывается оно
				 *          запятой либо скобкой перечня. Ветка эта закрытие его упускала:
				 *          разобран был один лишь случай отображения, а перечень с парою
				 *          открытою уходил со стопы, событие закрытия перечня выдавалось
				 *          прежде закрытия пары, и поток событий выходил перекрещенным -
				 *          запись `[ x:]` давала SEQUENCE_END прежде MAPPING_END. Строитель
				 *          дерева снимал тогда не тот уровень, размах корня оставался
				 *          единицею, и перезапись выдавала пустое отображение вместо всего
				 *          документа
				 *
				 * @note Значение пары, двоеточием объявленной и не пришедшей, выдаётся
				 *       пустым: пара без значения есть пара. Прежде оно пропадало вовсе.
				 *       Нашёл это ворошитель длинным прогоном
				 */
				if(sequence && bracket.paired){
					/**
					 * Если поставить событие пустого значения не удалось
					 *
					 * @warning Заход этот НЕДОСТИЖИМ, покуда держится условие: событие пустоты ставится
					 *          там, где метки вида уже нет, а без метки разрешение вида отказа не даёт -
					 *          запись пустая ни предела длины не превышает, ни метки порядка байтов не
					 *          несёт. Замерено шестнадцатью записями с меткою `!!bool` над пустотою
					 *          построения поточного: ни одна сюда не дошла - метку забирает заход
					 *          скалярного значения раньше
					 *
					 * @note Сносу заход не подлежит: у закрытия документа метка до пустоты доживает, и
					 *       там отказ этот управление получает - проверка `TagsAndAnchors` тому порукой
					 */
					if(!this->scalar(string(), style_t::PLAIN, offset))
						// Выводим признак неудачного разбора построения
						return false;
					// Устанавливаем вид пустого значения последнему событию
					this->emptied();
					// Выполняем постановку события закрытия отображения об одной паре
					this->emit(event_t::MAPPING_END, offset);
					// Выполняем сброс признака отображения об одной паре
					bracket.paired = false;
					// Выполняем сброс признака разбора значения пары
					bracket.valued = false;
				}
				// Выполняем переход за закрывающую скобку построения
				offset++;
				// Выполняем снятие закрытого построения со стопы
				this->_flow.pop_back();
				// Выполняем постановку события закрытия построения
				this->emit((sequence ? event_t::SEQUENCE_END : event_t::MAPPING_END), offset);
				// Запоминаем ожидание запятой либо закрывающей скобки
				this->_phase = flow_t::AFTER;
				// Выполняем переход к разбору следующего знака строки
				continue;
			}
			/**
			 * Если построение закрывается скобкой чужого вида
			 */
			if((letter == ']') || (letter == '}'))
				// Выводим отказ незакрытого поточного построения
				return this->fail(error_t::UNCLOSED_FLOW, offset);
			/**
			 * Если запись открывается вопросом составного имени
			 *
			 * @details Вопрос внутри скобок объявляет имя пары ровно так же, как объявляет он
			 *          его построением блочным. Вопросом здесь он является лишь тогда, когда
			 *          за ним стоит пробельный знак, запятая либо скобка: описание берёт его
			 *          указателем правилом `c-flow-mapping`, а `?имя` есть простое значение
			 *
			 * @note Внутри перечня вопрос заводит отображение об одной паре: запись `[ ? имя ]`
			 *       описание берёт правилом `ns-flow-pair` наравне с записью `[ имя: значение ]`
			 */
			if((letter == '?') && (((offset + 1) >= line.size()) || spacing(line[offset + 1]) ||
			   (line[offset + 1] == ',') || (line[offset + 1] == ']') || (line[offset + 1] == '}'))){
				/**
				 * Если запись стоит внутри перечня значений
				 */
				if(sequence){
					/**
					 * Если запись перечня отображением об одной паре уже объявлена
					 */
					if(bracket.paired)
						// Выводим отказ недопустимого знака в этом месте текста
						return this->fail(error_t::INVALID_CHARACTER, offset);
					// Выполняем постановку события открытия отображения об одной паре
					this->emit(event_t::MAPPING_START, offset);
					// Запоминаем признак отображения об одной паре, внутри перечня открытого
					bracket.paired = true;
					// Запоминаем место начала событий записи за открытием отображения
					bracket.origin = this->_staged.size();
				}
				// Запоминаем признак наполнения открытого построения
				bracket.filled = true;
				// Запоминаем признак того, что запись построения начата
				bracket.entered = true;
				// Запоминаем признак того, что запись объявлена вопросом составного имени
				bracket.asked = true;
				// Выполняем сброс признака разбора значения пары
				bracket.valued = false;
				// Запоминаем признак наполнения открытого документа
				this->_filled = true;
				// Выполняем переход за вопрос составного имени
				offset++;
				// Выполняем переход к разбору следующего знака строки
				continue;
			}
			/**
			 * Если значение подменено запятой
			 *
			 * @details Запятая на месте значения означает запись пустую, а таких построение
			 *          не несёт: разделитель отделяет записи друг от друга, и двум
			 *          разделителям подряд отделять нечего. Прежде запись `[ a, b, , c ]`
			 *          принималась с пустым значением посреди неё
			 *
			 * @note Отказ этот отвечает rapidyaml: она отвергает и `[ a, , b ]`, и
			 *       `{ a: 1, , }`. Запятая же перед скобкою закрывающей дозволена - она
			 *       записи не открывает, а закрывает последнюю. Нашло это сличение с
			 *       набором yaml-test-suite
			 */
			if(letter == ','){
				/**
				 * Если запятая стоит на месте значения пары, двоеточием объявленной
				 *
				 * @details Пара, двоеточие несущая, значение своё вправе не иметь вовсе:
				 *          правило `e-node` пустоту значением признаёт. Запись `{ имя:, }`
				 *          тем и разнится с записью `[ a, , b ]`, что там запятая стоит на
				 *          месте целой записи, а здесь - на месте значения объявленной пары
				 *
				 * @note Прежде отказ шёл на обе разом. Случаи 4ABK и FRK4 набора
				 *       yaml-test-suite
				 */
				if(bracket.valued){
					/**
					 * Если поставить событие пустого значения не удалось
					 *
					 * @warning Заход этот НЕДОСТИЖИМ, покуда держится условие: событие пустоты ставится
					 *          там, где метки вида уже нет, а без метки разрешение вида отказа не даёт -
					 *          запись пустая ни предела длины не превышает, ни метки порядка байтов не
					 *          несёт. Замерено шестнадцатью записями с меткою `!!bool` над пустотою
					 *          построения поточного: ни одна сюда не дошла - метку забирает заход
					 *          скалярного значения раньше
					 *
					 * @note Сносу заход не подлежит: у закрытия документа метка до пустоты доживает, и
					 *       там отказ этот управление получает - проверка `TagsAndAnchors` тому порукой
					 */
					if(!this->scalar(string(), style_t::PLAIN, offset))
						// Выводим признак неудачного разбора построения
						return false;
					// Устанавливаем вид пустого значения последнему событию
					this->emptied();
					/**
					 * Если запись перечня отображением об одной паре объявлена
					 *
					 * @note Скобок своих отображение это не имеет, и закрывается оно
					 *       запятой - той самой, что стоит на месте значения
					 */
					if(bracket.paired){
						// Выполняем постановку события закрытия отображения об одной паре
						this->emit(event_t::MAPPING_END, offset);
						// Выполняем сброс признака отображения об одной паре
						bracket.paired = false;
					}
					// Выполняем сброс признака разбора значения пары
					bracket.valued = false;
					// Выполняем сброс признака начатой записи построения
					bracket.entered = false;
					// Выполняем сброс признака записи, вопросом объявленной
					bracket.asked = false;
					// Выполняем переход за разделитель значений
					offset++;
					// Запоминаем ожидание очередного значения построения
					this->_phase = flow_t::ENTRY;
					// Выполняем переход к разбору следующего знака строки
					continue;
				}
				// Выводим отказ ожидания значения
				return this->fail(error_t::EXPECTED_VALUE, offset);
			}
			/**
			 * Если значение открывается свойствами узла
			 *
			 * @details Свойства снимаются здесь, а не разбором значения: за ними вправе
			 *          стоять вложенное построение, а разбор значения построений не знает и
			 *          прочёл бы скобку началом записи без ограды. Снятые свойства ждут узла
			 *          своего и достаются ему, скаляр то будет либо построение
			 */
			if((letter == '&') || (letter == '!')){
				/**
				 * Если разобрать свойства узла не удалось
				 */
				if(!this->property(line, offset))
					// Выводим признак неудачного разбора построения
					return false;
				// Выполняем переход к разбору следующего знака строки
				continue;
			}
			/**
			 * Если значение является вложенным поточным построением
			 */
			if((letter == '[') || (letter == '{')){
				/**
				 * Если глубина вложенности предел превышает
				 */
				if((this->_levels.size() + this->_flow.size()) >= limit)
					// Выводим отказ превышения глубины вложенности
					return this->fail(error_t::DEPTH_EXCEEDED, offset);
				/**
				 * Если метка типа, построению предпосланная, виду его противна
				 */
				if(!this->matched(((letter == '[') ? nesting_t::SEQUENCE : nesting_t::MAPPING), offset))
					// Выводим признак неудачного разбора построения
					return false;
				// Запоминаем признак наполнения открытого построения
				bracket.filled = true;
				// Запоминаем признак того, что запись построения начата
				bracket.entered = true;
				// Выполняем постановку события открытия вложенного построения
				item_t & item = this->emit(((letter == '[') ? event_t::SEQUENCE_START : event_t::MAPPING_START), offset);
				// Выполняем перенос накопленных свойств узла в собранное событие
				this->attach(item);
				// Запоминаем признак наполнения открытого документа
				this->_filled = true;
				// Выполняем открытие вложенного поточного построения
				this->_flow.emplace_back((letter == '[') ? nesting_t::SEQUENCE : nesting_t::MAPPING);
				// Выполняем переход за открывающую скобку построения
				offset++;
				// Выполняем переход к разбору следующего знака строки
				continue;
			}
			/**
			 * Если разобрать очередное значение не удалось
			 */
			if(!this->flowed(line, offset))
				// Выводим признак неудачного разбора построения
				return false;
			// Запоминаем признак наполнения открытого построения
			this->_flow.back().filled = true;
			/**
			 * Запоминаем ожидание запятой либо закрывающей скобки
			 *
			 * @note Простое значение, концом строки оборванное, разделителя ещё не имеет:
			 *       ожидание его означало бы, что строка следующая обязана открыться
			 *       запятой, - а она значение продолжает
			 */
			if(!this->_flowning)
				// Запоминаем ожидание запятой либо закрывающей скобки
				this->_phase = flow_t::AFTER;
			// Выполняем переход к разбору следующего знака строки
			continue;
		}
		/**
		 * Если за значением стоит разделитель имени пары
		 */
		if(letter == ':'){
			/**
			 * Если построение является перечнем значений
			 *
			 * @details Описание берёт запись `[ имя: значение ]` правилом `ns-flow-pair`:
			 *          запись перечня там есть отображение, одну пару несущее. Скобок своих
			 *          отображение это не имеет вовсе, и закрывается оно запятой либо
			 *          скобкой перечня
			 *
			 * @note Событие имени поставлено уже, и открытие отображения вставляется перед
			 *       ним - на место, запомненное началом записи
			 */
			if(sequence && !bracket.paired){
				/**
				 * Если место начала записи за накопителем строки вышло
				 */
				if(bracket.origin > this->_staged.size())
					// Выводим отказ недопустимого знака в этом месте текста
					return this->fail(error_t::INVALID_CHARACTER, offset);
				// Выполняем постановку события открытия отображения об одной паре
				this->emit(event_t::MAPPING_START, offset);
				/**
				 * Если событие имени пары в накопителе стоит
				 *
				 * @note Место события открытия берётся у имени пары: отображение стоит там же,
				 *       где стоит имя его, а не там, где стоит двоеточие
				 */
				if(bracket.origin < (this->_staged.size() - 1))
					// Переносим место события открытия отображения на имя пары
					this->_staged.back().location = this->_staged.at(bracket.origin).location;
				// Получаем поставленное событие открытия отображения
				const item_t opening = this->_staged.back();
				// Выполняем снятие события открытия с конца накопителя
				this->_staged.pop_back();
				// Выполняем вставку события открытия отображения перед именем пары
				this->_staged.insert((this->_staged.begin() + static_cast <ptrdiff_t> (bracket.origin)), opening);
				// Запоминаем признак отображения об одной паре, внутри перечня открытого
				bracket.paired = true;
			}
			/**
			 * Если имя пары прочитано уже вместе со значением её
			 */
			if(bracket.valued)
				// Выводим отказ недопустимого знака в этом месте текста
				return this->fail(error_t::INVALID_CHARACTER, offset);
			// Запоминаем признак разбора значения пары
			bracket.valued = true;
			// Выполняем переход за разделитель имени пары
			offset++;
			// Запоминаем ожидание очередного значения построения
			this->_phase = flow_t::ENTRY;
			// Выполняем переход к разбору следующего знака строки
			continue;
		}
		/**
		 * Если построение закрывается скобкой
		 */
		if(letter == closer){
			/**
			 * Если имя пары осталось без значения своего
			 *
			 * @note Отображение `{a, b}` описанием дозволено: значения пар пусты. Выдаём их
			 *       пустыми значениями, ибо пара без значения есть пара
			 */
			if(!sequence && !bracket.valued){
				/**
				 * Если поставить событие пустого значения не удалось
				 *
				 * @warning Заход этот НЕДОСТИЖИМ, покуда держится условие: событие пустоты ставится
				 *          там, где метки вида уже нет, а без метки разрешение вида отказа не даёт -
				 *          запись пустая ни предела длины не превышает, ни метки порядка байтов не
				 *          несёт. Замерено шестнадцатью записями с меткою `!!bool` над пустотою
				 *          построения поточного: ни одна сюда не дошла - метку забирает заход
				 *          скалярного значения раньше
				 *
				 * @note Сносу заход не подлежит: у закрытия документа метка до пустоты доживает, и
				 *       там отказ этот управление получает - проверка `TagsAndAnchors` тому порукой
				 */
				if(!this->scalar(string(), style_t::PLAIN, offset))
					// Выводим признак неудачного разбора построения
					return false;
				// Устанавливаем вид пустого значения последнему событию
				this->emptied();
			}
			/**
			 * Если запись перечня отображением об одной паре объявлена
			 *
			 * @note Скобок своих отображение это не имеет вовсе, и закрывается оно здесь -
			 *       запятой либо скобкой перечня. Значение пары, двоеточием объявленной и
			 *       не пришедшей, выдаётся пустым: пара без значения есть пара
			 */
			if(bracket.paired){
				/**
				 * Если имя пары осталось без значения своего
				 */
				if(!bracket.valued){
					/**
					 * Если поставить событие пустого значения не удалось
					 *
					 * @warning Заход этот НЕДОСТИЖИМ, покуда держится условие: событие пустоты ставится
					 *          там, где метки вида уже нет, а без метки разрешение вида отказа не даёт -
					 *          запись пустая ни предела длины не превышает, ни метки порядка байтов не
					 *          несёт. Замерено шестнадцатью записями с меткою `!!bool` над пустотою
					 *          построения поточного: ни одна сюда не дошла - метку забирает заход
					 *          скалярного значения раньше
					 *
					 * @note Сносу заход не подлежит: у закрытия документа метка до пустоты доживает, и
					 *       там отказ этот управление получает - проверка `TagsAndAnchors` тому порукой
					 */
					if(!this->scalar(string(), style_t::PLAIN, offset))
						// Выводим признак неудачного разбора построения
						return false;
					// Устанавливаем вид пустого значения последнему событию
					this->emptied();
				}
				// Выполняем постановку события закрытия отображения об одной паре
				this->emit(event_t::MAPPING_END, offset);
				// Выполняем сброс признака отображения об одной паре
				bracket.paired = false;
				// Выполняем сброс признака разбора значения пары
				bracket.valued = false;
			}
			// Выполняем переход за закрывающую скобку построения
			offset++;
			// Выполняем снятие закрытого построения со стопы
			this->_flow.pop_back();
			// Выполняем постановку события закрытия построения
			this->emit((sequence ? event_t::SEQUENCE_END : event_t::MAPPING_END), offset);
			// Выполняем переход к разбору следующего знака строки
			continue;
		}
		/**
		 * Если за значением стоит разделитель значений
		 */
		if(letter == ','){
			/**
			 * Если имя пары осталось без значения своего
			 */
			if(!sequence && !bracket.valued){
				/**
				 * Если поставить событие пустого значения не удалось
				 *
				 * @warning Заход этот НЕДОСТИЖИМ, покуда держится условие: событие пустоты ставится
				 *          там, где метки вида уже нет, а без метки разрешение вида отказа не даёт -
				 *          запись пустая ни предела длины не превышает, ни метки порядка байтов не
				 *          несёт. Замерено шестнадцатью записями с меткою `!!bool` над пустотою
				 *          построения поточного: ни одна сюда не дошла - метку забирает заход
				 *          скалярного значения раньше
				 *
				 * @note Сносу заход не подлежит: у закрытия документа метка до пустоты доживает, и
				 *       там отказ этот управление получает - проверка `TagsAndAnchors` тому порукой
				 */
				if(!this->scalar(string(), style_t::PLAIN, offset))
					// Выводим признак неудачного разбора построения
					return false;
				// Устанавливаем вид пустого значения последнему событию
				this->emptied();
			}
			/**
			 * Если запись перечня отображением об одной паре объявлена
			 *
			 * @note Скобок своих отображение это не имеет вовсе, и закрывается оно здесь -
			 *       запятой либо скобкой перечня. Значение пары, двоеточием объявленной и
			 *       не пришедшей, выдаётся пустым: пара без значения есть пара
			 */
			if(bracket.paired){
				/**
				 * Если имя пары осталось без значения своего
				 */
				if(!bracket.valued){
					/**
					 * Если поставить событие пустого значения не удалось
					 *
					 * @warning Заход этот НЕДОСТИЖИМ, покуда держится условие: событие пустоты ставится
					 *          там, где метки вида уже нет, а без метки разрешение вида отказа не даёт -
					 *          запись пустая ни предела длины не превышает, ни метки порядка байтов не
					 *          несёт. Замерено шестнадцатью записями с меткою `!!bool` над пустотою
					 *          построения поточного: ни одна сюда не дошла - метку забирает заход
					 *          скалярного значения раньше
					 *
					 * @note Сносу заход не подлежит: у закрытия документа метка до пустоты доживает, и
					 *       там отказ этот управление получает - проверка `TagsAndAnchors` тому порукой
					 */
					if(!this->scalar(string(), style_t::PLAIN, offset))
						// Выводим признак неудачного разбора построения
						return false;
					// Устанавливаем вид пустого значения последнему событию
					this->emptied();
				}
				// Выполняем постановку события закрытия отображения об одной паре
				this->emit(event_t::MAPPING_END, offset);
				// Выполняем сброс признака отображения об одной паре
				bracket.paired = false;
				// Выполняем сброс признака разбора значения пары
				bracket.valued = false;
			}
			// Выполняем сброс признака разбора значения пары
			bracket.valued = false;
			// Выполняем сброс признака начатой записи построения
			bracket.entered = false;
			// Выполняем сброс признака записи, вопросом объявленной
			bracket.asked = false;
			// Выполняем переход за разделитель значений
			offset++;
			// Запоминаем ожидание очередного значения построения
			this->_phase = flow_t::ENTRY;
			// Выполняем переход к разбору следующего знака строки
			continue;
		}
		/**
		 * Выводим отказ ожидания запятой либо закрывающей скобки
		 *
		 * @note Отказом этим отвергается и скобка чужого вида, за значением стоящая: место
		 *       отказа названо им точнее, нежели одним лишь незакрытым построением
		 */
		return this->fail(error_t::EXPECTED_COMMA, offset);
	}
}
/**
 * @brief Метод свёртки логической строки в собираемое простое значение
 *
 * @details Строка приходит сюда ЛОГИЧЕСКОЙ: склейка сводит в неё несколько строк исходных,
 * когда первая из них ограду значения открывает и не закрывает. Ограда та внутри простого
 * значения оградою не является вовсе - кавычка значаща лишь на месте значения, - и
 * присоединение склеенного дословно клало перевод строки внутрь значения сырым
 *
 * @warning Порок этот виден лишь хвостовым переводом строки: строка последняя, перевода не
 *          имеющая, склейке не подлежит вовсе. Написание `l\n- "\n-` без перевода давало
 *          значение `l - " -`, а с переводом - `l - "\n-`: хвостовой перевод менял
 *          содержимое значения, стоящего много выше него
 *
 * @note Свёртка ведётся тем же правилом, каким свёрнуты строки, склейке не подвергшиеся:
 *       перевод один обращается пробелом, а каждый следующий остаётся переводом
 *
 * @param text сворачиваемая логическая строка
 *
 */
void awh::codec::yaml::Reader::folded(const string_view text) noexcept {
	// Присоединяемое содержимое логической строки
	const string_view joined = text;
	// Смещение начала очередной строки исходной внутри логической
	size_t origin = 0;
	/**
	 * Выполняем перебор всех строк исходных, в логическую склеенных
	 */
	while(origin <= joined.size()){
		// Разыскиваем знак конца очередной строки исходной
		const size_t breaking = joined.find('\n', origin);
		// Получаем длину очередной строки исходной
		const size_t width = (((breaking == string_view::npos) ? joined.size() : breaking) - origin);
		// Получаем содержимое очередной строки исходной без обвязки
		const string_view piece = trimmed(joined.substr(origin, width));
		/**
		 * Если строка первою в логической является
		 */
		if(origin == 0)
			// Выполняем присоединение содержимого строки к собираемому значению
			this->_plain.append(piece);
		/**
		 * Если строка исходная пуста вовсе
		 *
		 * @note Строка пустая переводом и остаётся: свёртка обращает пробелом лишь перевод
		 *       одиночный
		 */
		else if(piece.empty())
			// Выполняем присоединение перевода строки к собираемому значению
			this->_plain.append(1, '\n');
		/**
		 * Если строка исходная содержимое несёт
		 */
		else {
			// Выполняем присоединение свёрнутого перевода строки
			this->_plain.append(1, ' ');
			// Выполняем присоединение содержимого строки к собираемому значению
			this->_plain.append(piece);
		}
		/**
		 * Если знака конца строки в логической больше нет
		 */
		if(breaking == string_view::npos)
			// Выходим из перебора строк исходных
			break;
		// Выполняем переход к следующей строке исходной
		origin = (breaking + 1);
	}
}
/**
 * @brief Метод откладывания выдачи простого значения
 *
 * @param text   содержимое простого значения
 * @param column положение значения в разбираемой строке
 * @return       признак успешного откладывания выдачи
 *
 */
bool awh::codec::yaml::Reader::deferred(const string_view text, const size_t column) noexcept {
	// Запоминаем признак сборки простого значения
	this->_plaining = true;
	// Запоминаем собранное содержимое простого значения
	/**
	 * Выполняем свёртку логической строки в собираемое простое значение
	 *
	 * @details Строка приходит сюда ЛОГИЧЕСКОЙ: склейка сводит в неё несколько строк
	 * исходных, когда первая из них ограду значения открывает и не закрывает. Ограда та
	 * внутри простого значения оградою не является вовсе, и присоединение склеенного
	 * дословно клало перевод строки внутрь значения сырым
	 *
	 * @warning Написание `o["\n ` с переводом хвостовым давало значение `o["` с переводом
	 *          внутри, а то же написание без перевода - значение `o["` без него: строка
	 *          последняя, перевода не имеющая, склейке не подлежит вовсе, и порок на ней
	 *          не проявлялся
	 *
	 * @note Свёртка та же, какою пользуется присоединение строк ниже: перевод один
	 *       обращается пробелом, а каждый следующий остаётся переводом
	 */
	this->_plain.clear();
	// Выполняем свёртку логической строки в собираемое простое значение
	this->folded(text);
	// Выполняем сброс количества пустых строк значения
	this->_folds = 0;
	/**
	 * Запоминаем отступ, который обязано превышать продолжение значения
	 *
	 * @details Отступ этот берётся у построения, значение объемлющего, а не у строки, в
	 *          которой значение началось: запись `ключ:` со значением строкою ниже ставит
	 *          продолжение его на тот же отступ, что и начало, и мерить продолжение
	 *          началом значило бы оборвать значение на первой же строке
	 */
	this->_required = (this->_levels.empty() ? 0 : this->_levels.back().indent);
	// Запоминаем смещение начала значения от начала текста
	this->_origin.offset = (this->_position + column);
	// Запоминаем номер строки, где значение началось
	this->_origin.line = this->_line;
	// Запоминаем положение начала значения в строке
	this->_origin.column = static_cast <uint32_t> (column + 1);
	// Запоминаем глубину вложенности, где значение началось
	this->_origin.depth = static_cast <uint32_t> (this->_levels.size());
	// Выводим признак успешного откладывания выдачи
	return true;
}
/**
 * @brief Метод выдачи собранного простого значения
 *
 * @return признак успешной выдачи значения
 *
 */
bool awh::codec::yaml::Reader::settle() noexcept {
	/**
	 * Если простое значение не собирается вовсе
	 */
	if(!this->_plaining)
		// Выводим признак успешной выдачи значения
		return true;
	// Выполняем сброс признака сборки простого значения
	this->_plaining = false;
	/**
	 * Получаем собранное содержимое простого значения
	 *
	 * @details Берётся оно СРЕЗОМ члена, а не копией его: копия заводилась лишь затем,
	 *          чтобы очистить член до выдачи, - а очистить его можно и после неё.
	 *          Постановка события содержимое своё переносит в хранилище знаков и
	 *          указателя на него не держит, так что срез переживает выдачу свободно
	 *
	 * @note Копия эта стоила выделения на КАЖДОЕ простое значение документа. Короткий
	 *       запас строки у libc++ вмещает 22 октета и прятал её, у libstdc++ он 15 - и
	 *       там выделение шло на всякое значение длиннее пятнадцати. На тексте в 16 МБ
	 *       выходило 460 756 выделений против 66, то есть работа делалась на ВСЕХ
	 *       системах, а видна была на пяти машинах из семи
	 */
	const string_view text(this->_plain);
	/**
	 * Запоминаем количество пустых строк, к значению не приставших
	 *
	 * @details Пустые строки, за простым значением стоящие, значению принадлежат лишь
	 *          тогда, когда за ними приходит содержимое: тогда они переводами строк в
	 *          него и ложатся. Не дождавшись содержимого, они значению чужие, и
	 *          затребованная выдача их обязана выдать их событиями
	 *
	 * @note Без этого выдача пустых строк зависела от оформления соседнего значения:
	 *       за закавыченным значением пустая строка выдавалась, а за простым пропадала,
	 *       ибо простое ждало продолжения и строку эту съедало
	 */
	const uint32_t folds = this->_folds;
	// Выполняем сброс количества пустых строк значения
	this->_folds = 0;
	/**
	 * Если поставить событие простого значения не удалось
	 */
	if(!this->scalar(text, style_t::PLAIN, 0)){
		// Выполняем сброс собираемого содержимого значения
		this->_plain.clear();
		// Выводим признак неудачной выдачи значения
		return false;
	}
	// Выполняем сброс собираемого содержимого значения
	this->_plain.clear();
	/**
	 * Устанавливаем положение начала значения поставленному событию
	 *
	 * @note Событие ставится там, где значение окончилось, а стоит оно там, где началось:
	 *       потребителю указывать надлежит на начало записи, а не на конец её
	 */
	this->_staged.back().location = this->_origin;
	/**
	 * Если выдача пустых строк затребована, а строки такие за значением стояли
	 */
	if(this->_settings.emitBlanks && (folds > 0)){
		/**
		 * Выполняем перебор всех пустых строк, к значению не приставших
		 */
		for(uint32_t i = 0; i < folds; i++)
			// Выполняем постановку события пустой строки
			this->emit(event_t::BLANK, 0);
	}
	/**
	 * Выполняем перенос собранных событий в очередь выдачи
	 *
	 * @details Значение это принадлежит строке прошлой, и та разобрана уже целиком:
	 *          отказ строки нынешней отозвать его не вправе. Без переноса этого отказ
	 *          сбросил бы накопитель строки вместе со значением, прошлою строкой
	 *          собранным, и откладывание выдачи меняло бы исход разбора
	 */
	this->commit();
	// Выводим признак успешной выдачи значения
	return true;
}
/**
 * @brief Метод присоединения очередной строки к простому значению
 *
 * @param line     присоединяемая строка
 * @param attached признак присоединения строки к простому значению
 * @return         признак успешного присоединения строки
 *
 */
bool awh::codec::yaml::Reader::plaining(const string_view line, bool & attached) noexcept {
	// Выполняем сброс признака присоединения строки
	attached = false;
	// Смещение начала содержимого строки за отступом
	size_t offset = 0;
	/**
	 * Выполняем пропуск отступа присоединяемой строки
	 */
	while((offset < line.size()) && (line[offset] == ' '))
		// Выполняем переход к следующему знаку строки
		offset++;
	/**
	 * Смещение содержимого строки за отделителем его
	 *
	 * @details Отступ описанием набирается одними пробелами, а за ним правило
	 *          `s-flow-line-prefix` дозволяет отделитель `s-separate-in-line` - пробелы
	 *          вместе с подачами. Оттого подача, продолжение значения открывающая, есть
	 *          отделитель, а не содержимое: написание со строкою `\tтретья` даёт `вторая
	 *          третья`, а не `вторая \tтретья`
	 *
	 * @note Считаются они порознь: отступ сличается с отступом построения, и подача в
	 *       счёт его не идёт. Случаи HS5T, NB6Z и UV7Q набора yaml-test-suite
	 */
	size_t content = offset;
	/**
	 * Выполняем пропуск отделителя содержимого присоединяемой строки
	 */
	while((content < line.size()) && spacing(line[content]))
		// Выполняем переход к следующему знаку строки
		content++;
	/**
	 * Если строка пуста
	 *
	 * @details Пустая строка значения не завершает: описание велит ей стать переводом
	 *          строки в собранном содержимом, а завершить значение вправе лишь строка
	 *          содержательная, отступом мельче. Оттого пустые строки лишь считаются, а
	 *          учтутся они приходом содержимого - либо пропадут, коли содержимого не будет
	 *
	 * @note Пустою считается и строка, одними подачами набранная: они суть отделитель,
	 *       и содержимого за ними нет
	 */
	if(content >= line.size()){
		// Выполняем учёт пустой строки, содержимого ещё не дождавшейся
		this->_folds++;
		// Запоминаем признак присоединения строки
		attached = true;
		// Выводим признак успешного присоединения строки
		return true;
	}
	/**
	 * Если отступ строки отступа объемлющего построения не превышает
	 *
	 * @note Значение, стоящее содержимым документа целиком, под правило это не подпадает:
	 *       построений над ним нет вовсе, и описание дозволяет продолжению его стоять с
	 *       начала строки - правило `s-l+block-node` берёт там отступ мельче нулевого.
	 *       Прежде написание `a` со строкою `b` ниже отказ получало. Нашло это сличение с
	 *       набором yaml-test-suite
	 */
	/**
	 * Если строка чертою начала либо конца документа открывается
	 *
	 * @details Черты эти содержимым значения не являются: описание запрещает их внутри
	 *          него правилом `c-forbidden` прямо. Прежде правило это исполнялось отступом
	 *          - продолжение обязано было стоять глубже построения, а черты стоят с начала
	 *          строки, - и с дозволением значению корневому продолжаться с начала строки
	 *          оно исполняться перестало: значение проглатывало черту вместе с документом
	 *          за нею
	 *
	 * @note Нашёл это ворошитель
	 */
	if((offset == 0) && ((line.compare(0, 3, "---") == 0) || (line.compare(0, 3, "...") == 0)) &&
	   ((line.size() == 3) || spacing(line[3])))
		// Выводим признак успешного присоединения строки
		return true;
	if(!this->_levels.empty() && (static_cast <uint32_t> (offset) <= this->_required))
		// Выводим признак успешного присоединения строки
		return true;
	/**
	 * Если строка несёт одно лишь примечание
	 *
	 * @note Примечание простое значение завершает: описание примечаний внутри значения
	 *       не знает вовсе
	 */
	if(line[offset] == '#')
		// Выводим признак успешного присоединения строки
		return true;
	/**
	 * Строка, чертою записи перечня открывающаяся, значение продолжает
	 *
	 * @details Запрет черты касается лишь первого знака простого значения: описание
	 * ограничивает `ns-plain-first`, а строки последующие собираются знаками
	 * `ns-plain-char`, среди коих черта дозволена. Строка глубже отступа объемлющего
	 * построения записью перечня быть не может - записи стоят отступом своим, - и
	 * остаётся ей быть продолжением значения
	 *
	 * @note Прежде здесь стоял отказ с доводом, будто записи эти описанием запрещены
	 *       прямо. Довод проверки не выдержал: libyaml и libfyaml обе складывают такую
	 *       строку в значение, выдавая `x - y` одним значением, а отказ был отвержением
	 *       написания дозволенного
	 */
	/**
	 * Выполняем поиск разделителя имени пары в присоединяемой строке
	 */
	for(size_t i = offset; i < line.size(); i++){
		/**
		 * Если строка несёт разделитель имени пары
		 *
		 * @note Простое значение разделителя этого нести не вправе вовсе: неведомо, пара
		 *       ли это внутри значения либо значение с двоеточием, и описание запрещает
		 *       запись эту прямо
		 */
		if((line[i] == ':') && (((i + 1) >= line.size()) || spacing(line[i + 1])))
			// Выводим отказ недопустимого знака в этом месте текста
			return this->fail(error_t::INVALID_CHARACTER, i);
	}
	// Длина содержимого строки без примечания за ним
	size_t length = line.size();
	/**
	 * Выполняем поиск примечания за содержимым присоединяемой строки
	 */
	for(size_t i = offset; i < length; i++){
		/**
		 * Если знак открывает примечание, стоя за пробельным знаком
		 */
		if((line[i] == '#') && (i > offset) && spacing(line[i - 1])){
			// Запоминаем длину содержимого строки без примечания
			length = i;
			// Выходим из поиска примечания
			break;
		}
	}
	/**
	 * Если пустые строки содержимого дождались
	 *
	 * @note Свёртка описанием задана так: перевод строки один обращается пробелом, а
	 *       каждый следующий остаётся переводом
	 */
	if(this->_folds > 0)
		// Выполняем присоединение переводов строк к собираемому значению
		this->_plain.append(this->_folds, '\n');
	// Если пустых строк не было вовсе
	else this->_plain.append(1, ' ');
	// Выполняем сброс количества пустых строк значения
	this->_folds = 0;
	// Выполняем свёртку логической строки в собираемое простое значение
	this->folded(line.substr(content, (length - content)));
	// Запоминаем признак присоединения строки
	attached = true;
	/**
	 * Если за содержимым строки стоит примечание
	 */
	if(length < line.size()){
		/**
		 * Если выдать собранное простое значение не удалось
		 *
		 * @note Примечание значение завершает, и выдать его надлежит прежде постановки
		 *       события примечания: иначе примечание оказалось бы прежде значения, за
		 *       которым стоит
		 */
		if(!this->settle())
			// Выводим признак неудачного присоединения строки
			return false;
		// Выполняем постановку события примечания
		this->remark(line, length);
	}
	// Выводим признак успешного присоединения строки
	return true;
}
/**
 * @brief Метод разбора одной логической строки текста
 *
 * @param line разбираемая строка без знака конца строки
 * @return     признак успешного разбора строки
 *
 */
bool awh::codec::yaml::Reader::record(const string_view line) noexcept {
	// Выполняем учёт разбираемой строки
	this->_line++;
	/**
	 * Если к разбираемой строке присоединены строки склейкой
	 *
	 * @note Учёт ведётся по строкам телесным: логическая строка одна, а телесных за нею
	 *       столько, сколько их склейка свела
	 */
	if(this->_joined > 0){
		// Выполняем учёт присоединённых строк
		this->_line += this->_joined;
		// Выполняем сброс количества присоединённых строк
		this->_joined = 0;
	}
	// Выполняем сброс признака разбора свойств узла в этой строке
	this->_propped = false;
	// Выполняем сброс признака объявления метки узла в разбираемой строке
	this->_anchoredHere = false;
	// Выполняем сброс признака объявления метки типа в разбираемой строке
	this->_taggedHere = false;
	// Выполняем сброс признака подачи в отступе вложенного построения
	this->_tabbed = false;
	/**
	 * Если разбирается поточное построение, скобками ещё не закрытое
	 *
	 * @note Строка эта построению и принадлежит целиком: ни отступ её, ни черта начала
	 *       документа смысла здесь не имеют, ибо внутри скобок отступ не значит ничего
	 */
	if(!this->_flow.empty()){
		// Смещение начала разбора строки
		size_t offset = 0;
		/**
		 * Выполняем пропуск пробельных знаков отступа строки
		 */
		while((offset < line.size()) && spacing(line[offset]))
			// Выполняем переход к следующему знаку строки
			offset++;
		/**
		 * Если строка продолжения несёт черту начала либо конца документа
		 *
		 * @details Черты эти внутри скобок содержимым не являются и построения не
		 *          закрывают: описание запрещает их там прямо. Прежде запись
		 *          `[\n--- ,\n...\n]` принималась перечнем из значений `---` да `...`
		 *
		 * @note Нашло это сличение с набором yaml-test-suite
		 */
		if((offset == 0) && ((line.compare(0, 3, "---") == 0) || (line.compare(0, 3, "...") == 0)) &&
		   ((line.size() == 3) || spacing(line[3])))
			// Выводим отказ недопустимого знака в этом месте текста
			return this->fail(error_t::INVALID_CHARACTER, 0);
		/**
		 * Если строка продолжения глубже объемлющего построения не стоит
		 *
		 * @details Содержимое поточного построения обязано стоять глубже построения
		 *          блочного, его объемлющего: без того запись `flow: [a,` со строкою `b` с
		 *          начала строки читалась бы и продолжением построения, и парою нового
		 *          отображения. Прежде отступ продолжения не сличался вовсе
		 *
		 * @note Построение, стоящее содержимым документа целиком, под правило это не
		 *       подпадает - блочных уровней над ним нет. Нашло это сличение с набором
		 *       yaml-test-suite
		 */
		/**
		 * Отступ строки продолжения, одними пробелами набранный
		 *
		 * @note Отступ описанием задан пробелами, и знак горизонтальной подачи в счёт его
		 *       не идёт: подача отделяет содержимое от отступа, отступом не будучи. Оттого
		 *       написание `- [` с подачами перед содержимым строкою ниже глубже перечня не
		 *       стоит вовсе. Случай Y79Y набора yaml-test-suite
		 */
		size_t margin = 0;
		/**
		 * Выполняем счёт пробелов отступа строки продолжения
		 */
		while((margin < line.size()) && (line[margin] == ' '))
			// Выполняем переход к следующему знаку строки
			margin++;
		if(!this->_levels.empty() && (offset < line.size()) &&
		   (margin <= static_cast <size_t> (this->_levels.back().indent)))
			// Выводим отказ отступа, ни одному из открытых уровней не отвечающего
			return this->fail(error_t::INVALID_INDENTATION, margin);
		// Выполняем возврат к началу строки продолжения построения
		offset = 0;
		/**
		 * Если разобрать продолжение поточного построения не удалось
		 */
		if(!this->flowing(line, offset))
			// Выводим признак неудачного разбора строки
			return false;
		/**
		 * Если построение скобками закрыто, а строка исчерпана не вся
		 */
		if(this->_flow.empty()){
			/**
			 * Выполняем пропуск пробельных знаков за поточным построением
			 */
			while((offset < line.size()) && spacing(line[offset]))
				/**
				 * @warning Тело это истины не принимает ни при одном написании: `flowing` начинает всякий
				 *          оборот перебора с пропуска пробельных знаков, а единственный выход его с опустевшею
				 *          стопою скобок стоит за этим пропуском. Оттого смещение, им возвращённое, на пробел
				 *          не указывает никогда. Замерено написаниями `[1] # c`, `[1] `, `[1]\t`, `[1,\n2] # c`
				 */
				// Выполняем переход к следующему знаку строки
				offset++;
			/**
			 * Если за построением стоит примечание
			 *
			 * @note Примечание опознаётся лишь за пробельным знаком: запись `]#invalid`
			 *       примечания не открывает, а является содержимым за завершённым
			 *       построением - и отвергается отказом. Нашло это сличение с набором
			 *       yaml-test-suite
			 */
			if((offset < line.size()) && (line[offset] == '#') &&
			   ((offset == 0) || spacing(line[offset - 1])))
				// Выполняем постановку события примечания
				this->remark(line, offset);
			/**
			 * Если за построением стоит содержимое, примечанием не являющееся
			 */
			else if(offset < line.size())
				// Выводим отказ содержимого за завершённой записью
				return this->fail(error_t::TRAILING_CHARACTERS, offset);
		}
		// Выполняем перенос собранных событий строки в очередь выдачи
		this->commit();
		// Выводим признак успешного разбора строки
		return true;
	}
	/**
	 * Если собирается простое значение, могущее прирасти
	 */
	if(this->_plaining){
		// Признак присоединения строки к простому значению
		bool attached = false;
		/**
		 * Если присоединить строку к простому значению не удалось
		 */
		if(!this->plaining(line, attached))
			// Выводим признак неудачного разбора строки
			return false;
		/**
		 * Если строка присоединена к простому значению
		 */
		if(attached){
			// Выполняем перенос собранных событий строки в очередь выдачи
			this->commit();
			// Выводим признак успешного разбора строки
			return true;
		}
		/**
		 * Если выдать собранное простое значение не удалось
		 *
		 * @note Строка, значению не принадлежащая, завершает его и разбирается затем
		 *       обычным порядком - здесь же, ниже
		 */
		if(!this->settle())
			// Выводим признак неудачного разбора строки
			return false;
	}
	/**
	 * Если собирается блочное значение
	 */
	if(this->_blocking){
		// Признак присоединения строки к блочному значению
		bool attached = false;
		/**
		 * Если присоединить строку к блочному значению не удалось
		 */
		if(!this->blocking(line, attached))
			// Выводим признак неудачного разбора строки
			return false;
		/**
		 * Если строка присоединена к блочному значению
		 */
		if(attached){
			// Выполняем перенос собранных событий строки в очередь выдачи
			this->commit();
			// Выводим признак успешного разбора строки
			return true;
		}
		/**
		 * Если завершить блочное значение не удалось
		 *
		 * @note Строка, блочному значению не принадлежащая, завершает его и разбирается
		 *       затем обычным порядком - здесь же, ниже
		 */
		if(!this->closing(0))
			// Выводим признак неудачного разбора строки
			return false;
		/**
		 * Смещение содержимого строки, блочное значение завершившей
		 *
		 * @note Отступ пропускается ради розыска разделителя пары: строка эта разбирается
		 *       ниже обычным порядком, и своего смещения там она получит заново
		 */
		size_t leading = 0;
		/**
		 * Выполняем пропуск отступа строки, блочное значение завершившей
		 */
		while((leading < line.size()) && (line[leading] == ' '))
			// Выполняем переход к следующему знаку строки
			leading++;
		/**
		 * Если строка, блочное значение завершившая, разделителем пары открывается
		 *
		 * @details Описание берёт имя пары правилом `ns-s-implicit-yaml-key`, а тому
		 * дозволено одно лишь скалярное значение поточного написания в одну строку:
		 * значение блочное именем пары быть не вправе вовсе. Разделитель, за блоком
		 * стоящий, именно это и означает - блок обращается именем пары
		 *
		 * @warning Отказ этот стоит ЗДЕСЬ, а не в разборе строки ниже: событие блочного
		 *          значения уже поставлено закрытием выше, и разбор строки выдал бы за
		 *          ним пару свою - дерево сложило бы их вкривь, приняв блок именем пары
		 *          следующей. Написание `x:\n! |\n a\n: b` тем и давало дерево, где
		 *          именем пары стоит содержимое блока, а значение `b` пропадало вовсе
		 *
		 * @note Написание то же в одиночку отвергалось и прежде - отказом отступа, а не
		 *       правилом имени: блок, парой не предварённый, отступа своего не получает.
		 *       Правило это закрывает и написание, блоку предшествующей парой открытое
		 *
		 * @warning Имя ЯВНОЕ под правило не подпадает: черта `?` объявляет имя пары
		 *          отдельно, и описание правилом `c-l-block-map-explicit-key` дозволяет
		 *          ему всякое значение, блочное включая. Признак `_expected` их и
		 *          различает: у имени явного значение пары ещё ожидается, а у блока,
		 *          парой предшествующей открытого, ожидание снято его же приходом.
		 *          Случаи 5WE3 и KK5P набора yaml-test-suite тому порукой
		 */
		if((leading < line.size()) && (line[leading] == ':') &&
		   (((leading + 1) >= line.size()) || spacing(line[leading + 1])) &&
		   this->_flow.empty() && !this->_expected)
			// Выводим отказ недопустимого знака в этом месте текста
			return this->fail(error_t::INVALID_CHARACTER, leading);
	}
	// Смещение начала содержимого строки за отступом
	size_t offset = 0;
	/**
	 * Выполняем пропуск отступа разбираемой строки
	 */
	while((offset < line.size()) && (line[offset] == ' '))
		// Выполняем переход к следующему знаку строки
		offset++;
	/**
	 * Отступ разбираемой строки, одними пробелами набранный
	 *
	 * @note Описание задаёт отступ правилом `s-indent`, а тот пробелами набирается: знак
	 *       горизонтальной подачи отступом не является вовсе, и в счёт его не идёт.
	 *       Отделять же им содержимое от отступа описание дозволяет - правилом
	 *       `s-separate-in-line`
	 */
	const uint32_t indent = static_cast <uint32_t> (offset);
	/**
	 * Если за отступом стоит знак горизонтальной подачи
	 *
	 * @details Подача содержимое от отступа отделяет, отступа ему не давая. Скаляру того
	 *          довольно - отступа он не задаёт, - а построение блочное отступ свой берёт
	 *          именно отсюда, и подача его лишает. Прежде подача за отступом отвергалась
	 *          всякая, и верное написание `foo:` со строкою ` <подача>bar` отказ получало
	 *
	 * @note Нашло это сличение с набором yaml-test-suite
	 */
	if((offset < line.size()) && (line[offset] == '\t')){
		/**
		 * Выполняем пропуск пробельных знаков за отступом
		 */
		while((offset < line.size()) && spacing(line[offset]))
			// Выполняем переход к следующему знаку строки
			offset++;
		/**
		 * Если за пробельными знаками стоит содержимое
		 */
		if((offset < line.size()) && (line[offset] != '#'))
			// Запоминаем признак подачи в отступе построения
			this->_tabbed = true;
	}
	/**
	 * Запоминаем отступ разбираемой строки
	 *
	 * @note Отступ этот нужен блочному значению: содержимое его обязано стоять глубже
	 *       отступа строки, заголовок несущей, а не глубже столбца самого заголовка
	 */
	this->_margin = indent;
	/**
	 * Если строка пуста
	 */
	if(offset >= line.size()){
		/**
		 * Если выдача пустых строк затребована
		 */
		if(this->_settings.emitBlanks && this->_opened)
			// Выполняем постановку события пустой строки
			this->emit(event_t::BLANK, offset);
		// Выполняем перенос собранных событий строки в очередь выдачи
		this->commit();
		// Выводим признак успешного разбора строки
		return true;
	}
	/**
	 * Если строка несёт одно лишь примечание
	 */
	if(line[offset] == '#'){
		// Выполняем постановку события примечания
		this->remark(line, offset);
		// Выполняем перенос собранных событий строки в очередь выдачи
		this->commit();
		// Выводим признак успешного разбора строки
		return true;
	}
	/**
	 * Если строка объявляет начало нового документа
	 */
	if((line.compare(offset, 3, "---") == 0) && (((offset + 3) >= line.size()) || spacing(line[offset + 3]))){
		/**
		 * Если закрыть открытый документ не удалось
		 */
		if(!this->finish(offset))
			// Выводим признак неудачного разбора строки
			return false;
		// Выполняем постановку события начала документа
		this->emit(event_t::DOCUMENT_START, offset);
		// Запоминаем признак открытия документа
		this->_opened = true;
		// Запоминаем признак документа, чертою открытого
		this->_dashed = true;
		// Выполняем сброс признака наполнения документа
		this->_filled = false;
		/**
		 * Выполняем сброс признака предпосланных директив
		 *
		 * @note Директивы, черте предшествовавшие, относятся к документу, ею открытому, и
		 *       ожидание черты они исполнили
		 */
		this->_directed = false;
		// Получаем смещение содержимого за объявлением документа
		size_t position = (offset + 3);
		/**
		 * Выполняем пропуск пробельных знаков за объявлением документа
		 */
		while((position < line.size()) && spacing(line[position]))
			// Выполняем переход к следующему знаку строки
			position++;
		// Запоминаем признак разбора содержимого на строке черты начала документа
		this->_headed = true;
		// Признак успешного разбора содержимого за объявлением документа
		const bool parsed = this->content(line, position, static_cast <uint32_t> (position));
		// Выполняем сброс признака разбора содержимого на строке черты начала документа
		this->_headed = false;
		/**
		 * Если разобрать содержимое за объявлением документа не удалось
		 */
		if(!parsed)
			// Выводим признак неудачного разбора строки
			return false;
		// Выполняем перенос собранных событий строки в очередь выдачи
		this->commit();
		// Выводим признак успешного разбора строки
		return true;
	}
	/**
	 * Если строка объявляет конец документа
	 */
	if((line.compare(offset, 3, "...") == 0) && (((offset + 3) >= line.size()) || spacing(line[offset + 3]))){
		// Смещение содержимого за чертою конца документа
		size_t following = (offset + 3);
		/**
		 * Выполняем пропуск пробельных знаков за чертою конца документа
		 */
		while((following < line.size()) && spacing(line[following]))
			// Выполняем переход к следующему знаку строки
			following++;
		/**
		 * Если за чертою конца документа стоит содержимое
		 *
		 * @details Черта конца документа занимает строку свою целиком: описанием за нею
		 *          дозволено одно примечание. Прежде содержимое за нею отбрасывалось
		 *          молча - запись `... invalid` принималась чертою, а слово `invalid`
		 *          пропадало из потока бесследно
		 *
		 * @note Нашло это сличение с набором yaml-test-suite
		 */
		if((following < line.size()) && (line[following] != '#') && (line[following] != '\n'))
			// Выводим отказ содержимого за завершённой записью
			return this->fail(error_t::TRAILING_CHARACTERS, following);
		/**
		 * Если закрыть открытый документ не удалось
		 */
		if(!this->finish(offset))
			// Выводим признак неудачного разбора строки
			return false;
		// Выполняем перенос собранных событий строки в очередь выдачи
		this->commit();
		// Выводим признак успешного разбора строки
		return true;
	}
	/**
	 * Если строка объявляет директиву
	 */
	if(line[offset] == '%'){
		/**
		 * Если разобрать директиву не удалось
		 */
		if(!this->directive(line, offset))
			// Выводим признак неудачного разбора строки
			return false;
		// Выполняем перенос собранных событий строки в очередь выдачи
		this->commit();
		// Выводим признак успешного разбора строки
		return true;
	}
	/**
	 * Если документ ещё не открыт
	 */
	if(!this->_opened){
		/**
		 * Если документу предпосланы директивы
		 *
		 * @note Описание велит документу с директивами открываться чертою прямо: без неё
		 *       неведомо, где кончаются директивы и начинается содержимое, и `%TAG`
		 *       оказался бы отнесён неизвестно к чему
		 */
		if(this->_directed)
			// Выводим отказ ошибочного построения директивы
			return this->fail(error_t::INVALID_DIRECTIVE, offset);
		// Выполняем постановку события начала документа
		this->emit(event_t::DOCUMENT_START, offset);
		// Запоминаем признак открытия документа
		this->_opened = true;
		// Выполняем сброс признака документа, чертою открытого
		this->_dashed = false;
		// Выполняем сброс признака наполнения документа
		this->_filled = false;
	/**
	 * Если документ открыт и содержимое его уже прочитано
	 */
	} else if(this->_filled && this->_levels.empty() && !this->_expected)
		// Выводим отказ содержимого за завершённой записью
		return this->fail(error_t::TRAILING_CHARACTERS, offset);
	/**
	 * Если свойства узла не дождались узла своего
	 *
	 * @details Строка, одними свойствами занятая, узла не несёт: узел ждёт их строкою
	 *          ниже. Сброс признака подачи значения терял тогда ожидание вовсе, и
	 *          написание `имя:`, `&метка`, `- запись` отвергалось отступом, ни одному
	 *          уровню не отвечающим
	 *
	 * @note Строка примечания под правило не подпадала - примечание признака этого не
	 *       трогает, - и оттого расхождение видно было лишь на свойствах
	 */
	if(this->_anchor.empty() && this->_tag.empty())
		// Выполняем сброс признака подачи значения пары, объявленной прежде
		this->_awaited = false;
	/**
	 * Если ожидалось значение пары, а отступ строки глубже отступа имени её
	 */
	if(this->_expected && (indent > this->_pending)){
		// Выполняем сброс признака ожидания значения пары
		this->_expected = false;
		// Запоминаем признак подачи значения пары, объявленной прежде
		this->_awaited = true;
	}
	/**
	 * Признак того, что строка объявляет очередное значение перечня
	 *
	 * @note Знать это надлежит прежде выдачи пустого значения пары: перечень, стоящий на
	 *       отступе имени своей пары, есть значение её, а не пустота вместо него
	 */
	const bool entry = ((line[offset] == '-') && (((offset + 1) >= line.size()) || spacing(line[offset + 1])));
	/**
	 * Признак того, что перечень строки есть значение пары, объявленной прежде
	 *
	 * @note Значением её он является лишь на отступе имени её самой: черта, стоящая
	 *       отступом мельче, к паре отношения не имеет вовсе, и пустоту значения её
	 *       надлежит выдать прежде закрытия уровней
	 */
	const bool implied = (entry && !this->_entered && (indent == this->_pending));
	/**
	 * Признак того, что строка объявляет значение имени, вопросом объявленного
	 *
	 * @note Знать это надлежит прежде выдачи пустого значения: двоеточие на отступе вопроса
	 *       есть значение имени его, а не строка, ожидание обрывающая. Без признака этого
	 *       имя, вопросом объявленное, получало бы пустоту прежде своего значения
	 */
	const bool answer = (this->_asked && (line[offset] == ':') &&
	 (((offset + 1) >= line.size()) || spacing(line[offset + 1])) && (indent == this->_pending));
	/**
	 * Если ожидалось значение пары, а строка стоит на отступе имени её, перечнем не являясь
	 *
	 * @details Выдаётся оно прежде закрытия уровней, а не за ним: значение принадлежит
	 *          отображению, имя своё несущему, и выданное за концом его легло бы именем
	 *          пары уровня объемлющего. Нашёл это ворошитель сличением перезаписи: запись
	 *          `''` становилась именем следующей пары, а значение её - значением пустоты
	 *
	 * @note Ожидание записи перечня чертою не снимается: черта на отступе ожидания есть
	 *       запись следующая, и пустоту прежней записи надлежит выдать прежде неё
	 */
	if(this->_expected && !implied && (!answer || !this->_answering) && (indent <= this->_pending)){
		// Выполняем сброс признака ожидания значения пары
		this->_expected = false;
		/**
		 * Если пустота эта принадлежит имени, вопросом объявленному
		 *
		 * @details Имя, вопросом объявленное, вправе быть построением, и построение это
		 *          стоит отступом глубже вопроса своего. Пустота значения принадлежит
		 *          отображению вопроса, а не построению имени его: выданная прежде
		 *          закрытия уровней, она легла бы записью перечня имени либо парою
		 *          отображения его
		 *
		 * @note Закрывается построение счётом уровней, а не отступом: отступ строки
		 *       мельче вопроса, и закрытие по отступу снесло бы заодно и само
		 *       отображение вопроса, пустоту принять некому. Случаи KK5P и M2N8 набора
		 *       yaml-test-suite
		 */
		if(this->_asked && this->_answering){
			// Выполняем сброс признака имени, вопросом объявленного
			this->_asked = false;
			/**
			 * Выполняем закрытие всех уровней, за вопросом открытых
			 */
			while(this->_levels.size() > this->_asking){
				// Получаем вид закрываемого уровня вложенности
				const nesting_t kind = this->_levels.back().kind;
				// Выполняем снятие закрываемого уровня со стопы
				this->_levels.pop_back();
				// Выполняем постановку события закрытия уровня
				this->emit(((kind == nesting_t::MAPPING) ? event_t::MAPPING_END : event_t::SEQUENCE_END), offset);
			}
		}
		/**
		 * Если поставить событие пустого значения не удалось
		 */
		if(!this->scalar(string(), style_t::PLAIN, offset))
			// Выводим признак неудачного разбора строки
			return false;
		// Устанавливаем вид пустого значения последнему событию
		this->emptied();
		/**
		 * Устанавливаем место пустого значения там, где оно ожидалось
		 *
		 * @details Выдаётся пустота не там, где ожидалась, а там, где ожидание оборвалось -
		 *          строкою ниже, чертою следующей записи. Место события есть место
		 *          значения, и без поправки пустота записи `-` получала бы место соседа
		 *
		 * @note Наружу это торчит удержанием исходного текста: начала записей узлов
		 *       сдвигались на строку, и перезапись правки теряла запись перечня. Нашёл это
		 *       ворошитель правкой дерева на перечне из трёх пустых записей
		 */
		this->_staged.back().location.offset = this->_awaiting.offset;
		// Устанавливаем строку пустого значения там, где оно ожидалось
		this->_staged.back().location.line = this->_awaiting.line;
		// Устанавливаем столбец пустого значения там, где оно ожидалось
		this->_staged.back().location.column = this->_awaiting.column;
		/**
		 * Если пустота эта была именем, вопросом объявленным
		 *
		 * @details Имя своё вопрос получил здесь же, пустотою, а значения ему никто так и
		 *          не дал: написание `? &метка` со строкою, ожидание обрывающей, есть пара
		 *          из имени пустого с меткою и значения пустого без неё
		 *
		 * @note Двоеточие ответа сюда не подпадает: значение своё имя получит от него, и
		 *       выданная здесь пустота легла бы значением лишним. Случай PW8X набора
		 *       yaml-test-suite
		 */
		if(this->_asked && !answer){
			// Выполняем сброс признака имени, вопросом объявленного
			this->_asked = false;
			/**
			 * Если поставить событие пустого значения не удалось
			 *
			 * @warning Заход этот НЕДОСТИЖИМ, покуда держится условие: событие пустоты ставится
			 *          там, где метки вида уже нет, а без метки разрешение вида отказа не даёт -
			 *          запись пустая ни предела длины не превышает, ни метки порядка байтов не
			 *          несёт. Замерено шестнадцатью записями с меткою `!!bool` над пустотою
			 *          построения поточного: ни одна сюда не дошла - метку забирает заход
			 *          скалярного значения раньше
			 *
			 * @note Сносу заход не подлежит: у закрытия документа метка до пустоты доживает, и
			 *       там отказ этот управление получает - проверка `TagsAndAnchors` тому порукой
			 */
			if(!this->scalar(string(), style_t::PLAIN, offset))
				// Выводим признак неудачного разбора строки
				return false;
			// Устанавливаем вид пустого значения последнему событию
			this->emptied();
			// Устанавливаем место пустого значения там, где оно ожидалось
			this->_staged.back().location.offset = this->_awaiting.offset;
			// Устанавливаем строку пустого значения там, где оно ожидалось
			this->_staged.back().location.line = this->_awaiting.line;
			// Устанавливаем столбец пустого значения там, где оно ожидалось
			this->_staged.back().location.column = this->_awaiting.column;
		}
	}
	/**
	 * Если закрыть уровни глубже отступа строки не удалось
	 *
	 * @warning Заход этот НЕДОСТИЖИМ, покуда держится условие: закрытие уровней отказа
	 *          не даёт ни при каком написании - у `collapse` выход один, и тот успех.
	 *          Замерено покрытием: заход не задет ни разу
	 *
	 * @note Сносу заход не подлежит: заведись у закрытия случай негодный - разбор пошёл
	 *       бы дальше с уровнями, оставшимися открытыми
	 */
	if(!this->collapse(indent, offset))
		// Выводим признак неудачного разбора строки
		return false;
	/**
	 * Если содержимое документа прочитано, а строка несёт ещё
	 *
	 * @details Проверка эта повторяет ту, что стоит прежде закрытия уровней, и повторяет
	 *          не зря: написание ` - a` со строкою `- b` за ним закрывает перечень отступа
	 *          мельче и открывает новый - а документ корень имеет один, и второго ему не
	 *          положено. Прежде закрытия уровень ещё открыт, и проверка та молчит. Нашёл
	 *          это ворошитель сличением дословной перезаписи: дерево клало второй перечень
	 *          вторым корнем, и счёт документов расходился с числом их в тексте
	 */
	if(this->_filled && this->_levels.empty() && !this->_expected && !this->_plaining)
		// Выводим отказ содержимого за завершённой записью
		return this->fail(error_t::TRAILING_CHARACTERS, offset);
	/**
	 * Если разобрать содержимое строки за отступом не удалось
	 */
	if(!this->content(line, offset, indent))
		// Выводим признак неудачного разбора строки
		return false;
	/**
	 * Если метка, вместилищу отложенная, вместилища своего не дождалась
	 *
	 * @details Откладывание оправдано лишь тем, что строка вместилище открывает: метка
	 *          строкою выше достаётся вместилищу, а метка этой строки - имени пары его.
	 *          Строка же, вместилища не открывшая, несёт узел один, и двух меток он не
	 *          несёт: написание `top: &m` со строкою `&v значение` ниже есть две метки
	 *          одному простому значению, и описание того не дозволяет
	 *
	 * @note Нашло это сличение с набором yaml-test-suite: случай 4JVG отказа требует,
	 *       а соседний 7BMT тем же написанием законен - разнятся они лишь тем, что
	 *       строка нижняя открывает отображение либо не открывает его вовсе
	 */
	if(!this->_delayed.empty() || !this->_delayedTag.empty())
		// Выводим отказ недопустимого знака в этом месте текста
		return this->fail(error_t::INVALID_CHARACTER, offset);
	/**
	 * Если имя, вопросом объявленное, собрано, а значения его ещё нет
	 *
	 * @details Признак ожидания у имени и у значения его один и тот же, и разбор имени его
	 *          снимает. Возвращается он здесь, дабы имя, значения своего не дождавшееся,
	 *          получило пустоту: написание `? имя` со следующим вопросом строкою ниже
	 *          читалось прежде одною парою, где второе имя легло значением первого
	 *
	 * @note Отступ ожидания берётся у вопроса, а не у имени: имя вправе стоять и строкою
	 *       ниже, отступом глубже, а двоеточие значения стоит отступом вопроса
	 */
	if(this->_asked && !this->_expected){
		// Запоминаем признак ожидания значения имени, вопросом объявленного
		this->_expected = true;
		// Запоминаем признак того, что ожидается именно значение имени
		this->_answering = true;
		// Выполняем сброс признака принадлежности ожидаемого значения записи перечня
		this->_entered = false;
		// Запоминаем отступ, на котором ожидается значение имени
		this->_pending = this->_questioned;
	}
	// Выполняем перенос собранных событий строки в очередь выдачи
	this->commit();
	// Выводим признак успешного разбора строки
	return true;
}
/**
 * @brief Метод подачи очередного куска исходного текста
 *
 * @param buffer подаваемый кусок исходного текста
 * @param size   размер подаваемого куска
 * @param end    признак того, что текст окончен
 * @return       признак успешного разбора поданного куска
 *
 */
bool awh::codec::yaml::Reader::feed(const void * buffer, const size_t size, const bool end) noexcept {
	/**
	 * Если разбор уже прекращён отказом
	 */
	if(this->_state == state_t::FAILED)
		// Выводим признак неудачного разбора поданного куска
		return false;
	/**
	 * Если текст уже разобран до конца
	 */
	if(this->_state == state_t::FINISHED)
		// Выводим отказ содержимого за завершённой записью
		return this->fail(error_t::TRAILING_CHARACTERS, 0);
	// Запоминаем состояние разбора текста
	this->_state = state_t::PARSING;
	/**
	 * Если начало потока ещё не выдано
	 */
	if(!this->_started){
		// Выполняем постановку события начала потока
		this->emit(event_t::STREAM_START, 0);
		// Выполняем перенос собранного события в очередь выдачи
		this->commit();
		// Запоминаем признак выдачи начала потока
		this->_started = true;
	}
	// Признак успешного приведения поданного куска к UTF-8
	const bool converted = this->_decoder.convert(buffer, size, end, this->_buffer);
	/**
	 * Признак того, что текст окончен и приведён целиком
	 *
	 * @details Приведение переносит в накопитель всё, что успело прочесть до битой
	 * последовательности, и строки те разобрать надлежит: при подаче по байту они
	 * разобраны были бы прежними кусками, и отказ пришёл бы уже за ними. Строка же
	 * последняя, переводом не закрытая, разбору не подлежит - прирасти ей уже нечем,
	 * но и признать текст оконченным нельзя: окончен он отказом, а не концом своим
	 */
	const bool complete = (end && converted);
	/**
	 * Признак того, что накопителю прирасти уже нечем
	 *
	 * @details Отсрочка решения о возврате каретки последнем ждёт следующего куска, а
	 * ждать его вправе лишь тогда, когда кусок этот будет. Провал приведения кодировки
	 * подачу обрывает отказом строкою ниже, и накопитель за ним не прирастает уже
	 * никогда: возврат, отсрочку получивший, остался бы неразобранным навсегда
	 *
	 * @warning Признак этот от `complete` отличен намеренно: `complete` требует УДАЧИ
	 *          приведения, а здесь важна лишь невозможность прироста. Судя отсрочку
	 *          признаком `end`, подача текста `e>\r\x8b` кусками теряла строку `e>`
	 *          целиком - целиком поданный тот же текст выдавал её события, а поданный
	 *          по байту не выдавал ни одного
	 */
	const bool sealed = (end || !converted);
	/**
	 * Выполняем разбор всех строк, поданных целиком
	 */
	while(this->_offset < this->_buffer.size()){
		// Признак отложенного решения о возврате каретки последнем
		bool deferred = false;
		// Разыскиваем знак конца очередной строки
		const size_t position = terminator(this->_buffer, this->_offset, sealed, deferred);
		/**
		 * Если решение о возврате каретки последнем отложено
		 *
		 * @note Разбирать строку сейчас значило бы решать о возврате прежде, чем известно,
		 *       стоит ли за ним перевод строки: следующий кусок вправе его принести
		 */
		if(deferred)
			// Выходим из разбора строк накопителя
			break;
		/**
		 * Если знака конца строки в накопителе нет вовсе
		 */
		if(position == string::npos){
			/**
			 * Если текст ещё не окончен
			 *
			 * @note Строка вправе прирасти следующим куском, и разбирать её сейчас значило
			 *       бы ставить исход разбора в зависимость от нарезки текста
			 */
			if(!complete)
				// Выходим из разбора строк накопителя
				break;
			// Получаем последнюю строку накопителя
			string_view line(this->_buffer.data() + this->_offset, (this->_buffer.size() - this->_offset));
			/**
			 * Если строка оканчивается возвратом каретки
			 */
			if(!line.empty() && (line.back() == '\r'))
				// Выполняем снятие возврата каретки с конца строки
				line = line.substr(0, (line.size() - 1));
			// Запоминаем смещение начала неразобранного текста
			const size_t consumed = this->_offset;
			// Запоминаем смещение разбираемой строки от начала текста
			this->_position = static_cast <uint64_t> (consumed);
			// Выполняем переход за разобранную строку
			this->_offset = this->_buffer.size();
			/**
			 * Если разобрать последнюю строку не удалось
			 */
			if(!this->record(line))
				// Выводим признак неудачного разбора поданного куска
				return false;
			// Выходим из разбора строк накопителя
			break;
		}
		// Получаем смещение знака конца логической строки
		size_t ending = position;
		// Выполняем сброс количества строк, к разбираемой присоединённых
		this->_joined = 0;
		// Выполняем сброс признака огранённого значения в несколько строк
		this->_stretched = false;
		/**
		 * Выполняем сброс наименьшего отступа присоединённых строк
		 *
		 * @note Сбрасывается он наибольшим числом, а не обозначением отсутствия отступа:
		 *       обозначение это нулём и является, а нуль наименьшим из отступов быть вправе
		 */
		this->_shallow = static_cast <uint32_t> (~0u);
		// Смещение содержимого разбираемой строки за отступом её
		size_t leading = this->_offset;
		/**
		 * Выполняем пропуск отступа разбираемой строки
		 */
		while((leading < ending) && (this->_buffer.at(leading) == ' '))
			// Выполняем переход к следующему знаку строки
			leading++;
		/**
		 * Признак того, что разбираемая строка продолжает простое значение
		 *
		 * @details Продолжение простого значения кавычки оградою не несёт: описание числит
		 *          её знаком содержимого, ибо ограда открывается лишь на месте значения.
		 *          Склейка же, кавычку эту оградою сочтя, глотала строку следующую и валила
		 *          разбор отказом «знак недопустим»
		 *
		 * @warning Обнаружилось это зависимостью исхода от хвостового перевода строки:
		 *          `a: x\n \"\nb: 1` без перевода принимался, а с переводом отвергался.
		 *          Причина в том, что последняя строка, перевода не имеющая, склейке не
		 *          подлежит вовсе, и порок склейки на ней не проявлялся
		 *
		 * @note Сличение отступом обязательно: признак сборки простого значения держится и
		 *       на строке, значение это ЗАВЕРШАЮЩЕЙ, - строке с новым именем пары. Той
		 *       склейка нужна, ибо значение её вправе быть огранённым в несколько строк
		 */
		/**
		 * @warning Отступ сличается СТРОГО лишь при открытом построении: значение, корнем
		 *          документа стоящее, построений над собою не имеет, и продолжению его
		 *          дозволен отступ нулевой - тот же, что у самого значения. Требуя строгого
		 *          превышения и там, склейка числила продолжение строкою чужой и лезла
		 *          сводить его оградою: написание `b\n"в #\n-` с переводом хвостовым
		 *          сводило строки вторую с третьей, а примечание рубило сведённое - строка
		 *          `-` пропадала молча, и текст, отвергаемый без перевода, с переводом
		 *          принимался
		 */
		const bool continued = (this->_plaining && ((static_cast <uint32_t> (leading - this->_offset) > this->_required) ||
		 (this->_levels.empty() && (static_cast <uint32_t> (leading - this->_offset) >= this->_required))));
		/**
		 * Если блочное значение не собирается, а строка простого не продолжает
		 *
		 * @note Строки блочного значения склейке не подлежат: кавычка внутри него оградою
		 *       не является вовсе, а собирается оно построчно само
		 */
		if(!this->_blocking && !continued){
			/**
			 * Выполняем присоединение строк, пока ограда значения не закрыта
			 */
			while(unclosed(string_view(this->_buffer.data() + this->_offset, (ending - this->_offset)))){
				// Признак отложенного решения о возврате каретки последнем
				bool postponed = false;
				// Разыскиваем знак конца следующей строки накопителя
				const size_t next = terminator(this->_buffer, (ending + 1), sealed, postponed);
				/**
				 * Если следующей строки в накопителе нет вовсе либо решение отложено
				 *
				 * @note Отсрочка ведёт себя здесь неразобранным концом строки: склейка ждёт
				 *       следующего куска ровно так же, как ждёт его строки, перевода не
				 *       имеющей
				 */
				if(postponed || (next == string::npos)){
					/**
					 * Если текст ещё не окончен
					 *
					 * @note Ограда закроется строкою, ещё не поданной, и разбирать сейчас
					 *       значило бы ставить исход разбора в зависимость от нарезки текста
					 */
					if(!end)
						// Выводим признак успешного разбора поданного куска
						return true;
					/**
					 * Выходим из присоединения строк
					 *
					 * @details Судится здесь окончание текста, а не признак `complete`:
					 *          последний несёт ещё и удачу приведения кодировки, и провал
					 *          приведения выглядел выходом с успехом - подача отвечала
					 *          удачей, отказ приведения оставался невыданным, а текст за
					 *          битою последовательностью пропадал молча. Отказ этот стоит
					 *          ниже, и дойти до него надлежит
					 *
					 * @note Нашёл это ворошитель поверкою состоявшегося сноса: дерево
					 *       выходило недостроенным, вместилища объявляли детей, каких не
					 *       накрывали, и снос внутри них пропадал из записи
					 */
					break;
				}
				/**
				 * Если присоединяемая строка чертою начала либо конца документа открывается
				 *
				 * @note Черты эти внутри значения описание запрещает правилом `c-forbidden`
				 *       прямо: присоединив такую строку, склейка проглотила бы документ,
				 *       за чертою стоящий
				 */
				const string_view following(this->_buffer.data() + (ending + 1), (next - (ending + 1)));
				/**
				 * Если строка чертою документа открывается
				 */
				if(((following.compare(0, 3, "---") == 0) || (following.compare(0, 3, "...") == 0)) &&
				   ((following.size() == 3) || spacing(following[3]) || (following[3] == '\r')))
					// Выходим из присоединения строк
					break;
				// Смещение начала содержимого присоединяемой строки
				size_t indent = 0;
				/**
				 * Выполняем пропуск отступа присоединяемой строки
				 */
				while((indent < following.size()) && (following[indent] == ' '))
					// Выполняем переход к следующему знаку строки
					indent++;
				// Смещение содержимого присоединяемой строки за пробельными знаками
				size_t content = indent;
				/**
				 * Выполняем пропуск пробельных знаков за отступом присоединяемой строки
				 *
				 * @note Пропуск идёт своим смещением, а не отступом: знак горизонтальной подачи
				 *       отступом не является вовсе - описание задаёт отступ правилом `s-indent`,
				 *       а тот пробелами набирается. Считая подачу отступом, склейка принимала бы
				 *       написание `foo: "bar` со строкою из одних подач, а описание его отвергает
				 */
				while((content < following.size()) && spacing(following[content]))
					// Выполняем переход к следующему знаку строки
					content++;
				/**
				 * Признак пустоты присоединяемой строки
				 *
				 * @note Строка пустая отступа своего не имеет вовсе: описание велит ей стать
				 *       переводом строки в собранном содержимом, а отступа с неё не требует.
				 *       Считая её отступ нулевым, склейка отвергала бы всякое значение, пустую
				 *       строку внутри себя несущее
				 */
				const bool empty = ((content >= following.size()) ||
				 (following[content] == '\r') || (following[content] == '\n'));
				/**
				 * Если отступ присоединяемой строки прежде намеренного мельче
				 *
				 * @note Отступ этот нужен сличению с отступом построения, значение объемлющего:
				 *       описание велит продолжению стоять глубже него, и мельчайший из отступов
				 *       решает о всей склейке разом
				 */
				if(!empty && (static_cast <uint32_t> (indent) < this->_shallow))
					// Запоминаем наименьший отступ присоединённых строк
					this->_shallow = static_cast <uint32_t> (indent);
				// Запоминаем смещение знака конца логической строки
				ending = next;
				// Запоминаем признак огранённого значения в несколько строк
				this->_stretched = true;
				// Увеличиваем количество строк, к разбираемой присоединённых
				this->_joined++;
			}
		}
		// Получаем очередную строку накопителя
		string_view line(this->_buffer.data() + this->_offset, (ending - this->_offset));
		/**
		 * Если строка оканчивается возвратом каретки
		 */
		if(!line.empty() && (line.back() == '\r'))
			// Выполняем снятие возврата каретки с конца строки
			line = line.substr(0, (line.size() - 1));
		// Запоминаем смещение разбираемой строки от начала текста
		this->_position = static_cast <uint64_t> (this->_offset);
		// Выполняем переход за разобранную строку
		this->_offset = (ending + 1);
		/**
		 * Если разобрать очередную строку не удалось
		 */
		if(!this->record(line))
			// Выводим признак неудачного разбора поданного куска
			return false;
	}
	/**
	 * Если привести поданный кусок к UTF-8 не удалось
	 */
	if(!converted)
		// Выводим отказ приведения кодировки исходного текста
		return this->fail(this->_decoder.error(), 0);
	/**
	 * Если текст окончен
	 */
	if(end){
		/**
		 * Если поточное построение скобками так и не закрыто
		 *
		 * @note Отказ этот объявляется здесь, а не строкою ниже: закрытие документа выдало
		 *       бы события закрытия построений, которых текст не содержит
		 */
		if(!this->_flow.empty())
			// Выводим отказ незакрытого поточного построения
			return this->fail(error_t::UNCLOSED_FLOW, 0);
		/**
		 * Если выдать собранное простое значение не удалось
		 */
		if(!this->settle())
			// Выводим признак неудачного разбора поданного куска
			return false;
		/**
		 * Если завершить собираемое блочное значение не удалось
		 */
		if(!this->closing(0))
			// Выводим признак неудачного разбора поданного куска
			return false;
		/**
		 * Если директивы объявлены, а документа за ними нет
		 *
		 * @details Директива есть принадлежность документа, и описание велит документу с
		 *          директивами открываться чертою прямо: без неё неведомо, где кончаются
		 *          директивы и начинается содержимое. Текст `%YAML 1.2` без черты
		 *          принимался прежде потоком без документов вовсе, и директива пропадала
		 *          молча
		 *
		 * @note Отказ этот отвечает и написанию `%YAML 1.2` с чертою конца за нею:
		 *       черта конца документа не открывает. Нашло это сличение с набором
		 *       yaml-test-suite
		 */
		if(this->_directed && !this->_opened)
			// Выводим отказ ошибочного построения директивы
			return this->fail(error_t::INVALID_DIRECTIVE, 0);
		/**
		 * Если закрыть открытый документ не удалось
		 */
		if(!this->finish(0))
			// Выводим признак неудачного разбора поданного куска
			return false;
		// Выполняем постановку события конца потока
		this->emit(event_t::STREAM_END, 0);
		// Выполняем перенос собранных событий в очередь выдачи
		this->commit();
		// Запоминаем состояние окончания разбора
		this->_state = state_t::FINISHED;
	}
	// Выводим признак успешного разбора поданного куска
	return true;
}
/**
 * @brief Метод подачи исходного текста целиком
 *
 * @param text подаваемый исходный текст
 * @return     признак успешного разбора поданного текста
 *
 */
bool awh::codec::yaml::Reader::feed(const string_view text) noexcept {
	// Выполняем подачу исходного текста целиком
	return this->feed(text.data(), text.size(), true);
}
/**
 * @brief Метод получения очередного события разбора
 *
 * @return признак того, что событие получено
 *
 */
bool awh::codec::yaml::Reader::next() noexcept {
	/**
	 * Если очередь собранных событий пуста
	 */
	if(this->_reading >= this->_events.size()){
		// Выполняем сброс события, выданного последним
		this->_current = item_t();
		// Выполняем сброс значения, выданного последним событием
		this->_content = content_t();
		/**
		 * Если текст разобран до конца
		 */
		if(this->_state == state_t::FINISHED)
			// Устанавливаем событие окончания разбора текста
			this->_current.event = event_t::FINISH;
		// Выводим признак того, что событий больше нет
		return false;
	}
	// Получаем очередное событие разбора
	this->_current = this->_events.at(this->_reading);
	// Выполняем снятие полученного события с очереди
	this->_reading++;
	// Устанавливаем вид значения полученного события
	this->_content.type = this->_current.type;
	// Устанавливаем вид записи значения полученного события
	this->_content.style = this->_current.style;
	// Устанавливаем положение значения в исходном тексте
	this->_content.location = this->_current.location;
	// Запоминаем признак того, что значение собрано внутри поточного построения
	this->_content.flow = this->_current.flow;
	// Устанавливаем схему, при выдаче события действовавшую
	this->_content.schema = this->_current.schema;
	// Устанавливаем признак того, что документ наречие своё директивой объявил
	this->_content.versioned = this->_current.versioned;
	// Устанавливаем содержимое значения полученного события
	this->_content.text = string_view(this->_storage.data() + this->_current.offset, this->_current.length);
	// Устанавливаем имя метки, событию предпосланной
	this->_content.anchor = string_view(this->_storage.data() + this->_current.anchor.offset, this->_current.anchor.length);
	// Устанавливаем метку типа, событию предпосланную
	this->_content.tag = string_view(this->_storage.data() + this->_current.tag.offset, this->_current.tag.length);
	// Выводим признак того, что событие получено
	return true;
}
